#!/usr/bin/env node
// ===========================================================================
// GALLA - THE APP ITSELF
// ---------------------------------------------------------------------------
// Everything behind the login. Until now the site was a brochure with a
// working login attached to it; this is the part a shopkeeper opens every
// morning.
//
// WHAT YOU GET
//
//   /app                 Home. Today's sales, money in, who owes you, what is
//                        running low, last seven days, and a short checklist
//                        while the shop is still being set up.
//
//   /app/billing         Making a bill. Type an item name, Enter, next item.
//                        GST works itself out as you type. Inline "add this
//                        as a new item" and "add this customer" so you never
//                        have to leave the screen half way through. Payment
//                        taken on the same screen. Save and print in one go.
//                        F2 item box, F4 customer box, Alt+S save,
//                        Alt+P save and print.
//
//   /app/bills           Every bill, with filters for unpaid, today, this
//                        week, this month. Open one to print it as A4 or as
//                        an 80mm receipt, send it on WhatsApp, take a
//                        payment, or cancel it.
//
//   /app/items           What you sell. Stock, cost, sale price, GST, low
//                        stock alerts. Correct the stock with a reason that
//                        gets written down, and see every movement of it.
//
//   /app/parties         Customers and suppliers, sorted by who owes the
//                        most. Open one for their bills, their payments, and
//                        a WhatsApp reminder already written.
//
// HOW IT TALKS TO THE BACKEND
//
//   Through lib/app-client.js, which sits on top of your existing
//   lib/api.js and leaves it alone. An earlier version of this installer
//   replaced lib/api.js, which broke the build: the AuthProvider imports
//   things from it that the replacement did not have. Running this puts the
//   original back and tidies up after that mistake.
//
//   Money is handled as whole paise everywhere, never as a decimal. The
//   totals you see while typing are worked out in the browser so they keep
//   up with you; the moment a bill is saved, what is shown and printed is
//   the server's own arithmetic. The browser's version is a preview and
//   never the record.
//
// BEFORE YOU RUN IT
//   The backend must be running on port 4000, as it already is.
//
// RUN FROM YOUR WEBSITE FOLDER (the one with app/ and components/):
//   node app.mjs
//
// Anything it replaces is backed up as <name>.bak. Safe to run twice.
// ===========================================================================

import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();

if (!fs.existsSync(path.join(ROOT, "package.json"))) {
  console.error("Stop - this does not look like the project root.");
  console.error("There is no package.json here. cd into the folder that has it, then run this again.");
  process.exit(1);
}

if (!fs.existsSync(path.join(ROOT, "components/account/AuthProvider.js"))) {
  console.error("Stop - this is not the website folder.");
  console.error("components/account/AuthProvider.js is missing.");
  console.error("Run wire.mjs first if you have not, or cd into the website folder (not backend).");
  process.exit(1);
}

// ---------------------------------------------------------------------------
// first: undo the lib/api.js replacement, if it happened
// ---------------------------------------------------------------------------
// The previous version of this installer overwrote lib/api.js and kept the
// original beside it as lib/api.js.bak. That file belongs to the login and
// account screens, which import names from it the replacement did not
// export, so the build stopped. Put it back, then remove the .bak so there
// is no spare copy lying about.
const apiPath = path.join(ROOT, "lib/api.js");
const apiBak = apiPath + ".bak";
const MARKER = "THE ONE PLACE THAT TALKS TO THE BACKEND";

if (fs.existsSync(apiPath) && fs.readFileSync(apiPath, "utf8").includes(MARKER)) {
  if (fs.existsSync(apiBak)) {
    fs.copyFileSync(apiBak, apiPath);
    fs.unlinkSync(apiBak);
    console.log("RESTORE lib/api.js - your original is back, lib/api.js.bak removed.");
  } else {
    console.error("");
    console.error("Stop - lib/api.js was replaced and there is no lib/api.js.bak to put back.");
    console.error("Recover it with:   git checkout lib/api.js");
    console.error("Then run this again.");
    process.exit(1);
  }
} else if (fs.existsSync(apiBak)) {
  // Already restored on an earlier run, or never broken. Either way the
  // spare copy has no job left.
  fs.unlinkSync(apiBak);
  console.log("TIDY  removed the leftover lib/api.js.bak");
}

const FILES = {"app/app/billing/page.js":"\"use client\";\n\nimport Shell from \"../../../components/app/Shell\";\nimport Billing from \"../../../components/app/billing/Billing\";\nimport { BILLING } from \"../../../components/app/content\";\n\nexport default function BillingPage() {\n  // flush, because the billing screen runs its own two-column layout right\n  // to the edges rather than sitting inside the usual page padding.\n  return (\n    <Shell title={BILLING.title} flush>\n      <Billing />\n    </Shell>\n  );\n}\n","app/app/bills/[id]/page.js":"\"use client\";\n\nimport { useParams } from \"next/navigation\";\nimport Shell from \"../../../../components/app/Shell\";\nimport BillDetail from \"../../../../components/app/bills/BillDetail\";\nimport { BILLS } from \"../../../../components/app/content\";\n\nexport default function Page() {\n  const { id } = useParams();\n\n  return (\n    <Shell title={BILLS.title}>\n      <BillDetail id={id} />\n    </Shell>\n  );\n}\n","app/app/bills/page.js":"\"use client\";\n\nimport Shell from \"../../../components/app/Shell\";\nimport BillsPage from \"../../../components/app/bills/BillsPage\";\nimport { BILLS } from \"../../../components/app/content\";\n\nexport default function Page() {\n  return (\n    <Shell title={BILLS.title}>\n      <BillsPage />\n    </Shell>\n  );\n}\n","app/app/items/page.js":"\"use client\";\n\nimport Shell from \"../../../components/app/Shell\";\nimport ItemsPage from \"../../../components/app/items/ItemsPage\";\nimport { ITEMS } from \"../../../components/app/content\";\n\nexport default function Page() {\n  return (\n    <Shell title={ITEMS.title}>\n      <ItemsPage />\n    </Shell>\n  );\n}\n","app/app/layout.js":"// ===========================================================================\n// /app - EVERYTHING BEHIND THE LOGIN\n// ---------------------------------------------------------------------------\n// This stays a server component so it can carry metadata, and it does only\n// one thing with it: keep the whole area out of search engines. These pages\n// are somebody's shop, not marketing. A stray crawl of /app would be at best\n// pointless and at worst an invitation.\n// ===========================================================================\n\nexport const metadata = {\n  title: \"Galla\",\n  robots: { index: false, follow: false, nocache: true },\n};\n\nexport default function AppLayout({ children }) {\n  return children;\n}\n","app/app/page.js":"\"use client\";\n\nimport Shell from \"../../components/app/Shell\";\nimport Dashboard from \"../../components/app/Dashboard\";\nimport { HOME } from \"../../components/app/content\";\n\nexport default function AppHomePage() {\n  return (\n    <Shell title={HOME.title}>\n      <Dashboard />\n    </Shell>\n  );\n}\n","app/app/parties/[id]/page.js":"\"use client\";\n\nimport { useParams } from \"next/navigation\";\nimport Shell from \"../../../../components/app/Shell\";\nimport PartyDetail from \"../../../../components/app/parties/PartyDetail\";\nimport { PARTIES } from \"../../../../components/app/content\";\n\nexport default function Page() {\n  // useParams rather than the page's own params prop: that prop is a promise\n  // in current Next, and this way the component stays plain.\n  const { id } = useParams();\n\n  return (\n    <Shell title={PARTIES.title}>\n      <PartyDetail id={id} />\n    </Shell>\n  );\n}\n","app/app/parties/page.js":"\"use client\";\n\nimport { Suspense } from \"react\";\nimport Shell from \"../../../components/app/Shell\";\nimport PartiesPage from \"../../../components/app/parties/PartiesPage\";\nimport { PARTIES } from \"../../../components/app/content\";\n\nexport default function Page() {\n  return (\n    <Shell title={PARTIES.title}>\n      {/* The list reads ?filter= from the URL, and Next wants anything using\n          the search params to sit inside a Suspense boundary. */}\n      <Suspense fallback={null}>\n        <PartiesPage />\n      </Suspense>\n    </Shell>\n  );\n}\n","components/app/Dashboard.js":"\"use client\";\n\n// ===========================================================================\n// HOME\n// ---------------------------------------------------------------------------\n// What a shopkeeper wants on opening the app: what sold today, what came in,\n// who still owes, and what is about to run out. Four numbers and three short\n// lists, and then out of the way.\n//\n// The figures are worked out from the last stretch of bills rather than from\n// a reporting endpoint. For a shop doing tens of bills a day that is one\n// request and it is instant. A shop doing thousands will want the server to\n// total it instead, and that is the point to add a summary endpoint - not\n// before, because the shape of what is worth totalling is still moving.\n// ===========================================================================\n\nimport { useCallback, useEffect, useMemo, useState } from \"react\";\nimport Link from \"next/link\";\nimport { HOME, ITEMS } from \"./content\";\nimport { useShop } from \"./useShop\";\nimport { Empty, ErrorState, StatusPill, TableSkeleton } from \"./ui/Bits\";\nimport { IconPlus, IconBox, IconUsers, IconRupee, IconArrowDown, IconBill, IconCheck } from \"./Icons\";\nimport { rupees, rupeesShort, formatQty, formatDate, today, daysAgo, ageInDays, relativeDay } from \"../../lib/money\";\nimport { unitShort } from \"../../lib/units\";\nimport { listInvoices, listItems, listParties, getBusiness } from \"./data\";\n\nexport default function Dashboard() {\n  const shop = useShop();\n  const [state, setState] = useState({ loading: true, error: null });\n  const [bills, setBills] = useState([]);\n  const [items, setItems] = useState([]);\n  const [parties, setParties] = useState([]);\n  const [biz, setBiz] = useState(null);\n\n  const load = useCallback(async () => {\n    setState({ loading: true, error: null });\n    try {\n      // Four calls at once rather than one after another - they do not\n      // depend on each other, and a shop connection has more latency than\n      // bandwidth.\n      const [inv, itm, prt, business] = await Promise.all([\n        listInvoices({ docType: \"sale\", limit: 60 }),\n        listItems({ limit: 200 }),\n        listParties({ limit: 200 }),\n        getBusiness(shop.businessId).catch(() => null),\n      ]);\n      setBills(inv.rows);\n      setItems(itm.rows);\n      setParties(prt.rows);\n      setBiz(business);\n      setState({ loading: false, error: null });\n    } catch (e) {\n      setState({ loading: false, error: e });\n    }\n  }, [shop.businessId]);\n\n  useEffect(() => {\n    if (shop.businessId) load();\n  }, [shop.businessId, load]);\n\n  const stats = useMemo(() => {\n    const t = today();\n    const live = bills.filter((b) => b.status !== \"cancelled\");\n    const todays = live.filter((b) => b.date === t);\n\n    const salesToday = todays.reduce((a, b) => a + b.amounts.total, 0);\n    const receivedToday = todays.reduce((a, b) => a + b.amounts.paid, 0);\n\n    const toCollect = parties.reduce((a, p) => a + p.owesUs, 0);\n    const toPay = parties.reduce((a, p) => a + p.weOwe, 0);\n\n    const low = items\n      .filter((i) => i.type !== \"service\" && (i.isLow || i.isOut))\n      .sort((a, b) => a.stock - b.stock)\n      .slice(0, 6);\n\n    const owing = parties\n      .filter((p) => p.owesUs > 0)\n      .sort((a, b) => {\n        const ageA = a.lastBillDate ? ageInDays(a.lastBillDate) : 0;\n        const ageB = b.lastBillDate ? ageInDays(b.lastBillDate) : 0;\n        return ageB - ageA || b.owesUs - a.owesUs;\n      })\n      .slice(0, 6);\n\n    // Last seven days, oldest on the left, for the little bar chart.\n    const week = [];\n    for (let i = 6; i >= 0; i--) {\n      const d = daysAgo(i);\n      const sum = live.filter((b) => b.date === d).reduce((a, b) => a + b.amounts.total, 0);\n      week.push({ date: d, paise: sum });\n    }\n\n    return {\n      salesToday,\n      billsToday: todays.length,\n      receivedToday,\n      toCollect,\n      toPay,\n      low,\n      owing,\n      week,\n      recent: live.slice(0, 6),\n    };\n  }, [bills, items, parties]);\n\n  if (state.error) return <ErrorState error={state.error} onRetry={load} />;\n\n  const hour = new Date().getHours();\n  const greet = hour < 12 ? HOME.greetMorning : hour < 17 ? HOME.greetAfternoon : HOME.greetEvening;\n  const name = (shop.user?.name || \"\").split(\" \")[0];\n\n  const needsSetup = !state.loading && (items.length === 0 || !biz?.gstin || bills.length === 0);\n\n  return (\n    <div className=\"ap-stack\" style={{ gap: 16 }}>\n      <div>\n        <h2 style={{ margin: 0, fontSize: 19, letterSpacing: \"-0.02em\" }}>\n          {greet}\n          {name ? `, ${name}` : \"\"}\n        </h2>\n        <p className=\"ap-sub\" style={{ margin: \"2px 0 0\" }}>\n          {shop.shop?.name}\n          {biz?.stateName ? ` · ${biz.stateName}` : \"\"}\n        </p>\n      </div>\n\n      <div className=\"ap-tiles\">\n        <div className=\"ap-tile\">\n          <div className=\"ap-tile-label\">\n            <IconRupee size={14} /> {HOME.tiles.sales}\n          </div>\n          <div className=\"ap-tile-value\">\n            {state.loading ? <span className=\"ap-skel\" style={{ width: 90, height: 22, display: \"block\" }} /> : rupeesShort(stats.salesToday)}\n          </div>\n          <div className=\"ap-tile-note\">\n            {stats.billsToday} {stats.billsToday === 1 ? \"bill today\" : HOME.tiles.salesNote}\n          </div>\n        </div>\n\n        <div className=\"ap-tile ap-tile-good\">\n          <div className=\"ap-tile-label\">\n            <IconArrowDown size={14} /> {HOME.tiles.received}\n          </div>\n          <div className=\"ap-tile-value\">\n            {state.loading ? <span className=\"ap-skel\" style={{ width: 90, height: 22, display: \"block\" }} /> : rupeesShort(stats.receivedToday)}\n          </div>\n          <div className=\"ap-tile-note\">{HOME.tiles.receivedNote}</div>\n        </div>\n\n        <Link href=\"/app/parties?filter=owing\" className=\"ap-tile ap-tile-bad\">\n          <div className=\"ap-tile-label\">\n            <IconUsers size={14} /> {HOME.tiles.toCollect}\n          </div>\n          <div className=\"ap-tile-value\">\n            {state.loading ? <span className=\"ap-skel\" style={{ width: 90, height: 22, display: \"block\" }} /> : rupeesShort(stats.toCollect)}\n          </div>\n          <div className=\"ap-tile-note\">{HOME.tiles.toCollectNote}</div>\n        </Link>\n\n        <div className=\"ap-tile\">\n          <div className=\"ap-tile-label\">\n            <IconBox size={14} /> {HOME.tiles.toPay}\n          </div>\n          <div className=\"ap-tile-value\">\n            {state.loading ? <span className=\"ap-skel\" style={{ width: 90, height: 22, display: \"block\" }} /> : rupeesShort(stats.toPay)}\n          </div>\n          <div className=\"ap-tile-note\">{HOME.tiles.toPayNote}</div>\n        </div>\n      </div>\n\n      <div className=\"ap-row\">\n        <Link href=\"/app/billing\" className=\"ap-btn ap-btn-primary ap-btn-lg\">\n          <IconPlus size={18} /> {HOME.newBill}\n        </Link>\n        <Link href=\"/app/items\" className=\"ap-btn\">\n          <IconBox size={17} /> {HOME.addItem}\n        </Link>\n        <Link href=\"/app/parties\" className=\"ap-btn\">\n          <IconUsers size={17} /> {HOME.addParty}\n        </Link>\n      </div>\n\n      {needsSetup ? (\n        <SetupChecklist items={items} bills={bills} biz={biz} />\n      ) : null}\n\n      <WeekBars week={stats.week} loading={state.loading} />\n\n      <div className=\"ap-grid2\" style={{ gap: 16, alignItems: \"start\" }}>\n        <section className=\"ap-panel\">\n          <div className=\"ap-panel-head\">\n            <h2>{HOME.recent}</h2>\n            <Link href=\"/app/bills\" className=\"ap-btn ap-btn-sm ap-btn-ghost ap-spacer\">\n              {HOME.seeAll}\n            </Link>\n          </div>\n          {state.loading ? (\n            <TableSkeleton rows={4} cols={3} />\n          ) : stats.recent.length ? (\n            <div className=\"ap-tablewrap\">\n              <table className=\"ap-table\">\n                <tbody>\n                  {stats.recent.map((b) => (\n                    <tr key={b.id}>\n                      <td>\n                        <Link href={`/app/bills/${b.id}`}>{b.number}</Link>\n                        <div className=\"ap-sub\">\n                          {b.partyName || \"Walk-in\"}\n                          {\" · \"}\n                          {relativeDay(b.date)}\n                        </div>\n                      </td>\n                      <td className=\"ap-right ap-num ap-strong\">{rupees(b.amounts.total)}</td>\n                      <td className=\"ap-right\">\n                        <StatusPill invoice={b} />\n                      </td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n          ) : (\n            <Empty icon={<IconBill size={32} />} title={HOME.recentEmpty} />\n          )}\n        </section>\n\n        <section className=\"ap-panel\">\n          <div className=\"ap-panel-head\">\n            <h2>{HOME.owes}</h2>\n            <Link href=\"/app/parties\" className=\"ap-btn ap-btn-sm ap-btn-ghost ap-spacer\">\n              {HOME.seeAll}\n            </Link>\n          </div>\n          {state.loading ? (\n            <TableSkeleton rows={4} cols={2} />\n          ) : stats.owing.length ? (\n            <div className=\"ap-tablewrap\">\n              <table className=\"ap-table\">\n                <tbody>\n                  {stats.owing.map((p) => (\n                    <tr key={p.id}>\n                      <td>\n                        <Link href={`/app/parties/${p.id}`}>{p.name}</Link>\n                        {p.lastBillDate ? (\n                          <div className=\"ap-sub\">Last bill {formatDate(p.lastBillDate)}</div>\n                        ) : null}\n                      </td>\n                      <td className=\"ap-right ap-num ap-strong\" style={{ color: \"var(--ap-danger)\" }}>\n                        {rupees(p.owesUs)}\n                      </td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n          ) : (\n            <Empty icon={<IconCheck size={32} />} title={HOME.owesEmpty} />\n          )}\n        </section>\n      </div>\n\n      <section className=\"ap-panel\">\n        <div className=\"ap-panel-head\">\n          <h2>{HOME.lowStock}</h2>\n          <span className=\"ap-sub ap-spacer\">{HOME.lowStockNote}</span>\n        </div>\n        {state.loading ? (\n          <TableSkeleton rows={3} cols={3} />\n        ) : stats.low.length ? (\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <tbody>\n                {stats.low.map((i) => (\n                  <tr key={i.id}>\n                    <td>\n                      <Link href=\"/app/items\">{i.name}</Link>\n                    </td>\n                    <td>\n                      {i.isOut ? (\n                        <span className=\"ap-pill ap-pill-unpaid\">{ITEMS.outTag}</span>\n                      ) : (\n                        <span className=\"ap-pill ap-pill-part\">{ITEMS.lowTag}</span>\n                      )}\n                    </td>\n                    <td className=\"ap-right ap-num\">\n                      {formatQty(i.stock)} {unitShort(i.unit)}\n                      {i.lowStockAlert != null ? (\n                        <span className=\"ap-sub\"> / {formatQty(i.lowStockAlert)}</span>\n                      ) : null}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <Empty icon={<IconCheck size={32} />} title={HOME.lowStockEmpty} />\n        )}\n      </section>\n    </div>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// seven days, as bars\n// ---------------------------------------------------------------------------\n// Drawn with divs rather than a charting library. It is seven rectangles -\n// pulling in a dependency for that would be sixty kilobytes to say the same\n// thing, on a connection that cannot spare it.\nconst BAR_MAX = 104;\n\nfunction WeekBars({ week, loading }) {\n  const max = Math.max(1, ...week.map((d) => d.paise));\n  const DAYS = [\"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\"];\n\n  return (\n    <section className=\"ap-panel\">\n      <div className=\"ap-panel-head\">\n        <h2>{HOME.weekTitle}</h2>\n        <span className=\"ap-sub ap-spacer\">{HOME.weekNote}</span>\n      </div>\n      <div className=\"ap-panel-body\">\n        <div style={{ display: \"flex\", gap: 10, alignItems: \"flex-end\" }}>\n          {week.map((d) => {\n            // Height in pixels, not a percentage. A percentage height inside\n            // a column of automatic height resolves to nothing, and the bars\n            // come out as hairlines.\n            const h = loading ? 8 : Math.max(4, Math.round((d.paise / max) * BAR_MAX));\n            const dow = DAYS[new Date(`${d.date}T00:00:00`).getDay()];\n            return (\n              <div key={d.date} style={{ flex: 1, textAlign: \"center\", minWidth: 0 }}>\n                <div style={{ height: BAR_MAX, display: \"flex\", alignItems: \"flex-end\" }}>\n                  <div\n                    title={`${formatDate(d.date)} — ${rupees(d.paise)}`}\n                    style={{\n                      width: \"100%\",\n                      height: h,\n                      background: d.paise ? \"var(--ap-brand)\" : \"var(--ap-line)\",\n                      borderRadius: \"5px 5px 2px 2px\",\n                      transition: \"height 0.25s\",\n                    }}\n                  />\n                </div>\n                <div className=\"ap-sub\" style={{ marginTop: 6, fontSize: 11 }}>\n                  {dow}\n                </div>\n                <div className=\"ap-sub\" style={{ fontSize: 11 }}>\n                  {d.paise ? rupeesShort(d.paise) : \"–\"}\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </div>\n    </section>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// the three things worth doing first\n// ---------------------------------------------------------------------------\nfunction SetupChecklist({ items, bills, biz }) {\n  const steps = [\n    {\n      done: items.length > 0,\n      label: HOME.stepItems,\n      note: HOME.stepItemsNote,\n      href: \"/app/items\",\n    },\n    {\n      done: Boolean(biz?.gstin),\n      label: HOME.stepGst,\n      note: HOME.stepGstNote,\n      href: \"/account\",\n    },\n    {\n      done: bills.length > 0,\n      label: HOME.stepBill,\n      note: HOME.stepBillNote,\n      href: \"/app/billing\",\n    },\n  ];\n\n  if (steps.every((s) => s.done)) return null;\n\n  return (\n    <section className=\"ap-panel\">\n      <div className=\"ap-panel-head\">\n        <h2>{HOME.setupTitle}</h2>\n        <span className=\"ap-sub ap-spacer\">{HOME.setupNote}</span>\n      </div>\n      <div className=\"ap-panel-body\" style={{ display: \"grid\", gap: 10 }}>\n        {steps.map((s) => (\n          <div key={s.label} className=\"ap-row\" style={{ gap: 11 }}>\n            <span\n              style={{\n                width: 22,\n                height: 22,\n                borderRadius: \"50%\",\n                display: \"grid\",\n                placeItems: \"center\",\n                flex: \"0 0 auto\",\n                background: s.done ? \"var(--ap-brand-soft)\" : \"var(--ap-sunken)\",\n                color: s.done ? \"var(--ap-brand)\" : \"var(--ap-ink-3)\",\n                border: `1px solid ${s.done ? \"var(--ap-brand-line)\" : \"var(--ap-line-strong)\"}`,\n              }}\n            >\n              {s.done ? <IconCheck size={14} /> : null}\n            </span>\n            <span style={{ minWidth: 0, flex: 1 }}>\n              <span\n                className=\"ap-strong\"\n                style={{ textDecoration: s.done ? \"line-through\" : \"none\", opacity: s.done ? 0.6 : 1 }}\n              >\n                {s.label}\n              </span>\n              <span className=\"ap-sub\" style={{ display: \"block\" }}>\n                {s.note}\n              </span>\n            </span>\n            {!s.done ? (\n              <Link href={s.href} className=\"ap-btn ap-btn-sm\">\n                Do it\n              </Link>\n            ) : null}\n          </div>\n        ))}\n      </div>\n    </section>\n  );\n}\n","components/app/Icons.js":"// ===========================================================================\n// ICONS\n// ---------------------------------------------------------------------------\n// Drawn in code, not loaded as files. A shop on a slow connection should not\n// wait on an icon font before the billing screen is usable, and an inline\n// path costs nothing and takes the surrounding text colour for free.\n//\n// Every icon is 24x24, 1.6 stroke, round caps. Keep new ones to that grid\n// or they will look wrong next to the rest.\n// ===========================================================================\n\nfunction Svg({ children, size = 20, ...rest }) {\n  return (\n    <svg\n      width={size}\n      height={size}\n      viewBox=\"0 0 24 24\"\n      fill=\"none\"\n      stroke=\"currentColor\"\n      strokeWidth=\"1.6\"\n      strokeLinecap=\"round\"\n      strokeLinejoin=\"round\"\n      aria-hidden=\"true\"\n      focusable=\"false\"\n      {...rest}\n    >\n      {children}\n    </svg>\n  );\n}\n\nexport const IconHome = (p) => (\n  <Svg {...p}>\n    <path d=\"M4 10.5 12 4l8 6.5V19a1 1 0 0 1-1 1h-4v-5H9v5H5a1 1 0 0 1-1-1z\" />\n  </Svg>\n);\n\nexport const IconBill = (p) => (\n  <Svg {...p}>\n    <path d=\"M6 3h12v18l-3-2-3 2-3-2-3 2z\" />\n    <path d=\"M9 8h6M9 12h6M9 16h3\" />\n  </Svg>\n);\n\nexport const IconPlus = (p) => (\n  <Svg {...p}>\n    <path d=\"M12 5v14M5 12h14\" />\n  </Svg>\n);\n\nexport const IconBox = (p) => (\n  <Svg {...p}>\n    <path d=\"M12 3l8 4.5v9L12 21l-8-4.5v-9z\" />\n    <path d=\"M4 7.5 12 12l8-4.5M12 12v9\" />\n  </Svg>\n);\n\nexport const IconUsers = (p) => (\n  <Svg {...p}>\n    <circle cx=\"9\" cy=\"8\" r=\"3.2\" />\n    <path d=\"M3 20c0-3.3 2.7-5.5 6-5.5s6 2.2 6 5.5\" />\n    <path d=\"M16 5.5a3.2 3.2 0 0 1 0 6M17.5 14.8c2.1.6 3.5 2.4 3.5 5.2\" />\n  </Svg>\n);\n\nexport const IconList = (p) => (\n  <Svg {...p}>\n    <path d=\"M8 6h12M8 12h12M8 18h12\" />\n    <circle cx=\"4\" cy=\"6\" r=\"1\" fill=\"currentColor\" stroke=\"none\" />\n    <circle cx=\"4\" cy=\"12\" r=\"1\" fill=\"currentColor\" stroke=\"none\" />\n    <circle cx=\"4\" cy=\"18\" r=\"1\" fill=\"currentColor\" stroke=\"none\" />\n  </Svg>\n);\n\nexport const IconSearch = (p) => (\n  <Svg {...p}>\n    <circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\" />\n    <path d=\"m15.5 15.5 4.5 4.5\" />\n  </Svg>\n);\n\nexport const IconClose = (p) => (\n  <Svg {...p}>\n    <path d=\"M6 6l12 12M18 6 6 18\" />\n  </Svg>\n);\n\nexport const IconChevron = (p) => (\n  <Svg {...p}>\n    <path d=\"m9 6 6 6-6 6\" />\n  </Svg>\n);\n\nexport const IconChevronDown = (p) => (\n  <Svg {...p}>\n    <path d=\"m6 9 6 6 6-6\" />\n  </Svg>\n);\n\nexport const IconCheck = (p) => (\n  <Svg {...p}>\n    <path d=\"m5 13 4.5 4.5L19 7\" />\n  </Svg>\n);\n\nexport const IconPrint = (p) => (\n  <Svg {...p}>\n    <path d=\"M7 9V3h10v6\" />\n    <path d=\"M5 9h14a1 1 0 0 1 1 1v6h-4v5H8v-5H4v-6a1 1 0 0 1 1-1z\" />\n    <path d=\"M8 16h8\" />\n  </Svg>\n);\n\nexport const IconShare = (p) => (\n  <Svg {...p}>\n    <path d=\"M4 12v7a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-7\" />\n    <path d=\"M12 16V3M8 7l4-4 4 4\" />\n  </Svg>\n);\n\nexport const IconWhatsApp = (p) => (\n  <Svg {...p}>\n    <path d=\"M20 11.7A8 8 0 0 1 8.2 19L4 20l1.1-4.1A8 8 0 1 1 20 11.7z\" />\n    <path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5.6 0 1-.5 1-1l-1.3-.7-1 .8a5 5 0 0 1-2.3-2.3l.8-1L11 9.5c0-.5-.4-1-1-1-.5 0-1 .4-1 1z\" />\n  </Svg>\n);\n\nexport const IconRupee = (p) => (\n  <Svg {...p}>\n    <path d=\"M7 4h10M7 9h10M15.5 4c0 4-2.5 5-6 5l7 10\" />\n  </Svg>\n);\n\nexport const IconWarn = (p) => (\n  <Svg {...p}>\n    <path d=\"M12 4l9 16H3z\" />\n    <path d=\"M12 10v4M12 17h.01\" />\n  </Svg>\n);\n\nexport const IconTrash = (p) => (\n  <Svg {...p}>\n    <path d=\"M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13\" />\n    <path d=\"M10 11v6M14 11v6\" />\n  </Svg>\n);\n\nexport const IconEdit = (p) => (\n  <Svg {...p}>\n    <path d=\"M4 20h4L20 8l-4-4L4 16z\" />\n    <path d=\"m14 6 4 4\" />\n  </Svg>\n);\n\nexport const IconShop = (p) => (\n  <Svg {...p}>\n    <path d=\"M4 9h16v11a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1z\" />\n    <path d=\"M3 9l2-5h14l2 5\" />\n    <path d=\"M9 21v-6h6v6\" />\n  </Svg>\n);\n\nexport const IconSettings = (p) => (\n  <Svg {...p}>\n    <circle cx=\"12\" cy=\"12\" r=\"3\" />\n    <path d=\"M12 3v2.5M12 18.5V21M4.2 7.5l2.2 1.3M17.6 15.2l2.2 1.3M4.2 16.5l2.2-1.3M17.6 8.8l2.2-1.3\" />\n  </Svg>\n);\n\nexport const IconLogout = (p) => (\n  <Svg {...p}>\n    <path d=\"M10 4H5a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h5\" />\n    <path d=\"M15 8l4 4-4 4M9 12h10\" />\n  </Svg>\n);\n\nexport const IconArrowDown = (p) => (\n  <Svg {...p}>\n    <path d=\"M12 4v15M6 13l6 6 6-6\" />\n  </Svg>\n);\n\nexport const IconArrowUp = (p) => (\n  <Svg {...p}>\n    <path d=\"M12 20V5M6 11l6-6 6 6\" />\n  </Svg>\n);\n\nexport const IconHistory = (p) => (\n  <Svg {...p}>\n    <path d=\"M3.5 12a8.5 8.5 0 1 0 2.6-6.1\" />\n    <path d=\"M3.5 4.5V9H8\" />\n    <path d=\"M12 8v4.5l3 1.8\" />\n  </Svg>\n);\n\nexport const IconMenu = (p) => (\n  <Svg {...p}>\n    <path d=\"M4 7h16M4 12h16M4 17h16\" />\n  </Svg>\n);\n\nexport const IconPhone = (p) => (\n  <Svg {...p}>\n    <path d=\"M7 3h4l1.5 4L10 8.5a9 9 0 0 0 5.5 5.5L17 12l4 1.5V18a2 2 0 0 1-2.2 2A16 16 0 0 1 4 5.2 2 2 0 0 1 6 3z\" />\n  </Svg>\n);\n\nexport const IconCalendar = (p) => (\n  <Svg {...p}>\n    <rect x=\"3.5\" y=\"5.5\" width=\"17\" height=\"15\" rx=\"1.5\" />\n    <path d=\"M3.5 10h17M8 3.5v4M16 3.5v4\" />\n  </Svg>\n);\n\nexport const IconDownload = (p) => (\n  <Svg {...p}>\n    <path d=\"M12 3v12M7 11l5 5 5-5\" />\n    <path d=\"M4 20h16\" />\n  </Svg>\n);\n\nexport const IconKeyboard = (p) => (\n  <Svg {...p}>\n    <rect x=\"2.5\" y=\"6.5\" width=\"19\" height=\"11\" rx=\"1.5\" />\n    <path d=\"M6 10h.01M9 10h.01M12 10h.01M15 10h.01M18 10h.01M7 14h10\" />\n  </Svg>\n);\n","components/app/Shell.js":"\"use client\";\n\n// ===========================================================================\n// THE APP SHELL\n// ---------------------------------------------------------------------------\n// The frame every screen behind the login sits in: the sidebar, the shop\n// switcher, the top bar, and the gate that decides whether there is anything\n// to show at all.\n//\n// The gate has four honest answers and no fifth:\n//   still checking    -> a quiet placeholder, no flash of the wrong thing\n//   not signed in     -> say so, with a way back to the login\n//   no shop yet       -> send them to set one up; a bill needs a state\n//   server unreachable-> say that, rather than an empty screen that looks\n//                        like a shop with no bills in it\n// ===========================================================================\n\nimport { useEffect, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { usePathname, useRouter } from \"next/navigation\";\nimport { NAV, COMMON, SHOP } from \"./content\";\nimport { useShop } from \"./useShop\";\nimport { ToastProvider } from \"./ui/Toast\";\nimport { Note } from \"./ui/Bits\";\nimport {\n  IconHome,\n  IconBill,\n  IconBox,\n  IconUsers,\n  IconPlus,\n  IconShop,\n  IconMenu,\n  IconChevronDown,\n  IconCheck,\n  IconLogout,\n  IconSettings,\n} from \"./Icons\";\n\nconst ICONS = {\n  home: IconHome,\n  bill: IconBill,\n  box: IconBox,\n  users: IconUsers,\n  plus: IconPlus,\n};\n\nexport default function Shell({ title, children, flush = false, actions }) {\n  const shop = useShop();\n  const pathname = usePathname();\n  const router = useRouter();\n  const [menuOpen, setMenuOpen] = useState(false);\n\n  // Close the slide-over whenever the route changes, or it stays over the\n  // page you just navigated to on a phone.\n  useEffect(() => {\n    setMenuOpen(false);\n  }, [pathname]);\n\n  useHotkeys(router);\n\n  return (\n    <div className=\"ap-root\">\n      <ToastProvider>\n        <div className=\"ap-shell\">\n          {menuOpen ? <div className=\"ap-scrim\" onClick={() => setMenuOpen(false)} /> : null}\n\n          <aside className=\"ap-side\" data-open={menuOpen ? \"true\" : \"false\"}>\n            <Link href=\"/app\" className=\"ap-brandbar\">\n              <span className=\"ap-brandmark\" aria-hidden=\"true\">\n                G\n              </span>\n              <span>Galla</span>\n            </Link>\n\n            <ShopSwitcher shop={shop} />\n\n            <nav className=\"ap-nav\" aria-label=\"Main\">\n              {NAV.map((n) => {\n                const Icon = ICONS[n.icon] || IconHome;\n                const active = n.href === \"/app\" ? pathname === \"/app\" : pathname.startsWith(n.href);\n                return (\n                  <Link\n                    key={n.href}\n                    href={n.href}\n                    className=\"ap-navlink\"\n                    aria-current={active ? \"page\" : undefined}\n                  >\n                    <Icon size={18} />\n                    <span>{n.label}</span>\n                    <span className=\"ap-navkey\">{n.hotkey}</span>\n                  </Link>\n                );\n              })}\n\n              <div className=\"ap-navhead\">Shop</div>\n              <Link href=\"/account\" className=\"ap-navlink\">\n                <IconSettings size={18} />\n                <span>{SHOP.myAccount}</span>\n              </Link>\n              <Link href=\"/\" className=\"ap-navlink\">\n                <IconShop size={18} />\n                <span>{SHOP.website}</span>\n              </Link>\n            </nav>\n\n            <div className=\"ap-sidefoot\">\n              <button\n                type=\"button\"\n                className=\"ap-navlink\"\n                style={{ width: \"100%\", background: \"none\", border: 0, font: \"inherit\", cursor: \"pointer\" }}\n                onClick={() => {\n                  shop.signOut?.();\n                  router.push(\"/\");\n                }}\n              >\n                <IconLogout size={18} />\n                <span>{SHOP.signOut}</span>\n              </button>\n            </div>\n          </aside>\n\n          <div className=\"ap-main\">\n            <header className=\"ap-top\">\n              <button\n                type=\"button\"\n                className=\"ap-burger\"\n                onClick={() => setMenuOpen((v) => !v)}\n                aria-label=\"Menu\"\n                aria-expanded={menuOpen}\n              >\n                <IconMenu size={18} />\n              </button>\n              <h1 className=\"ap-title\">{title}</h1>\n              <div className=\"ap-top-right\">{actions}</div>\n            </header>\n\n            <main className={flush ? \"ap-body ap-body-flush\" : \"ap-body\"}>\n              <Gate shop={shop}>{children}</Gate>\n            </main>\n          </div>\n        </div>\n      </ToastProvider>\n    </div>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// the gate\n// ---------------------------------------------------------------------------\nfunction Gate({ shop, children }) {\n  if (!shop.ready) {\n    return (\n      <div style={{ padding: 20, display: \"grid\", gap: 10, maxWidth: 420 }}>\n        <div className=\"ap-skel\" style={{ width: \"40%\", height: 17 }} />\n        <div className=\"ap-skel\" style={{ width: \"72%\" }} />\n        <div className=\"ap-skel\" style={{ width: \"58%\" }} />\n      </div>\n    );\n  }\n\n  if (shop.offline && !shop.signedIn) {\n    return (\n      <div style={{ maxWidth: 560 }}>\n        <Note kind=\"warn\">\n          <strong style={{ display: \"block\", marginBottom: 3 }}>{COMMON.offlineTitle}</strong>\n          {COMMON.offlineBody}\n        </Note>\n      </div>\n    );\n  }\n\n  if (!shop.signedIn) {\n    return (\n      <div className=\"ap-panel\" style={{ maxWidth: 480 }}>\n        <div className=\"ap-panel-body\">\n          <h2 style={{ margin: \"0 0 6px\", fontSize: 17 }}>{COMMON.authTitle}</h2>\n          <p style={{ margin: \"0 0 14px\", color: \"var(--ap-ink-3)\" }}>{COMMON.authBody}</p>\n          <Link href=\"/login?next=/app\" className=\"ap-btn ap-btn-primary\">\n            Sign in\n          </Link>\n        </div>\n      </div>\n    );\n  }\n\n  if (!shop.businessId) {\n    return (\n      <div className=\"ap-panel\" style={{ maxWidth: 480 }}>\n        <div className=\"ap-panel-body\">\n          <h2 style={{ margin: \"0 0 6px\", fontSize: 17 }}>{COMMON.noShopTitle}</h2>\n          <p style={{ margin: \"0 0 14px\", color: \"var(--ap-ink-3)\" }}>{COMMON.noShopBody}</p>\n          <Link href=\"/account\" className=\"ap-btn ap-btn-primary\">\n            {COMMON.noShopCta}\n          </Link>\n        </div>\n      </div>\n    );\n  }\n\n  return children;\n}\n\n// ---------------------------------------------------------------------------\n// shop switcher\n// ---------------------------------------------------------------------------\n// Only becomes a menu when there is more than one shop. A single-shop\n// shopkeeper should not be given a dropdown that does nothing.\nfunction ShopSwitcher({ shop }) {\n  const [open, setOpen] = useState(false);\n  const box = useRef(null);\n\n  useEffect(() => {\n    if (!open) return;\n    const onDown = (e) => {\n      if (box.current && !box.current.contains(e.target)) setOpen(false);\n    };\n    const onKey = (e) => {\n      if (e.key === \"Escape\") setOpen(false);\n    };\n    document.addEventListener(\"mousedown\", onDown);\n    document.addEventListener(\"keydown\", onKey);\n    return () => {\n      document.removeEventListener(\"mousedown\", onDown);\n      document.removeEventListener(\"keydown\", onKey);\n    };\n  }, [open]);\n\n  const name = shop.shop?.name || \"Your shop\";\n  const sub = shop.shop?.stateName || shop.shop?.city || \"\";\n  const many = (shop.businesses || []).length > 1;\n\n  if (!shop.signedIn) {\n    return (\n      <div className=\"ap-shopbtn\" style={{ cursor: \"default\" }}>\n        <IconShop size={18} />\n        <span className=\"ap-shopbtn-txt\">\n          <span className=\"ap-shopbtn-name\">Not signed in</span>\n        </span>\n      </div>\n    );\n  }\n\n  return (\n    <div style={{ position: \"relative\" }} ref={box}>\n      <button\n        type=\"button\"\n        className=\"ap-shopbtn\"\n        onClick={() => many && setOpen((v) => !v)}\n        aria-expanded={many ? open : undefined}\n        style={many ? undefined : { cursor: \"default\" }}\n      >\n        <IconShop size={18} />\n        <span className=\"ap-shopbtn-txt\">\n          <span className=\"ap-shopbtn-name\" title={name}>\n            {name}\n          </span>\n          {sub ? <span className=\"ap-shopbtn-sub\">{sub}</span> : null}\n        </span>\n        {many ? <IconChevronDown size={16} /> : null}\n      </button>\n\n      {open ? (\n        <div\n          className=\"ap-suggest\"\n          style={{ left: 10, right: 10, top: \"calc(100% - 4px)\" }}\n          role=\"menu\"\n        >\n          {shop.businesses.map((b) => (\n            <button\n              key={b.id}\n              type=\"button\"\n              className=\"ap-suggest-item\"\n              onClick={() => {\n                shop.switchBusiness?.(b.id);\n                setOpen(false);\n              }}\n            >\n              <span className=\"ap-suggest-name\">{b.name}</span>\n              {String(b.id) === String(shop.businessId) ? (\n                <span className=\"ap-suggest-right\" style={{ color: \"var(--ap-brand)\" }}>\n                  <IconCheck size={16} />\n                </span>\n              ) : null}\n            </button>\n          ))}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// keyboard shortcuts\n// ---------------------------------------------------------------------------\n// \"g\" then a letter, the way a lot of keyboard-driven tools work. Ignored\n// while the cursor is in a field, because a shopkeeper typing \"garam masala\"\n// into the item box must not be thrown onto another page by the g.\nfunction useHotkeys(router) {\n  const pending = useRef(null);\n\n  useEffect(() => {\n    const onKey = (e) => {\n      if (e.metaKey || e.ctrlKey || e.altKey) return;\n      const el = e.target;\n      const tag = el?.tagName;\n      if (tag === \"INPUT\" || tag === \"TEXTAREA\" || tag === \"SELECT\" || el?.isContentEditable) return;\n\n      const key = e.key.toLowerCase();\n\n      if (pending.current === \"g\") {\n        pending.current = null;\n        const to = { h: \"/app\", b: \"/app/billing\", l: \"/app/bills\", i: \"/app/items\", p: \"/app/parties\" }[key];\n        if (to) {\n          e.preventDefault();\n          router.push(to);\n        }\n        return;\n      }\n\n      if (key === \"g\") {\n        pending.current = \"g\";\n        // Forget it after a moment, so a stray g does not hijack the next key\n        // pressed a minute later.\n        setTimeout(() => {\n          pending.current = null;\n        }, 1200);\n      }\n    };\n\n    window.addEventListener(\"keydown\", onKey);\n    return () => window.removeEventListener(\"keydown\", onKey);\n  }, [router]);\n}\n","components/app/app.css":"/* ==========================================================================\n   THE APP AREA\n   --------------------------------------------------------------------------\n   Everything behind the login, prefixed ap-. It deliberately declares its\n   own tokens rather than borrowing the marketing site's: the two have\n   different jobs. The website is a brochure and wants air. This is a tool\n   somebody uses for six hours a day with one hand on the keyboard, so it is\n   denser, quieter, and its tap targets are big enough to hit without\n   looking.\n\n   Nothing in here is !important and nothing selects a bare tag outside\n   .ap-root, so it cannot leak into the website's pages.\n   ========================================================================== */\n\n.ap-root {\n  /* surfaces */\n  --ap-bg: #f5f6f8;\n  --ap-panel: #ffffff;\n  --ap-sunken: #f0f2f5;\n  --ap-line: #e2e6eb;\n  --ap-line-strong: #cbd3db;\n\n  /* ink */\n  --ap-ink: #10151c;\n  --ap-ink-2: #46525f;\n  --ap-ink-3: #74818e;\n\n  /* brand - a ledger green. Reads as money without shouting. */\n  --ap-brand: #0b6e4f;\n  --ap-brand-ink: #085840;\n  --ap-brand-soft: #e6f4ef;\n  --ap-brand-line: #bfe0d4;\n\n  /* states */\n  --ap-danger: #b4232a;\n  --ap-danger-soft: #fdecec;\n  --ap-warn: #9a6400;\n  --ap-warn-soft: #fdf3e2;\n  --ap-info: #1f5fa8;\n  --ap-info-soft: #eaf2fc;\n\n  --ap-radius: 10px;\n  --ap-radius-sm: 7px;\n  --ap-shadow: 0 1px 2px rgba(16, 21, 28, 0.05), 0 4px 16px rgba(16, 21, 28, 0.05);\n  --ap-shadow-lift: 0 8px 28px rgba(16, 21, 28, 0.14);\n\n  --ap-sidebar: 232px;\n  --ap-topbar: 56px;\n\n  --ap-mono: ui-monospace, \"SF Mono\", \"Cascadia Mono\", Menlo, Consolas, monospace;\n\n  color: var(--ap-ink);\n  background: var(--ap-bg);\n  min-height: 100vh;\n  font-size: 14.5px;\n  line-height: 1.45;\n  -webkit-text-size-adjust: 100%;\n}\n\n.ap-root *,\n.ap-root *::before,\n.ap-root *::after {\n  box-sizing: border-box;\n}\n\n/* Tabular figures everywhere a number can be compared down a column.\n   Without this the 1s are narrow and the column looks ragged. */\n.ap-num,\n.ap-root td.ap-num,\n.ap-root input[type=\"number\"] {\n  font-variant-numeric: tabular-nums;\n  font-feature-settings: \"tnum\" 1;\n}\n\n/* --------------------------------------------------------------------------\n   shell\n   -------------------------------------------------------------------------- */\n.ap-shell {\n  display: grid;\n  grid-template-columns: var(--ap-sidebar) 1fr;\n  min-height: 100vh;\n}\n\n.ap-side {\n  background: #0c1118;\n  color: #c6ced8;\n  display: flex;\n  flex-direction: column;\n  position: sticky;\n  top: 0;\n  height: 100vh;\n  overflow-y: auto;\n}\n\n.ap-brandbar {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  padding: 0 16px;\n  height: var(--ap-topbar);\n  flex: 0 0 auto;\n  color: #fff;\n  font-weight: 650;\n  letter-spacing: -0.01em;\n  text-decoration: none;\n}\n\n.ap-brandmark {\n  width: 26px;\n  height: 26px;\n  border-radius: 7px;\n  background: linear-gradient(145deg, #12d08f, var(--ap-brand));\n  display: grid;\n  place-items: center;\n  color: #04231a;\n  font-weight: 800;\n  font-size: 14px;\n  flex: 0 0 auto;\n}\n\n.ap-shopbtn {\n  margin: 4px 10px 10px;\n  padding: 9px 10px;\n  border-radius: var(--ap-radius-sm);\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.09);\n  color: #e7ecf1;\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  cursor: pointer;\n  text-align: left;\n  width: calc(100% - 20px);\n  font: inherit;\n}\n\n.ap-shopbtn:hover {\n  background: rgba(255, 255, 255, 0.1);\n}\n\n.ap-shopbtn-name {\n  display: block;\n  font-weight: 600;\n  font-size: 13.5px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.ap-shopbtn-sub {\n  display: block;\n  font-size: 11.5px;\n  color: #8b97a4;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.ap-shopbtn-txt {\n  min-width: 0;\n  flex: 1;\n}\n\n.ap-nav {\n  padding: 4px 8px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  flex: 1;\n}\n\n.ap-navhead {\n  padding: 14px 10px 5px;\n  font-size: 10.5px;\n  letter-spacing: 0.09em;\n  text-transform: uppercase;\n  color: #6d7a88;\n  font-weight: 650;\n}\n\n.ap-navlink {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px;\n  border-radius: var(--ap-radius-sm);\n  color: #c6ced8;\n  text-decoration: none;\n  font-size: 14px;\n  position: relative;\n}\n\n.ap-navlink:hover {\n  background: rgba(255, 255, 255, 0.07);\n  color: #fff;\n}\n\n.ap-navlink[aria-current=\"page\"] {\n  background: rgba(18, 208, 143, 0.14);\n  color: #7ff0c4;\n  font-weight: 600;\n}\n\n.ap-navlink[aria-current=\"page\"]::before {\n  content: \"\";\n  position: absolute;\n  left: -8px;\n  top: 7px;\n  bottom: 7px;\n  width: 3px;\n  border-radius: 0 3px 3px 0;\n  background: #12d08f;\n}\n\n.ap-navlink svg {\n  flex: 0 0 auto;\n  opacity: 0.85;\n}\n\n.ap-navkey {\n  margin-left: auto;\n  font-size: 10.5px;\n  color: #6d7a88;\n  font-family: var(--ap-mono);\n}\n\n.ap-sidefoot {\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n  padding: 10px;\n}\n\n/* --------------------------------------------------------------------------\n   main column\n   -------------------------------------------------------------------------- */\n.ap-main {\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n}\n\n.ap-top {\n  height: var(--ap-topbar);\n  background: var(--ap-panel);\n  border-bottom: 1px solid var(--ap-line);\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 0 18px;\n  position: sticky;\n  top: 0;\n  z-index: 30;\n}\n\n.ap-burger {\n  display: none;\n  background: none;\n  border: 1px solid var(--ap-line);\n  border-radius: var(--ap-radius-sm);\n  padding: 6px;\n  color: var(--ap-ink-2);\n  cursor: pointer;\n}\n\n.ap-title {\n  font-size: 16px;\n  font-weight: 650;\n  letter-spacing: -0.01em;\n  margin: 0;\n}\n\n.ap-top-right {\n  margin-left: auto;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.ap-body {\n  padding: 18px;\n  flex: 1;\n  min-width: 0;\n}\n\n.ap-body-flush {\n  padding: 0;\n}\n\n/* --------------------------------------------------------------------------\n   buttons\n   -------------------------------------------------------------------------- */\n.ap-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 7px;\n  padding: 8px 14px;\n  min-height: 38px;\n  border-radius: var(--ap-radius-sm);\n  border: 1px solid var(--ap-line-strong);\n  background: var(--ap-panel);\n  color: var(--ap-ink);\n  font: inherit;\n  font-weight: 550;\n  cursor: pointer;\n  text-decoration: none;\n  white-space: nowrap;\n  transition: background 0.12s, border-color 0.12s, transform 0.06s;\n}\n\n.ap-btn:hover {\n  background: var(--ap-sunken);\n}\n\n.ap-btn:active {\n  transform: translateY(1px);\n}\n\n.ap-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n  transform: none;\n}\n\n.ap-btn-primary {\n  background: var(--ap-brand);\n  border-color: var(--ap-brand);\n  color: #fff;\n}\n\n.ap-btn-primary:hover {\n  background: var(--ap-brand-ink);\n}\n\n.ap-btn-danger {\n  color: var(--ap-danger);\n  border-color: #e9bfc1;\n  background: var(--ap-panel);\n}\n\n.ap-btn-danger:hover {\n  background: var(--ap-danger-soft);\n}\n\n.ap-btn-ghost {\n  border-color: transparent;\n  background: transparent;\n}\n\n.ap-btn-ghost:hover {\n  background: var(--ap-sunken);\n}\n\n.ap-btn-sm {\n  padding: 5px 10px;\n  min-height: 31px;\n  font-size: 13px;\n}\n\n.ap-btn-lg {\n  padding: 12px 20px;\n  min-height: 48px;\n  font-size: 15.5px;\n  font-weight: 650;\n}\n\n.ap-btn-block {\n  width: 100%;\n}\n\n.ap-btn-icon {\n  padding: 7px;\n  min-height: 34px;\n  min-width: 34px;\n}\n\n/* --------------------------------------------------------------------------\n   panels and cards\n   -------------------------------------------------------------------------- */\n.ap-panel {\n  background: var(--ap-panel);\n  border: 1px solid var(--ap-line);\n  border-radius: var(--ap-radius);\n  box-shadow: var(--ap-shadow);\n}\n\n.ap-panel-head {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--ap-line);\n}\n\n.ap-panel-head h2 {\n  margin: 0;\n  font-size: 14.5px;\n  font-weight: 650;\n}\n\n.ap-panel-head .ap-spacer {\n  margin-left: auto;\n}\n\n.ap-panel-body {\n  padding: 14px;\n}\n\n.ap-panel-foot {\n  padding: 12px 14px;\n  border-top: 1px solid var(--ap-line);\n  background: var(--ap-sunken);\n  border-radius: 0 0 var(--ap-radius) var(--ap-radius);\n}\n\n/* --------------------------------------------------------------------------\n   stat tiles\n   -------------------------------------------------------------------------- */\n.ap-tiles {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.ap-tile {\n  background: var(--ap-panel);\n  border: 1px solid var(--ap-line);\n  border-radius: var(--ap-radius);\n  padding: 13px 14px;\n  box-shadow: var(--ap-shadow);\n  text-decoration: none;\n  color: inherit;\n  display: block;\n}\n\na.ap-tile:hover {\n  border-color: var(--ap-line-strong);\n}\n\n.ap-tile-label {\n  font-size: 12px;\n  color: var(--ap-ink-3);\n  font-weight: 550;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.ap-tile-value {\n  font-size: 23px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  margin-top: 5px;\n  font-variant-numeric: tabular-nums;\n}\n\n.ap-tile-note {\n  font-size: 12px;\n  color: var(--ap-ink-3);\n  margin-top: 2px;\n}\n\n.ap-tile-good .ap-tile-value {\n  color: var(--ap-brand-ink);\n}\n\n.ap-tile-bad .ap-tile-value {\n  color: var(--ap-danger);\n}\n\n/* --------------------------------------------------------------------------\n   inputs\n   -------------------------------------------------------------------------- */\n.ap-field {\n  display: block;\n}\n\n.ap-label {\n  display: block;\n  font-size: 12.5px;\n  font-weight: 600;\n  color: var(--ap-ink-2);\n  margin-bottom: 5px;\n}\n\n.ap-req {\n  color: var(--ap-danger);\n}\n\n.ap-input,\n.ap-select,\n.ap-textarea {\n  width: 100%;\n  padding: 9px 11px;\n  min-height: 40px;\n  border: 1px solid var(--ap-line-strong);\n  border-radius: var(--ap-radius-sm);\n  background: var(--ap-panel);\n  color: var(--ap-ink);\n  font: inherit;\n}\n\n.ap-textarea {\n  min-height: 72px;\n  resize: vertical;\n}\n\n.ap-input:focus,\n.ap-select:focus,\n.ap-textarea:focus {\n  outline: 2px solid var(--ap-brand);\n  outline-offset: -1px;\n  border-color: var(--ap-brand);\n}\n\n.ap-input::placeholder {\n  color: #9aa6b2;\n}\n\n.ap-input[aria-invalid=\"true\"],\n.ap-select[aria-invalid=\"true\"] {\n  border-color: var(--ap-danger);\n}\n\n.ap-hint {\n  font-size: 12px;\n  color: var(--ap-ink-3);\n  margin-top: 4px;\n}\n\n.ap-err {\n  font-size: 12.5px;\n  color: var(--ap-danger);\n  margin-top: 4px;\n}\n\n.ap-grid2 {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.ap-grid3 {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.ap-stack {\n  display: grid;\n  gap: 12px;\n}\n\n.ap-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n/* a rupee sign welded to the left of the box */\n.ap-money {\n  position: relative;\n}\n\n.ap-money .ap-input {\n  padding-left: 26px;\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n}\n\n.ap-money::before {\n  content: \"\\20B9\";\n  position: absolute;\n  left: 10px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--ap-ink-3);\n  pointer-events: none;\n  font-size: 13.5px;\n}\n\n.ap-search {\n  position: relative;\n  flex: 1;\n  min-width: 180px;\n}\n\n.ap-search .ap-input {\n  padding-left: 34px;\n}\n\n.ap-search-ico {\n  position: absolute;\n  left: 9px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--ap-ink-3);\n  pointer-events: none;\n}\n\n.ap-check {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 13.5px;\n  cursor: pointer;\n}\n\n.ap-check input {\n  width: 17px;\n  height: 17px;\n  accent-color: var(--ap-brand);\n}\n\n/* segmented control, for doc type and in/out */\n.ap-seg {\n  display: inline-flex;\n  background: var(--ap-sunken);\n  border: 1px solid var(--ap-line);\n  border-radius: var(--ap-radius-sm);\n  padding: 2px;\n  gap: 2px;\n  max-width: 100%;\n  overflow-x: auto;\n  scrollbar-width: none;\n}\n\n.ap-seg::-webkit-scrollbar {\n  display: none;\n}\n\n.ap-seg button {\n  border: 0;\n  background: none;\n  font: inherit;\n  font-weight: 550;\n  padding: 6px 13px;\n  border-radius: 5px;\n  color: var(--ap-ink-2);\n  cursor: pointer;\n  white-space: nowrap;\n}\n\n.ap-seg button[aria-pressed=\"true\"] {\n  background: var(--ap-panel);\n  color: var(--ap-ink);\n  box-shadow: 0 1px 2px rgba(16, 21, 28, 0.12);\n}\n\n.ap-sronly {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* --------------------------------------------------------------------------\n   tables\n   -------------------------------------------------------------------------- */\n.ap-tablewrap {\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n}\n\n.ap-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 14px;\n}\n\n.ap-table th {\n  text-align: left;\n  font-size: 11.5px;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  color: var(--ap-ink-3);\n  font-weight: 650;\n  padding: 9px 12px;\n  border-bottom: 1px solid var(--ap-line);\n  background: var(--ap-sunken);\n  white-space: nowrap;\n  position: sticky;\n  top: 0;\n  z-index: 1;\n}\n\n.ap-table td {\n  padding: 10px 12px;\n  border-bottom: 1px solid var(--ap-line);\n  vertical-align: middle;\n}\n\n.ap-table tbody tr:hover td {\n  background: #fafbfc;\n}\n\n.ap-table tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.ap-table .ap-right,\n.ap-right {\n  text-align: right;\n}\n\n.ap-table a {\n  color: var(--ap-brand-ink);\n  font-weight: 550;\n  text-decoration: none;\n}\n\n.ap-table a:hover {\n  text-decoration: underline;\n}\n\n.ap-rowclick {\n  cursor: pointer;\n}\n\n.ap-sub {\n  font-size: 12px;\n  color: var(--ap-ink-3);\n}\n\n.ap-strong {\n  font-weight: 650;\n}\n\n/* --------------------------------------------------------------------------\n   pills\n   -------------------------------------------------------------------------- */\n.ap-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 11.5px;\n  font-weight: 650;\n  padding: 2px 8px;\n  border-radius: 999px;\n  border: 1px solid transparent;\n  white-space: nowrap;\n}\n\n.ap-pill-paid {\n  background: var(--ap-brand-soft);\n  color: var(--ap-brand-ink);\n  border-color: var(--ap-brand-line);\n}\n\n.ap-pill-part {\n  background: var(--ap-warn-soft);\n  color: var(--ap-warn);\n  border-color: #f0dcb6;\n}\n\n.ap-pill-unpaid {\n  background: var(--ap-danger-soft);\n  color: var(--ap-danger);\n  border-color: #efc9cb;\n}\n\n.ap-pill-cancelled {\n  background: var(--ap-sunken);\n  color: var(--ap-ink-3);\n  border-color: var(--ap-line-strong);\n  text-decoration: line-through;\n}\n\n.ap-pill-info {\n  background: var(--ap-info-soft);\n  color: var(--ap-info);\n  border-color: #c9dcf3;\n}\n\n/* --------------------------------------------------------------------------\n   empty and loading\n   -------------------------------------------------------------------------- */\n.ap-empty {\n  text-align: center;\n  padding: 44px 20px;\n  color: var(--ap-ink-2);\n}\n\n.ap-empty svg {\n  color: var(--ap-line-strong);\n  margin-bottom: 10px;\n}\n\n.ap-empty h3 {\n  margin: 0 0 5px;\n  font-size: 15.5px;\n  color: var(--ap-ink);\n}\n\n.ap-empty p {\n  margin: 0 auto 14px;\n  max-width: 44ch;\n  font-size: 13.5px;\n  color: var(--ap-ink-3);\n}\n\n.ap-spin {\n  width: 17px;\n  height: 17px;\n  border: 2px solid currentColor;\n  border-right-color: transparent;\n  border-radius: 50%;\n  display: inline-block;\n  animation: ap-spin 0.65s linear infinite;\n  vertical-align: -3px;\n}\n\n@keyframes ap-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ap-spin {\n    animation-duration: 1.6s;\n  }\n}\n\n.ap-skel {\n  background: linear-gradient(90deg, var(--ap-sunken) 25%, #e7eaee 37%, var(--ap-sunken) 63%);\n  background-size: 400% 100%;\n  animation: ap-sheen 1.2s ease-in-out infinite;\n  border-radius: 5px;\n  height: 13px;\n}\n\n@keyframes ap-sheen {\n  0% {\n    background-position: 100% 50%;\n  }\n  100% {\n    background-position: 0 50%;\n  }\n}\n\n/* --------------------------------------------------------------------------\n   notices\n   -------------------------------------------------------------------------- */\n.ap-note {\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n  padding: 11px 13px;\n  border-radius: var(--ap-radius-sm);\n  font-size: 13.5px;\n  border: 1px solid;\n}\n\n.ap-note svg {\n  flex: 0 0 auto;\n  margin-top: 1px;\n}\n\n.ap-note-warn {\n  background: var(--ap-warn-soft);\n  border-color: #f0dcb6;\n  color: #6f4a00;\n}\n\n.ap-note-bad {\n  background: var(--ap-danger-soft);\n  border-color: #efc9cb;\n  color: #8a1c22;\n}\n\n.ap-note-info {\n  background: var(--ap-info-soft);\n  border-color: #c9dcf3;\n  color: #16477d;\n}\n\n.ap-note-good {\n  background: var(--ap-brand-soft);\n  border-color: var(--ap-brand-line);\n  color: var(--ap-brand-ink);\n}\n\n/* --------------------------------------------------------------------------\n   modal\n   -------------------------------------------------------------------------- */\n.ap-backdrop {\n  position: fixed;\n  inset: 0;\n  background: rgba(12, 17, 24, 0.5);\n  display: grid;\n  place-items: start center;\n  padding: 24px 16px;\n  overflow-y: auto;\n  z-index: 100;\n  animation: ap-fade 0.12s ease-out;\n}\n\n@keyframes ap-fade {\n  from {\n    opacity: 0;\n  }\n}\n\n.ap-modal {\n  background: var(--ap-panel);\n  border-radius: 12px;\n  box-shadow: var(--ap-shadow-lift);\n  width: 100%;\n  max-width: 540px;\n  margin: auto 0;\n  animation: ap-pop 0.14s ease-out;\n}\n\n.ap-modal-wide {\n  max-width: 760px;\n}\n\n@keyframes ap-pop {\n  from {\n    transform: translateY(8px) scale(0.99);\n    opacity: 0;\n  }\n}\n\n.ap-modal-head {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 14px 16px;\n  border-bottom: 1px solid var(--ap-line);\n}\n\n.ap-modal-head h2 {\n  margin: 0;\n  font-size: 16px;\n  font-weight: 650;\n}\n\n.ap-modal-x {\n  margin-left: auto;\n  border: 0;\n  background: none;\n  padding: 5px;\n  border-radius: 6px;\n  color: var(--ap-ink-3);\n  cursor: pointer;\n}\n\n.ap-modal-x:hover {\n  background: var(--ap-sunken);\n  color: var(--ap-ink);\n}\n\n.ap-modal-body {\n  padding: 16px;\n}\n\n.ap-modal-foot {\n  display: flex;\n  gap: 8px;\n  justify-content: flex-end;\n  padding: 13px 16px;\n  border-top: 1px solid var(--ap-line);\n  background: var(--ap-sunken);\n  border-radius: 0 0 12px 12px;\n}\n\n/* --------------------------------------------------------------------------\n   toasts\n   -------------------------------------------------------------------------- */\n.ap-toasts {\n  position: fixed;\n  bottom: 18px;\n  left: 50%;\n  transform: translateX(-50%);\n  display: grid;\n  gap: 8px;\n  z-index: 200;\n  width: max-content;\n  max-width: calc(100vw - 32px);\n}\n\n.ap-toast {\n  background: #10151c;\n  color: #fff;\n  padding: 10px 15px;\n  border-radius: 999px;\n  font-size: 13.5px;\n  font-weight: 550;\n  box-shadow: var(--ap-shadow-lift);\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  animation: ap-rise 0.16s ease-out;\n}\n\n@keyframes ap-rise {\n  from {\n    transform: translateY(10px);\n    opacity: 0;\n  }\n}\n\n.ap-toast-good svg {\n  color: #4fe0a8;\n}\n\n.ap-toast-bad {\n  background: #7d1218;\n}\n\n/* --------------------------------------------------------------------------\n   the billing screen\n   -------------------------------------------------------------------------- */\n.ap-bill {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 346px;\n  gap: 0;\n  align-items: start;\n  min-height: calc(100vh - var(--ap-topbar));\n}\n\n.ap-bill-left {\n  padding: 16px 18px 120px;\n  min-width: 0;\n}\n\n.ap-bill-right {\n  position: sticky;\n  top: var(--ap-topbar);\n  height: calc(100vh - var(--ap-topbar));\n  overflow-y: auto;\n  background: var(--ap-panel);\n  border-left: 1px solid var(--ap-line);\n  padding: 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.ap-bill-head {\n  display: flex;\n  gap: 12px;\n  align-items: flex-end;\n  flex-wrap: wrap;\n  margin-bottom: 14px;\n}\n\n.ap-bill-head > * {\n  min-width: 0;\n}\n\n/* the item search box, big on purpose - it is the one thing you aim at */\n.ap-addbar {\n  position: relative;\n  margin-bottom: 12px;\n}\n\n.ap-addbar .ap-input {\n  min-height: 48px;\n  font-size: 15.5px;\n  padding-left: 40px;\n}\n\n.ap-addbar-ico {\n  position: absolute;\n  left: 12px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--ap-brand);\n  pointer-events: none;\n}\n\n.ap-suggest {\n  position: absolute;\n  z-index: 40;\n  left: 0;\n  right: 0;\n  top: calc(100% + 5px);\n  background: var(--ap-panel);\n  border: 1px solid var(--ap-line-strong);\n  border-radius: var(--ap-radius);\n  box-shadow: var(--ap-shadow-lift);\n  max-height: 340px;\n  overflow-y: auto;\n  padding: 5px;\n}\n\n.ap-suggest-item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 9px 10px;\n  border-radius: var(--ap-radius-sm);\n  cursor: pointer;\n  border: 0;\n  background: none;\n  width: 100%;\n  text-align: left;\n  font: inherit;\n}\n\n.ap-suggest-item[data-active=\"true\"],\n.ap-suggest-item:hover {\n  background: var(--ap-brand-soft);\n}\n\n.ap-suggest-name {\n  font-weight: 550;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ap-suggest-meta {\n  font-size: 12px;\n  color: var(--ap-ink-3);\n}\n\n.ap-suggest-right {\n  margin-left: auto;\n  text-align: right;\n  flex: 0 0 auto;\n}\n\n.ap-suggest-new {\n  border-top: 1px solid var(--ap-line);\n  margin-top: 5px;\n  padding-top: 5px;\n}\n\n.ap-suggest-empty {\n  padding: 14px 10px;\n  color: var(--ap-ink-3);\n  font-size: 13.5px;\n  text-align: center;\n}\n\n/* the lines */\n.ap-lines {\n  width: 100%;\n  border-collapse: collapse;\n  background: var(--ap-panel);\n  border: 1px solid var(--ap-line);\n  border-radius: var(--ap-radius);\n  overflow: hidden;\n}\n\n.ap-lines th {\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--ap-ink-3);\n  font-weight: 650;\n  text-align: left;\n  padding: 8px 10px;\n  background: var(--ap-sunken);\n  border-bottom: 1px solid var(--ap-line);\n  white-space: nowrap;\n}\n\n.ap-lines td {\n  padding: 6px 8px;\n  border-bottom: 1px solid var(--ap-line);\n  vertical-align: middle;\n}\n\n.ap-lines tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.ap-lines .ap-input {\n  min-height: 34px;\n  padding: 5px 8px;\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n}\n\n.ap-lines .ap-select {\n  min-height: 34px;\n  padding: 5px 6px;\n}\n\n.ap-line-name {\n  font-weight: 550;\n  font-size: 14px;\n}\n\n.ap-line-sub {\n  font-size: 11.5px;\n  color: var(--ap-ink-3);\n}\n\n.ap-line-x {\n  border: 0;\n  background: none;\n  color: var(--ap-ink-3);\n  padding: 5px;\n  border-radius: 5px;\n  cursor: pointer;\n}\n\n.ap-line-x:hover {\n  background: var(--ap-danger-soft);\n  color: var(--ap-danger);\n}\n\n.ap-col-qty {\n  width: 86px;\n}\n\n.ap-col-rate {\n  width: 104px;\n}\n\n.ap-col-disc {\n  width: 80px;\n}\n\n.ap-col-tax {\n  width: 92px;\n}\n\n.ap-col-amt {\n  width: 112px;\n}\n\n.ap-col-x {\n  width: 34px;\n}\n\n/* the totals block in the right rail */\n.ap-tot {\n  display: grid;\n  gap: 6px;\n  font-size: 13.5px;\n}\n\n.ap-tot-row {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n  color: var(--ap-ink-2);\n}\n\n.ap-tot-row span:last-child {\n  font-variant-numeric: tabular-nums;\n  color: var(--ap-ink);\n}\n\n.ap-tot-grand {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 12px;\n  border-top: 1.5px solid var(--ap-ink);\n  margin-top: 6px;\n  padding-top: 9px;\n  font-weight: 700;\n}\n\n.ap-tot-grand .ap-tot-amt {\n  font-size: 25px;\n  letter-spacing: -0.02em;\n  font-variant-numeric: tabular-nums;\n}\n\n.ap-tot-words {\n  font-size: 11.5px;\n  color: var(--ap-ink-3);\n  text-align: right;\n  line-height: 1.35;\n}\n\n.ap-paychips {\n  display: flex;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n\n.ap-paychip {\n  border: 1px solid var(--ap-line-strong);\n  background: var(--ap-panel);\n  border-radius: 999px;\n  padding: 5px 12px;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 550;\n  cursor: pointer;\n  color: var(--ap-ink-2);\n}\n\n.ap-paychip[aria-pressed=\"true\"] {\n  background: var(--ap-brand);\n  border-color: var(--ap-brand);\n  color: #fff;\n}\n\n.ap-sticky-save {\n  position: sticky;\n  bottom: 0;\n  background: var(--ap-panel);\n  padding-top: 12px;\n  border-top: 1px solid var(--ap-line);\n  display: grid;\n  gap: 8px;\n}\n\n/* the \"bill saved\" panel */\n.ap-done {\n  text-align: center;\n  padding: 10px 0 4px;\n}\n\n.ap-done-tick {\n  width: 52px;\n  height: 52px;\n  border-radius: 50%;\n  background: var(--ap-brand-soft);\n  color: var(--ap-brand);\n  display: grid;\n  place-items: center;\n  margin: 0 auto 10px;\n}\n\n.ap-done-num {\n  font-family: var(--ap-mono);\n  font-size: 13.5px;\n  color: var(--ap-ink-2);\n}\n\n.ap-done-amt {\n  font-size: 28px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  font-variant-numeric: tabular-nums;\n}\n\n/* --------------------------------------------------------------------------\n   keyboard help\n   -------------------------------------------------------------------------- */\n.ap-keys {\n  display: grid;\n  gap: 7px;\n}\n\n.ap-keys-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-size: 13.5px;\n}\n\nkbd.ap-kbd {\n  font-family: var(--ap-mono);\n  font-size: 11.5px;\n  background: var(--ap-sunken);\n  border: 1px solid var(--ap-line-strong);\n  border-bottom-width: 2px;\n  border-radius: 5px;\n  padding: 2px 6px;\n  color: var(--ap-ink-2);\n  white-space: nowrap;\n}\n\n/* --------------------------------------------------------------------------\n   responsive\n   -------------------------------------------------------------------------- */\n@media (max-width: 1100px) {\n  .ap-bill {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .ap-bill-right {\n    position: static;\n    height: auto;\n    border-left: 0;\n    border-top: 1px solid var(--ap-line);\n  }\n\n  .ap-bill-left {\n    padding-bottom: 16px;\n  }\n}\n\n@media (max-width: 1000px) {\n  .ap-tiles {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 860px) {\n  .ap-shell {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .ap-side {\n    position: fixed;\n    inset: 0 auto 0 0;\n    width: 258px;\n    z-index: 120;\n    transform: translateX(-100%);\n    transition: transform 0.16s ease-out;\n    box-shadow: var(--ap-shadow-lift);\n  }\n\n  .ap-side[data-open=\"true\"] {\n    transform: none;\n  }\n\n  .ap-scrim {\n    position: fixed;\n    inset: 0;\n    background: rgba(12, 17, 24, 0.45);\n    z-index: 110;\n  }\n\n  .ap-burger {\n    display: inline-flex;\n  }\n\n  .ap-body {\n    padding: 14px;\n  }\n\n  .ap-grid3,\n  .ap-grid2 {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n@media (max-width: 560px) {\n  .ap-root {\n    font-size: 15px;\n  }\n\n  .ap-tiles {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .ap-bill-left,\n  .ap-bill-right {\n    padding: 12px;\n  }\n\n  .ap-top {\n    padding: 0 12px;\n  }\n\n  .ap-title {\n    font-size: 15px;\n  }\n}\n\n/* --------------------------------------------------------------------------\n   print\n   --------------------------------------------------------------------------\n   The app's chrome is for the screen. When something is printed, only the\n   print sheet should be on the paper.\n   -------------------------------------------------------------------------- */\n.ap-printonly {\n  display: none;\n}\n\n@media print {\n  .ap-side,\n  .ap-top,\n  .ap-toasts,\n  .ap-backdrop,\n  .ap-noprint {\n    display: none !important;\n  }\n\n  .ap-shell {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .ap-root {\n    background: #fff;\n  }\n\n  .ap-body,\n  .ap-bill-left {\n    padding: 0;\n  }\n\n  .ap-printonly {\n    display: block;\n  }\n\n  .ap-screenonly {\n    display: none !important;\n  }\n}\n","components/app/billing/Billing.js":"\"use client\";\n\n// ===========================================================================\n// MAKING A BILL\n// ---------------------------------------------------------------------------\n// The screen the whole product is judged on. The rule it is built to is:\n// a shopkeeper with four items and a queue should get from an empty screen\n// to a printed bill without touching the mouse, and without waiting for the\n// network between keystrokes.\n//\n// So the totals are worked out in the browser as you type, and the server is\n// only asked once, when you save. The server's answer is then what is shown\n// and printed - the browser's arithmetic is a preview and never the record.\n//\n// One thing worth knowing about saving: the bill and the payment are two\n// requests. The bill itself is atomic on the server - number, lines, stock\n// and the customer's balance all commit together or not at all. The payment\n// is recorded straight after. If the payment call fails, the bill still\n// exists and is simply unpaid, and the screen says so and offers to record\n// the payment again. That is recoverable; a half-written bill would not be.\n// ===========================================================================\n\nimport { useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { BILLING, COMMON, PAYMENT } from \"../content\";\nimport { useShop } from \"../useShop\";\nimport { useToast } from \"../ui/Toast\";\nimport { Note } from \"../ui/Bits\";\nimport { Select, Text, Money, Check, numericOnly } from \"../ui/Field\";\nimport ItemSearch from \"./ItemSearch\";\nimport PartyPicker from \"./PartyPicker\";\nimport Lines from \"./Lines\";\nimport ItemForm from \"../items/ItemForm\";\nimport PartyForm from \"../parties/PartyForm\";\nimport { computeTotals, isInterState } from \"../../../lib/gst-calc\";\nimport { rupees, paiseToWords, today, toPaise } from \"../../../lib/money\";\nimport { PAYMENT_MODES } from \"../../../lib/units\";\nimport { createInvoice, createPayment, getParty, getBusiness } from \"../data\";\nimport InvoicePrint from \"../print/InvoicePrint\";\nimport {\n  IconCheck,\n  IconPrint,\n  IconWhatsApp,\n  IconPlus,\n  IconKeyboard,\n  IconWarn,\n} from \"../Icons\";\n\nlet keyCounter = 0;\n\nfunction lineFromItem(item) {\n  return {\n    key: `l${++keyCounter}`,\n    itemId: item.id,\n    name: item.name,\n    hsn: item.hsn,\n    unit: item.unit,\n    type: item.type,\n    stock: item.type === \"service\" ? null : item.stock,\n    quantity: \"1\",\n    rate: item.salePaise ? String(item.salePaise / 100) : \"\",\n    discountPercent: \"\",\n    taxRate: item.taxRate ?? 0,\n    taxIncluded: Boolean(item.taxIncluded),\n  };\n}\n\nexport default function Billing() {\n  const shop = useShop();\n  const { toast, error } = useToast();\n\n  const [docType, setDocType] = useState(\"sale\");\n  const [party, setParty] = useState(null);\n  const [date, setDate] = useState(() => today());\n  const [lines, setLines] = useState([]);\n  const [extraDiscount, setExtraDiscount] = useState(\"\");\n  const [notes, setNotes] = useState(\"\");\n\n  const [received, setReceived] = useState(\"\");\n  const [touchedReceived, setTouchedReceived] = useState(false);\n  const [mode, setMode] = useState(\"cash\");\n\n  const [newItemName, setNewItemName] = useState(null);\n  const [newPartyName, setNewPartyName] = useState(null);\n\n  const [busy, setBusy] = useState(false);\n  const [saved, setSaved] = useState(null);\n  const [paymentFailed, setPaymentFailed] = useState(false);\n  const [err, setErr] = useState(null);\n  const [showKeys, setShowKeys] = useState(false);\n\n  const itemInput = useRef(null);\n  const partyInput = useRef(null);\n\n  // The sidebar only knows the shop's name. A printed tax invoice needs its\n  // address and GSTIN too, so the full record is fetched once.\n  const [shopFull, setShopFull] = useState(null);\n  useEffect(() => {\n    if (!shop.businessId) return;\n    let alive = true;\n    getBusiness(shop.businessId)\n      .then((b) => {\n        if (alive) setShopFull(b);\n      })\n      .catch(() => {});\n    return () => {\n      alive = false;\n    };\n  }, [shop.businessId]);\n\n  const isPurchaseSide = docType === \"purchase\" || docType === \"debit_note\";\n\n  // --------------------------------------------------------------------\n  // the arithmetic\n  // --------------------------------------------------------------------\n  const interState = useMemo(\n    () => isInterState(shop.stateCode, party?.stateCode),\n    [shop.stateCode, party]\n  );\n\n  const computed = useMemo(\n    () =>\n      computeTotals(\n        lines.map((l) => ({\n          quantity: Number(l.quantity) || 0,\n          ratePaise: toPaise(l.rate),\n          taxRate: Number(l.taxRate) || 0,\n          discountPercent: Number(l.discountPercent) || 0,\n          taxIncluded: l.taxIncluded,\n        })),\n        { interState, extraDiscountPaise: toPaise(extraDiscount) }\n      ),\n    [lines, interState, extraDiscount]\n  );\n\n  // A sale is assumed to be paid in full unless the shopkeeper says\n  // otherwise. That is what happens at a counter nine times out of ten, and\n  // the one time it does not, one tap on \"Credit\" fixes it.\n  useEffect(() => {\n    if (touchedReceived || saved) return;\n    if (docType === \"estimate\") return;\n    setReceived(computed.total ? String(computed.total / 100) : \"\");\n  }, [computed.total, touchedReceived, saved, docType]);\n\n  const receivedPaise = Math.max(0, toPaise(received));\n  const duePaise = Math.max(0, computed.total - receivedPaise);\n  const overpaid = receivedPaise > computed.total;\n\n  // --------------------------------------------------------------------\n  // line handling\n  // --------------------------------------------------------------------\n  function addItem(item) {\n    setLines((prev) => {\n      // The same item twice means \"two of them\", not two lines. Scanning a\n      // barcode three times should read as quantity 3.\n      const at = prev.findIndex((l) => l.itemId === item.id);\n      if (at >= 0) {\n        const next = [...prev];\n        next[at] = { ...next[at], quantity: String((Number(next[at].quantity) || 0) + 1) };\n        return next;\n      }\n      return [...prev, lineFromItem(item)];\n    });\n  }\n\n  function changeLine(i, patch) {\n    setLines((prev) => {\n      const next = [...prev];\n      next[i] = { ...next[i], ...patch };\n      return next;\n    });\n  }\n\n  function removeLine(i) {\n    setLines((prev) => prev.filter((_, x) => x !== i));\n  }\n\n  function reset() {\n    setLines([]);\n    setParty(null);\n    setExtraDiscount(\"\");\n    setNotes(\"\");\n    setReceived(\"\");\n    setTouchedReceived(false);\n    setSaved(null);\n    setPaymentFailed(false);\n    setErr(null);\n    setDate(today());\n    setTimeout(() => itemInput.current?.focus(), 30);\n  }\n\n  // --------------------------------------------------------------------\n  // shortcuts\n  // --------------------------------------------------------------------\n  useEffect(() => {\n    itemInput.current?.focus();\n  }, []);\n\n  useEffect(() => {\n    const onKey = (e) => {\n      if (e.key === \"F2\") {\n        e.preventDefault();\n        itemInput.current?.focus();\n        return;\n      }\n      if (e.key === \"F4\") {\n        e.preventDefault();\n        partyInput.current?.focus();\n        return;\n      }\n      if (e.altKey && (e.key === \"s\" || e.key === \"S\")) {\n        e.preventDefault();\n        save(false);\n        return;\n      }\n      if (e.altKey && (e.key === \"p\" || e.key === \"P\")) {\n        e.preventDefault();\n        save(true);\n      }\n    };\n    window.addEventListener(\"keydown\", onKey);\n    return () => window.removeEventListener(\"keydown\", onKey);\n  });\n\n  // --------------------------------------------------------------------\n  // saving\n  // --------------------------------------------------------------------\n  async function save(thenPrint) {\n    if (busy || saved) return;\n    setErr(null);\n\n    if (!lines.length) {\n      error(BILLING.needLines);\n      itemInput.current?.focus();\n      return;\n    }\n    if (overpaid) {\n      error(BILLING.overpaid);\n      return;\n    }\n    // Credit with nobody's name against it is money you will never see\n    // again, so this one is worth refusing.\n    if (!party && duePaise > 0 && docType !== \"estimate\") {\n      error(BILLING.needPartyCredit);\n      partyInput.current?.focus();\n      return;\n    }\n\n    setBusy(true);\n    try {\n      const payload = {\n        docType,\n        date,\n        lines: lines.map((l) => ({\n          itemId: l.itemId,\n          quantity: Number(l.quantity) || 0,\n          rate: Number(l.rate) || 0,\n          taxRate: Number(l.taxRate) || 0,\n          discountPercent: Number(l.discountPercent) || 0,\n        })),\n      };\n      if (party) payload.partyId = party.id;\n      if (notes.trim()) payload.notes = notes.trim();\n      const extra = toPaise(extraDiscount);\n      if (extra > 0) payload.discount = extra / 100;\n\n      const invoice = await createInvoice(payload);\n\n      // The payment, if any. Allocated against this bill so it shows as\n      // paid rather than floating on the customer's account.\n      let failed = false;\n      if (receivedPaise > 0 && docType !== \"estimate\") {\n        try {\n          await createPayment({\n            direction: isPurchaseSide ? \"out\" : \"in\",\n            partyId: party ? party.id : undefined,\n            amountRupees: receivedPaise / 100,\n            mode,\n            date,\n            allocations: [{ invoiceId: invoice.id, amount: receivedPaise / 100 }],\n          });\n        } catch {\n          failed = true;\n        }\n      }\n\n      // What the screen and the paper show from here on is the server's own\n      // total, not the preview. If the two ever differ, the server is right.\n      // The paid figure is folded in because the payment was a second call\n      // and the invoice we were handed back predates it.\n      const paid = failed ? 0 : Math.min(receivedPaise, invoice.amounts.total);\n      setPaymentFailed(failed);\n      setSaved({\n        ...invoice,\n        amounts: {\n          ...invoice.amounts,\n          paid,\n          balance: Math.max(0, invoice.amounts.total - paid),\n        },\n      });\n      toast(`${BILLING.savedTitle} · ${invoice.number || \"\"}`.trim());\n\n      if (thenPrint && !failed) {\n        // Let the panel paint before the print dialog takes over.\n        setTimeout(() => window.print(), 220);\n      }\n    } catch (e) {\n      setErr(e.isOffline ? COMMON.offlineBody : e.message || COMMON.genericError);\n      error(e.isOffline ? COMMON.offlineTitle : e.message || COMMON.genericError);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  // --------------------------------------------------------------------\n  // WhatsApp\n  // --------------------------------------------------------------------\n  // A link, not an integration. It opens WhatsApp with the message ready,\n  // and the shopkeeper presses send. No API, no fees, no approval, and it\n  // works from a phone and a desktop alike.\n  function whatsappHref(invoice) {\n    const shopName = shop.shop?.name || \"our shop\";\n    const text = [\n      `${shopName}`,\n      `Bill ${invoice.number}`,\n      `Amount ${rupees(invoice.amounts.total)}`,\n      duePaise > 0 ? `Pending ${rupees(duePaise)}` : \"Paid. Thank you.\",\n    ].join(\"\\n\");\n    const phone = party?.phone ? `91${String(party.phone).replace(/\\D+/g, \"\").slice(-10)}` : \"\";\n    return `https://wa.me/${phone}?text=${encodeURIComponent(text)}`;\n  }\n\n  // What the printer gets if the server did not send the lines back with the\n  // saved bill. The amounts come from the same computation the screen showed,\n  // so the paper and the screen cannot disagree.\n  const printLines = useMemo(\n    () =>\n      lines.map((l, i) => {\n        const c = computed.lines[i] || {};\n        return {\n          name: l.name,\n          hsn: l.hsn,\n          unit: l.unit,\n          quantity: Number(l.quantity) || 0,\n          ratePaise: toPaise(l.rate),\n          taxRate: Number(l.taxRate) || 0,\n          taxablePaise: c.taxable || 0,\n          cgstPaise: c.cgst || 0,\n          sgstPaise: c.sgst || 0,\n          igstPaise: c.igst || 0,\n          totalPaise: c.total || 0,\n        };\n      }),\n    [lines, computed]\n  );\n\n  // --------------------------------------------------------------------\n  return (\n    <div className=\"ap-bill\">\n      <div className=\"ap-bill-left ap-screenonly\">\n        {err ? (\n          <div style={{ marginBottom: 12 }}>\n            <Note kind=\"bad\">{err}</Note>\n          </div>\n        ) : null}\n\n        <div className=\"ap-bill-head\">\n          <div>\n            <label className=\"ap-label\">Bill type</label>\n            <div className=\"ap-seg\">\n              {BILLING.docTypes.map((d) => (\n                <button\n                  key={d.value}\n                  type=\"button\"\n                  aria-pressed={docType === d.value}\n                  onClick={() => {\n                    setDocType(d.value);\n                    setTouchedReceived(false);\n                  }}\n                  disabled={Boolean(saved)}\n                >\n                  {d.label}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          <div style={{ width: 150 }}>\n            <Text\n              label={BILLING.dateLabel}\n              type=\"date\"\n              value={date}\n              onChange={(e) => setDate(e.target.value)}\n              disabled={Boolean(saved)}\n            />\n          </div>\n        </div>\n\n        <p className=\"ap-hint\" style={{ marginTop: -8, marginBottom: 12 }}>\n          {BILLING.docHelp[docType]}\n        </p>\n\n        <div style={{ maxWidth: 560, marginBottom: 14 }}>\n          <PartyPicker\n            value={party}\n            forSupplier={isPurchaseSide}\n            inputRef={partyInput}\n            onPick={setParty}\n            onClear={() => setParty(null)}\n            onCreate={(name) => setNewPartyName(name || \"\")}\n          />\n        </div>\n\n        {!saved ? (\n          <ItemSearch\n            inputRef={itemInput}\n            onPick={addItem}\n            onCreate={(name) => setNewItemName(name || \"\")}\n          />\n        ) : null}\n\n        <Lines\n          lines={lines}\n          computed={computed}\n          docType={docType}\n          onChange={changeLine}\n          onRemove={removeLine}\n        />\n\n        {lines.length ? (\n          <div className=\"ap-row\" style={{ marginTop: 12, alignItems: \"flex-start\", gap: 16 }}>\n            <div style={{ width: 180 }}>\n              <Money\n                label={BILLING.extraDiscount}\n                value={extraDiscount}\n                onChange={(e) => setExtraDiscount(numericOnly(e.target.value))}\n                placeholder=\"0.00\"\n                disabled={Boolean(saved)}\n              />\n            </div>\n            <div style={{ flex: 1, minWidth: 220 }}>\n              <Text\n                label=\"Note on the bill\"\n                value={notes}\n                onChange={(e) => setNotes(e.target.value)}\n                placeholder=\"Anything you want printed on it\"\n                disabled={Boolean(saved)}\n                maxLength={300}\n              />\n            </div>\n          </div>\n        ) : null}\n\n        <button\n          type=\"button\"\n          className=\"ap-btn ap-btn-ghost ap-btn-sm ap-noprint\"\n          style={{ marginTop: 16, color: \"var(--ap-ink-3)\" }}\n          onClick={() => setShowKeys((v) => !v)}\n        >\n          <IconKeyboard size={16} />\n          {BILLING.shortcuts}\n        </button>\n\n        {showKeys ? (\n          <div className=\"ap-panel\" style={{ marginTop: 8, maxWidth: 420 }}>\n            <div className=\"ap-panel-body ap-keys\">\n              {BILLING.keys.map((k) => (\n                <div className=\"ap-keys-row\" key={k.keys}>\n                  <kbd className=\"ap-kbd\">{k.keys}</kbd>\n                  <span>{k.what}</span>\n                </div>\n              ))}\n            </div>\n          </div>\n        ) : null}\n      </div>\n\n      {/* ---------------------------------------------------------------- */}\n      <aside className=\"ap-bill-right ap-screenonly\">\n        {saved ? (\n          <SavedPanel\n            invoice={saved}\n            paymentFailed={paymentFailed}\n            onNew={reset}\n            whatsappHref={whatsappHref}\n            hasPhone={Boolean(party?.phone)}\n          />\n        ) : (\n          <>\n            <div className=\"ap-tot\">\n              <div className=\"ap-tot-row\">\n                <span>{BILLING.subtotal}</span>\n                <span>{rupees(computed.gross)}</span>\n              </div>\n\n              {computed.discount ? (\n                <div className=\"ap-tot-row\">\n                  <span>{BILLING.discount}</span>\n                  <span style={{ color: \"var(--ap-danger)\" }}>- {rupees(computed.discount)}</span>\n                </div>\n              ) : null}\n\n              <div className=\"ap-tot-row\">\n                <span>{BILLING.taxable}</span>\n                <span>{rupees(computed.taxable)}</span>\n              </div>\n\n              {interState ? (\n                computed.igst ? (\n                  <div className=\"ap-tot-row\">\n                    <span>IGST</span>\n                    <span>{rupees(computed.igst)}</span>\n                  </div>\n                ) : null\n              ) : (\n                <>\n                  {computed.cgst ? (\n                    <div className=\"ap-tot-row\">\n                      <span>CGST</span>\n                      <span>{rupees(computed.cgst)}</span>\n                    </div>\n                  ) : null}\n                  {computed.sgst ? (\n                    <div className=\"ap-tot-row\">\n                      <span>SGST</span>\n                      <span>{rupees(computed.sgst)}</span>\n                    </div>\n                  ) : null}\n                </>\n              )}\n\n              {computed.roundOff ? (\n                <div className=\"ap-tot-row\">\n                  <span>{BILLING.roundOff}</span>\n                  <span>\n                    {computed.roundOff > 0 ? \"+\" : \"-\"} {rupees(Math.abs(computed.roundOff))}\n                  </span>\n                </div>\n              ) : null}\n\n              <div className=\"ap-tot-grand\">\n                <span>{BILLING.total}</span>\n                <span className=\"ap-tot-amt\">{rupees(computed.total)}</span>\n              </div>\n\n              {computed.total ? (\n                <div className=\"ap-tot-words\">{paiseToWords(computed.total)}</div>\n              ) : null}\n            </div>\n\n            {computed.tax ? (\n              <p className=\"ap-hint\" style={{ margin: 0 }}>\n                {interState ? BILLING.igstNote : BILLING.gstNote}\n              </p>\n            ) : null}\n\n            {docType !== \"estimate\" ? (\n              <div style={{ borderTop: \"1px solid var(--ap-line)\", paddingTop: 13 }}>\n                <div className=\"ap-label\" style={{ marginBottom: 7 }}>\n                  {BILLING.payTitle}\n                </div>\n\n                <div className=\"ap-paychips\" style={{ marginBottom: 10 }}>\n                  <button\n                    type=\"button\"\n                    className=\"ap-paychip\"\n                    aria-pressed={receivedPaise === computed.total && computed.total > 0}\n                    onClick={() => {\n                      setTouchedReceived(true);\n                      setReceived(computed.total ? String(computed.total / 100) : \"\");\n                    }}\n                  >\n                    {BILLING.payFull}\n                  </button>\n                  <button\n                    type=\"button\"\n                    className=\"ap-paychip\"\n                    aria-pressed={receivedPaise === 0}\n                    onClick={() => {\n                      setTouchedReceived(true);\n                      setReceived(\"\");\n                    }}\n                  >\n                    {BILLING.payNone}\n                  </button>\n                </div>\n\n                <div className=\"ap-grid2\">\n                  <Money\n                    label={BILLING.payAmount}\n                    value={received}\n                    onChange={(e) => {\n                      setTouchedReceived(true);\n                      setReceived(numericOnly(e.target.value));\n                    }}\n                    placeholder=\"0.00\"\n                    error={overpaid ? BILLING.overpaid : undefined}\n                  />\n                  <Select\n                    label={BILLING.payMode}\n                    value={mode}\n                    onChange={(e) => setMode(e.target.value)}\n                    disabled={receivedPaise <= 0}\n                  >\n                    {PAYMENT_MODES.map((m) => (\n                      <option key={m.value} value={m.value}>\n                        {m.label}\n                      </option>\n                    ))}\n                  </Select>\n                </div>\n\n                {duePaise > 0 ? (\n                  <div\n                    className=\"ap-tot-row\"\n                    style={{ marginTop: 10, fontWeight: 650, color: \"var(--ap-danger)\" }}\n                  >\n                    <span>{BILLING.payBalance}</span>\n                    <span>{rupees(duePaise)}</span>\n                  </div>\n                ) : null}\n              </div>\n            ) : null}\n\n            <div className=\"ap-sticky-save ap-noprint\">\n              <button\n                type=\"button\"\n                className=\"ap-btn ap-btn-primary ap-btn-lg ap-btn-block\"\n                onClick={() => save(true)}\n                disabled={busy || !lines.length}\n              >\n                {busy ? (\n                  <>\n                    <span className=\"ap-spin\" /> {BILLING.savingBill}\n                  </>\n                ) : (\n                  <>\n                    <IconPrint size={18} /> {BILLING.saveAndPrint}\n                  </>\n                )}\n              </button>\n              <button\n                type=\"button\"\n                className=\"ap-btn ap-btn-block\"\n                onClick={() => save(false)}\n                disabled={busy || !lines.length}\n              >\n                {BILLING.saveOnly}\n              </button>\n            </div>\n          </>\n        )}\n      </aside>\n\n      {newItemName !== null ? (\n        <ItemForm\n          initialName={newItemName}\n          onClose={() => setNewItemName(null)}\n          onSaved={(item) => {\n            setNewItemName(null);\n            if (item) addItem(item);\n            setTimeout(() => itemInput.current?.focus(), 30);\n          }}\n        />\n      ) : null}\n\n      {newPartyName !== null ? (\n        <PartyForm\n          initial={{\n            name: newPartyName,\n            type: isPurchaseSide ? \"supplier\" : \"customer\",\n            stateCode: shop.stateCode || \"\",\n          }}\n          onClose={() => setNewPartyName(null)}\n          onSaved={async (p) => {\n            setNewPartyName(null);\n            // Re-read so the balance shown next to the name is the server's,\n            // not an assumption.\n            try {\n              setParty(p?.id ? await getParty(p.id) : p);\n            } catch {\n              setParty(p);\n            }\n          }}\n        />\n      ) : null}\n\n      {saved ? (\n        <InvoicePrint\n          invoice={saved}\n          shop={shopFull || shop.shop}\n          party={party}\n          lines={printLines}\n          copyLabel=\"Customer copy\"\n        />\n      ) : null}\n    </div>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// after saving\n// ---------------------------------------------------------------------------\nfunction SavedPanel({ invoice, paymentFailed, onNew, whatsappHref, hasPhone }) {\n  return (\n    <>\n      <div className=\"ap-done\">\n        <div className=\"ap-done-tick\">\n          <IconCheck size={26} />\n        </div>\n        <div className=\"ap-done-num\">{invoice.number}</div>\n        <div className=\"ap-done-amt\">{rupees(invoice.amounts.total)}</div>\n        <div className=\"ap-sub\">{paiseToWords(invoice.amounts.total)}</div>\n      </div>\n\n      {paymentFailed ? (\n        <Note kind=\"warn\" icon={<IconWarn size={17} />}>\n          The bill was saved, but the payment was not recorded. Open the bill and take the payment\n          again &mdash; nothing has been double counted.\n        </Note>\n      ) : null}\n\n      <div style={{ display: \"grid\", gap: 8 }}>\n        <button type=\"button\" className=\"ap-btn ap-btn-primary ap-btn-lg\" onClick={onNew}>\n          <IconPlus size={18} /> {BILLING.savedNext}\n        </button>\n        <button type=\"button\" className=\"ap-btn\" onClick={() => window.print()}>\n          <IconPrint size={17} /> {BILLING.savedPrint}\n        </button>\n        {hasPhone ? (\n          <a\n            className=\"ap-btn\"\n            href={whatsappHref(invoice)}\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >\n            <IconWhatsApp size={17} /> {BILLING.savedShare}\n          </a>\n        ) : null}\n        <Link className=\"ap-btn ap-btn-ghost\" href={`/app/bills/${invoice.id}`}>\n          {BILLING.savedOpen}\n        </Link>\n      </div>\n    </>\n  );\n}\n","components/app/billing/ItemSearch.js":"\"use client\";\n\n// ===========================================================================\n// THE ITEM BOX\n// ---------------------------------------------------------------------------\n// The single most used control in the whole product. A shop doing forty\n// bills an hour touches this a few hundred times a day, so it is built for\n// that and nothing else:\n//\n//   - focused the moment the screen opens, and again after every item added\n//   - type, arrow down, Enter. The mouse is never needed.\n//   - an exact code match is added straight away without a list, which is\n//     what a barcode scanner does: it types the code then sends Enter\n//   - if nothing matches, offering to add it as a new item is the first\n//     option rather than a dead end\n//   - the list is kept short because reading ten lines is slower than typing\n//     two more letters\n// ===========================================================================\n\nimport { useEffect, useMemo, useRef, useState } from \"react\";\nimport { BILLING } from \"../content\";\nimport { IconSearch, IconPlus } from \"../Icons\";\nimport { rupees, formatQty } from \"../../../lib/money\";\nimport { unitShort } from \"../../../lib/units\";\nimport { listItems } from \"../data\";\n\nexport default function ItemSearch({ onPick, onCreate, inputRef, disabled }) {\n  const [q, setQ] = useState(\"\");\n  const [rows, setRows] = useState([]);\n  const [open, setOpen] = useState(false);\n  const [active, setActive] = useState(0);\n  const [loading, setLoading] = useState(false);\n  const box = useRef(null);\n  const own = useRef(null);\n  const input = inputRef || own;\n\n  // Keep the most recent search's answer only. Without this, a slow reply\n  // for \"ba\" can land after \"basmati\" and put the wrong list on screen.\n  const seq = useRef(0);\n\n  useEffect(() => {\n    const term = q.trim();\n    if (!term) {\n      setRows([]);\n      setLoading(false);\n      return undefined;\n    }\n\n    const mine = ++seq.current;\n    setLoading(true);\n\n    // 180ms is about as long as you can wait without it feeling laggy, and\n    // short enough that a four-letter search is one request, not four.\n    const timer = setTimeout(async () => {\n      try {\n        const { rows: found } = await listItems({ search: term, limit: 8 });\n        if (seq.current !== mine) return;\n        setRows(found);\n        setActive(0);\n      } catch {\n        if (seq.current === mine) setRows([]);\n      } finally {\n        if (seq.current === mine) setLoading(false);\n      }\n    }, 180);\n\n    return () => clearTimeout(timer);\n  }, [q]);\n\n  useEffect(() => {\n    const onDown = (e) => {\n      if (box.current && !box.current.contains(e.target)) setOpen(false);\n    };\n    document.addEventListener(\"mousedown\", onDown);\n    return () => document.removeEventListener(\"mousedown\", onDown);\n  }, []);\n\n  const options = useMemo(() => rows, [rows]);\n\n  function take(item) {\n    onPick(item);\n    setQ(\"\");\n    setRows([]);\n    setOpen(false);\n    // Straight back to the box, ready for the next item.\n    input.current?.focus();\n  }\n\n  function makeNew() {\n    onCreate(q.trim());\n    setQ(\"\");\n    setRows([]);\n    setOpen(false);\n  }\n\n  function onKeyDown(e) {\n    if (e.key === \"ArrowDown\") {\n      e.preventDefault();\n      setOpen(true);\n      setActive((i) => Math.min(i + 1, options.length - 1));\n      return;\n    }\n    if (e.key === \"ArrowUp\") {\n      e.preventDefault();\n      setActive((i) => Math.max(i - 1, 0));\n      return;\n    }\n    if (e.key === \"Escape\") {\n      setOpen(false);\n      return;\n    }\n    if (e.key !== \"Enter\") return;\n\n    e.preventDefault();\n    const term = q.trim();\n    if (!term) return;\n\n    // A barcode scanner types the whole code and hits Enter in one burst,\n    // before any suggestion list has had time to render. So an exact code\n    // match wins outright.\n    const exactCode = options.find(\n      (r) => r.code && r.code.toLowerCase() === term.toLowerCase()\n    );\n    if (exactCode) {\n      take(exactCode);\n      return;\n    }\n\n    if (options[active]) {\n      take(options[active]);\n      return;\n    }\n\n    if (!loading) makeNew();\n  }\n\n  const showList = open && Boolean(q.trim());\n\n  return (\n    <div className=\"ap-addbar\" ref={box}>\n      <span className=\"ap-addbar-ico\">\n        <IconSearch size={20} />\n      </span>\n      <input\n        ref={input}\n        className=\"ap-input\"\n        placeholder={BILLING.addItemPlaceholder}\n        value={q}\n        disabled={disabled}\n        onChange={(e) => {\n          setQ(e.target.value);\n          setOpen(true);\n        }}\n        onFocus={() => setOpen(true)}\n        onKeyDown={onKeyDown}\n        autoComplete=\"off\"\n        spellCheck=\"false\"\n        aria-label={BILLING.addItemPlaceholder}\n        aria-expanded={showList}\n        role=\"combobox\"\n        aria-controls=\"ap-item-suggest\"\n      />\n\n      {showList ? (\n        <div className=\"ap-suggest\" id=\"ap-item-suggest\" role=\"listbox\">\n          {options.map((r, i) => (\n            <button\n              key={r.id}\n              type=\"button\"\n              role=\"option\"\n              aria-selected={i === active}\n              data-active={i === active}\n              className=\"ap-suggest-item\"\n              onMouseEnter={() => setActive(i)}\n              onClick={() => take(r)}\n            >\n              <span style={{ minWidth: 0, flex: 1 }}>\n                <span className=\"ap-suggest-name\">{r.name}</span>\n                <span className=\"ap-suggest-meta\" style={{ display: \"block\" }}>\n                  {r.type === \"service\"\n                    ? \"Service\"\n                    : `${formatQty(r.stock)} ${unitShort(r.unit)} in stock`}\n                  {r.code ? ` · ${r.code}` : \"\"}\n                  {r.taxRate ? ` · ${r.taxRate}% GST` : \"\"}\n                </span>\n              </span>\n              <span className=\"ap-suggest-right\">\n                <span className=\"ap-strong ap-num\">{rupees(r.salePaise)}</span>\n                {r.isOut && r.type !== \"service\" ? (\n                  <span className=\"ap-suggest-meta\" style={{ display: \"block\", color: \"var(--ap-danger)\" }}>\n                    Out of stock\n                  </span>\n                ) : null}\n              </span>\n            </button>\n          ))}\n\n          {loading && !options.length ? (\n            <div className=\"ap-suggest-empty\">\n              <span className=\"ap-spin\" />\n            </div>\n          ) : null}\n\n          {!loading && !options.length ? <div className=\"ap-suggest-empty\">{BILLING.noItems}</div> : null}\n\n          <div className={options.length ? \"ap-suggest-new\" : \"\"}>\n            <button type=\"button\" className=\"ap-suggest-item\" onClick={makeNew}>\n              <span style={{ color: \"var(--ap-brand)\" }}>\n                <IconPlus size={17} />\n              </span>\n              <span>\n                <span className=\"ap-suggest-name\">\n                  {BILLING.createItem} &ldquo;{q.trim()}&rdquo;\n                </span>\n                <span className=\"ap-suggest-meta\" style={{ display: \"block\" }}>\n                  {BILLING.asNewItem}\n                </span>\n              </span>\n            </button>\n          </div>\n        </div>\n      ) : null}\n    </div>\n  );\n}\n","components/app/billing/Lines.js":"\"use client\";\n\n// ===========================================================================\n// THE LINES ON THE BILL\n// ---------------------------------------------------------------------------\n// Everything is editable in place: the rate because a regular customer gets\n// a different price, the discount because it is haggled over at the counter,\n// the GST rate because the person entering the item may have picked the\n// wrong one. Changing it here changes this bill only, never the item.\n//\n// Quantities and rates are held as the strings being typed and only turned\n// into numbers when the total is worked out, so a half-typed \"1.\" is not\n// rewritten under the cursor.\n// ===========================================================================\n\nimport { BILLING, ITEMS } from \"../content\";\nimport { IconClose, IconWarn } from \"../Icons\";\nimport { rupees, formatQty } from \"../../../lib/money\";\nimport { unitShort } from \"../../../lib/units\";\nimport { TAX_RATES } from \"../../../lib/gst-calc\";\nimport { numericOnly } from \"../ui/Field\";\nimport { Empty } from \"../ui/Bits\";\nimport { IconBox } from \"../Icons\";\n\nexport default function Lines({ lines, computed, onChange, onRemove, docType }) {\n  if (!lines.length) {\n    return (\n      <div className=\"ap-panel\">\n        <Empty\n          icon={<IconBox size={34} />}\n          title={BILLING.emptyLines}\n          body={BILLING.emptyLinesHint}\n        />\n      </div>\n    );\n  }\n\n  const takesStock = docType === \"sale\" || docType === \"debit_note\";\n\n  return (\n    <div className=\"ap-tablewrap\">\n      <table className=\"ap-lines\">\n        <thead>\n          <tr>\n            <th>{BILLING.colItem}</th>\n            <th className=\"ap-col-qty ap-right\">{BILLING.colQty}</th>\n            <th className=\"ap-col-rate ap-right\">{BILLING.colRate}</th>\n            <th className=\"ap-col-disc ap-right\">{BILLING.colDisc}</th>\n            <th className=\"ap-col-tax\">{BILLING.colTax}</th>\n            <th className=\"ap-col-amt ap-right\">{BILLING.colAmount}</th>\n            <th className=\"ap-col-x\" />\n          </tr>\n        </thead>\n        <tbody>\n          {lines.map((line, i) => {\n            const c = computed.lines[i] || {};\n            const qty = Number(line.quantity) || 0;\n\n            // Only a warning, never a block. A shop sells the last bag before\n            // the delivery arrives all the time, and the stock count is\n            // frequently behind reality. Stopping the sale would be wrong.\n            const short =\n              takesStock &&\n              line.type !== \"service\" &&\n              line.stock != null &&\n              qty > Number(line.stock);\n\n            return (\n              <tr key={line.key}>\n                <td>\n                  <div className=\"ap-line-name\">{line.name}</div>\n                  <div className=\"ap-line-sub\">\n                    {line.hsn ? `HSN ${line.hsn} · ` : \"\"}\n                    {line.type === \"service\"\n                      ? ITEMS.service\n                      : `${formatQty(line.stock ?? 0)} ${unitShort(line.unit)} in stock`}\n                  </div>\n                  {short ? (\n                    <div\n                      className=\"ap-line-sub\"\n                      style={{ color: \"var(--ap-warn)\", display: \"flex\", gap: 5, alignItems: \"center\" }}\n                    >\n                      <IconWarn size={13} />\n                      {BILLING.stockWarn\n                        .replace(\"{qty}\", formatQty(line.stock))\n                        .replace(\"{unit}\", unitShort(line.unit))\n                        .replace(\"{name}\", line.name)}\n                    </div>\n                  ) : null}\n                </td>\n\n                <td>\n                  <input\n                    className=\"ap-input\"\n                    value={line.quantity}\n                    inputMode=\"decimal\"\n                    onChange={(e) => onChange(i, { quantity: numericOnly(e.target.value) })}\n                    aria-label={`Quantity of ${line.name}`}\n                  />\n                </td>\n\n                <td>\n                  <input\n                    className=\"ap-input\"\n                    value={line.rate}\n                    inputMode=\"decimal\"\n                    onChange={(e) => onChange(i, { rate: numericOnly(e.target.value) })}\n                    aria-label={`Rate of ${line.name}`}\n                  />\n                </td>\n\n                <td>\n                  <input\n                    className=\"ap-input\"\n                    value={line.discountPercent}\n                    inputMode=\"decimal\"\n                    placeholder=\"0\"\n                    onChange={(e) => onChange(i, { discountPercent: numericOnly(e.target.value) })}\n                    aria-label={`Discount on ${line.name}`}\n                  />\n                </td>\n\n                <td>\n                  <select\n                    className=\"ap-select\"\n                    value={String(line.taxRate)}\n                    onChange={(e) => onChange(i, { taxRate: e.target.value })}\n                    aria-label={`GST rate on ${line.name}`}\n                  >\n                    {TAX_RATES.map((t) => (\n                      <option key={t.value} value={String(t.value)}>\n                        {t.value}%\n                      </option>\n                    ))}\n                  </select>\n                </td>\n\n                <td className=\"ap-right\">\n                  <span className=\"ap-strong ap-num\">{rupees(c.total || 0)}</span>\n                  {c.tax ? (\n                    <div className=\"ap-line-sub ap-num\">\n                      {rupees(c.taxable || 0)} + {rupees(c.tax)}\n                    </div>\n                  ) : null}\n                </td>\n\n                <td>\n                  <button\n                    type=\"button\"\n                    className=\"ap-line-x\"\n                    onClick={() => onRemove(i)}\n                    aria-label={`Remove ${line.name}`}\n                  >\n                    <IconClose size={16} />\n                  </button>\n                </td>\n              </tr>\n            );\n          })}\n        </tbody>\n      </table>\n    </div>\n  );\n}\n","components/app/billing/PartyPicker.js":"\"use client\";\n\n// ===========================================================================\n// THE CUSTOMER BOX\n// ---------------------------------------------------------------------------\n// Searches by name or phone, because at a counter the phone number is often\n// the only thing anybody remembers. Leaving it empty is a real answer - a\n// cash sale to somebody passing by does not need a name on file, and\n// forcing one is how an app ends up with four hundred customers called\n// \"customer\".\n//\n// Once picked, the box shows what they owe. That is the number you want in\n// front of you before you hand over more goods on credit.\n// ===========================================================================\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { BILLING, PARTIES } from \"../content\";\nimport { IconSearch, IconPlus, IconClose, IconUsers } from \"../Icons\";\nimport { rupees } from \"../../../lib/money\";\nimport { stateName } from \"../../../lib/gst-states\";\nimport { listParties } from \"../data\";\n\nexport default function PartyPicker({ value, onPick, onClear, onCreate, inputRef, forSupplier }) {\n  const [q, setQ] = useState(\"\");\n  const [rows, setRows] = useState([]);\n  const [open, setOpen] = useState(false);\n  const [active, setActive] = useState(0);\n  const [loading, setLoading] = useState(false);\n  const box = useRef(null);\n  const own = useRef(null);\n  const input = inputRef || own;\n  const seq = useRef(0);\n\n  useEffect(() => {\n    const term = q.trim();\n    if (!term) {\n      setRows([]);\n      return undefined;\n    }\n    const mine = ++seq.current;\n    setLoading(true);\n    const timer = setTimeout(async () => {\n      try {\n        const { rows: found } = await listParties({ search: term, limit: 8 });\n        if (seq.current !== mine) return;\n        setRows(found);\n        setActive(0);\n      } catch {\n        if (seq.current === mine) setRows([]);\n      } finally {\n        if (seq.current === mine) setLoading(false);\n      }\n    }, 180);\n    return () => clearTimeout(timer);\n  }, [q]);\n\n  useEffect(() => {\n    const onDown = (e) => {\n      if (box.current && !box.current.contains(e.target)) setOpen(false);\n    };\n    document.addEventListener(\"mousedown\", onDown);\n    return () => document.removeEventListener(\"mousedown\", onDown);\n  }, []);\n\n  function take(p) {\n    onPick(p);\n    setQ(\"\");\n    setRows([]);\n    setOpen(false);\n  }\n\n  function onKeyDown(e) {\n    if (e.key === \"ArrowDown\") {\n      e.preventDefault();\n      setOpen(true);\n      setActive((i) => Math.min(i + 1, rows.length - 1));\n    } else if (e.key === \"ArrowUp\") {\n      e.preventDefault();\n      setActive((i) => Math.max(i - 1, 0));\n    } else if (e.key === \"Escape\") {\n      setOpen(false);\n    } else if (e.key === \"Enter\") {\n      e.preventDefault();\n      if (rows[active]) take(rows[active]);\n      else if (q.trim() && !loading) onCreate(q.trim());\n    }\n  }\n\n  // Already chosen: show them, with a way to drop back to a walk-in.\n  if (value) {\n    const owes = value.balancePaise > 0;\n    return (\n      <div>\n        <label className=\"ap-label\">{forSupplier ? BILLING.partyLabelSupplier : BILLING.partyLabel}</label>\n        <div\n          className=\"ap-row\"\n          style={{\n            border: \"1px solid var(--ap-line-strong)\",\n            borderRadius: \"var(--ap-radius-sm)\",\n            padding: \"7px 9px 7px 11px\",\n            minHeight: 40,\n            background: \"var(--ap-panel)\",\n            gap: 10,\n          }}\n        >\n          <span style={{ minWidth: 0 }}>\n            <span className=\"ap-strong\" style={{ display: \"block\" }}>\n              {value.name}\n            </span>\n            <span className=\"ap-sub\">\n              {[\n                value.phone || null,\n                value.gstin || null,\n                value.stateCode ? stateName(value.stateCode) : null,\n              ]\n                .filter(Boolean)\n                .join(\" · \") || \"No phone on file\"}\n            </span>\n          </span>\n          <span style={{ marginLeft: \"auto\", textAlign: \"right\", flex: \"0 0 auto\" }}>\n            {value.balancePaise ? (\n              <span className={`ap-pill ${owes ? \"ap-pill-unpaid\" : \"ap-pill-paid\"}`}>\n                {owes\n                  ? `${PARTIES.owesYou} ${rupees(value.owesUs)}`\n                  : `${PARTIES.youOwe} ${rupees(value.weOwe)}`}\n              </span>\n            ) : (\n              <span className=\"ap-sub\">{PARTIES.settled}</span>\n            )}\n          </span>\n          <button type=\"button\" className=\"ap-line-x\" onClick={onClear} aria-label=\"Remove customer\">\n            <IconClose size={16} />\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  const showList = open && Boolean(q.trim());\n\n  return (\n    <div ref={box} style={{ position: \"relative\" }}>\n      <label className=\"ap-label\" htmlFor=\"ap-party-input\">\n        {forSupplier ? BILLING.partyLabelSupplier : BILLING.partyLabel}\n      </label>\n      <div className=\"ap-search\" style={{ minWidth: 0 }}>\n        <span className=\"ap-search-ico\">\n          <IconSearch size={17} />\n        </span>\n        <input\n          id=\"ap-party-input\"\n          ref={input}\n          className=\"ap-input\"\n          placeholder={BILLING.partyPlaceholder}\n          value={q}\n          onChange={(e) => {\n            setQ(e.target.value);\n            setOpen(true);\n          }}\n          onFocus={() => setOpen(true)}\n          onKeyDown={onKeyDown}\n          autoComplete=\"off\"\n          role=\"combobox\"\n          aria-expanded={showList}\n        />\n      </div>\n      {!q ? <p className=\"ap-hint\">{BILLING.walkInNote}</p> : null}\n\n      {showList ? (\n        <div className=\"ap-suggest\" role=\"listbox\">\n          {rows.map((p, i) => (\n            <button\n              key={p.id}\n              type=\"button\"\n              role=\"option\"\n              aria-selected={i === active}\n              data-active={i === active}\n              className=\"ap-suggest-item\"\n              onMouseEnter={() => setActive(i)}\n              onClick={() => take(p)}\n            >\n              <span style={{ color: \"var(--ap-ink-3)\" }}>\n                <IconUsers size={17} />\n              </span>\n              <span style={{ minWidth: 0, flex: 1 }}>\n                <span className=\"ap-suggest-name\">{p.name}</span>\n                <span className=\"ap-suggest-meta\" style={{ display: \"block\" }}>\n                  {p.phone || \"No phone\"}\n                  {p.city ? ` · ${p.city}` : \"\"}\n                </span>\n              </span>\n              {p.balancePaise ? (\n                <span className=\"ap-suggest-right\">\n                  <span\n                    className=\"ap-strong ap-num\"\n                    style={{ color: p.balancePaise > 0 ? \"var(--ap-danger)\" : \"var(--ap-brand-ink)\" }}\n                  >\n                    {rupees(Math.abs(p.balancePaise))}\n                  </span>\n                  <span className=\"ap-suggest-meta\" style={{ display: \"block\" }}>\n                    {p.balancePaise > 0 ? PARTIES.owesYou : PARTIES.youOwe}\n                  </span>\n                </span>\n              ) : null}\n            </button>\n          ))}\n\n          {loading && !rows.length ? (\n            <div className=\"ap-suggest-empty\">\n              <span className=\"ap-spin\" />\n            </div>\n          ) : null}\n\n          <div className={rows.length ? \"ap-suggest-new\" : \"\"}>\n            <button type=\"button\" className=\"ap-suggest-item\" onClick={() => onCreate(q.trim())}>\n              <span style={{ color: \"var(--ap-brand)\" }}>\n                <IconPlus size={17} />\n              </span>\n              <span className=\"ap-suggest-name\">\n                {BILLING.newParty} &ldquo;{q.trim()}&rdquo;\n              </span>\n            </button>\n          </div>\n        </div>\n      ) : null}\n    </div>\n  );\n}\n","components/app/bills/BillDetail.js":"\"use client\";\n\n// ===========================================================================\n// ONE BILL\n// ---------------------------------------------------------------------------\n// Read-only, and that is deliberate. A bill that has gone to a customer and\n// into the GST return is not a draft. If something is wrong with it, the\n// right move is to cancel it and issue another, which is what the law\n// expects and what leaves an explainable trail.\n//\n// So the actions here are: print it, send it, take money against it, or\n// cancel it. Not edit it.\n// ===========================================================================\n\nimport { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { BILLS, COMMON, BILLING } from \"../content\";\nimport { ErrorState, Note, StatusPill, TableSkeleton, statusOf } from \"../ui/Bits\";\nimport Modal from \"../ui/Modal\";\nimport { TextArea } from \"../ui/Field\";\nimport { IconPrint, IconWhatsApp, IconRupee, IconTrash, IconChevron } from \"../Icons\";\nimport { rupees, formatQty, formatDateLong, paiseToWords } from \"../../../lib/money\";\nimport { unitShort, modeLabel } from \"../../../lib/units\";\nimport { stateName } from \"../../../lib/gst-states\";\nimport { getInvoice, getParty, getBusiness, cancelInvoice } from \"../data\";\nimport { useShop } from \"../useShop\";\nimport { useToast } from \"../ui/Toast\";\nimport PaymentForm from \"../payments/PaymentForm\";\nimport InvoicePrint from \"../print/InvoicePrint\";\n\nexport default function BillDetail({ id }) {\n  const shop = useShop();\n  const { toast } = useToast();\n\n  const [invoice, setInvoice] = useState(null);\n  const [party, setParty] = useState(null);\n  const [biz, setBiz] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const [paying, setPaying] = useState(false);\n  const [cancelling, setCancelling] = useState(false);\n  const [printSize, setPrintSize] = useState(\"a4\");\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const inv = await getInvoice(id);\n      setInvoice(inv);\n      const [p, b] = await Promise.all([\n        inv.partyId ? getParty(inv.partyId).catch(() => null) : Promise.resolve(null),\n        shop.businessId ? getBusiness(shop.businessId).catch(() => null) : Promise.resolve(null),\n      ]);\n      setParty(p);\n      setBiz(b);\n    } catch (e) {\n      setError(e);\n    } finally {\n      setLoading(false);\n    }\n  }, [id, shop.businessId]);\n\n  useEffect(() => {\n    load();\n  }, [load]);\n\n  function printAs(size) {\n    setPrintSize(size);\n    // Let the layout swap before the print dialog captures the page.\n    setTimeout(() => window.print(), 120);\n  }\n\n  if (error) return <ErrorState error={error} onRetry={load} />;\n\n  if (loading || !invoice) {\n    return (\n      <div className=\"ap-panel\">\n        <TableSkeleton rows={6} cols={4} />\n      </div>\n    );\n  }\n\n  const a = invoice.amounts;\n  const status = statusOf(invoice);\n  const cancelled = status === \"cancelled\";\n  const interState = invoice.interState || a.igst > 0;\n\n  const waText = [\n    biz?.name || shop.shop?.name || \"\",\n    `Bill ${invoice.number}`,\n    `Amount ${rupees(a.total)}`,\n    a.balance > 0 ? `Pending ${rupees(a.balance)}` : \"Paid. Thank you.\",\n  ]\n    .filter(Boolean)\n    .join(\"\\n\");\n  const waHref = party?.phone\n    ? `https://wa.me/91${String(party.phone).slice(-10)}?text=${encodeURIComponent(waText)}`\n    : null;\n\n  return (\n    <>\n      <div className=\"ap-screenonly\">\n        <div className=\"ap-row\" style={{ marginBottom: 6 }}>\n          <Link href=\"/app/bills\" className=\"ap-btn ap-btn-ghost ap-btn-sm\">\n            <span style={{ transform: \"rotate(180deg)\", display: \"inline-flex\" }}>\n              <IconChevron size={15} />\n            </span>\n            {BILLS.title}\n          </Link>\n        </div>\n\n        <div className=\"ap-row\" style={{ marginBottom: 14, alignItems: \"flex-start\" }}>\n          <div>\n            <h1 className=\"ap-title\" style={{ fontSize: 21, fontFamily: \"var(--ap-mono)\" }}>\n              {invoice.number}\n            </h1>\n            <p className=\"ap-sub\" style={{ margin: \"2px 0 0\" }}>\n              {formatDateLong(invoice.date)}\n              {invoice.partyName ? ` · ${invoice.partyName}` : \" · Walk-in\"}\n            </p>\n          </div>\n          <div className=\"ap-row\" style={{ marginLeft: \"auto\" }}>\n            <StatusPill invoice={invoice} />\n            <button type=\"button\" className=\"ap-btn\" onClick={() => printAs(\"a4\")}>\n              <IconPrint size={16} /> {BILLS.detail.print}\n            </button>\n            <button type=\"button\" className=\"ap-btn\" onClick={() => printAs(\"thermal\")}>\n              {BILLS.detail.thermal}\n            </button>\n            {waHref ? (\n              <a className=\"ap-btn\" href={waHref} target=\"_blank\" rel=\"noopener noreferrer\">\n                <IconWhatsApp size={16} /> {BILLS.detail.share}\n              </a>\n            ) : null}\n            {!cancelled && a.balance > 0 ? (\n              <button type=\"button\" className=\"ap-btn ap-btn-primary\" onClick={() => setPaying(true)}>\n                <IconRupee size={16} /> {BILLS.detail.collect}\n              </button>\n            ) : null}\n            {!cancelled ? (\n              <button type=\"button\" className=\"ap-btn ap-btn-danger\" onClick={() => setCancelling(true)}>\n                <IconTrash size={16} /> {BILLS.detail.cancelBill}\n              </button>\n            ) : null}\n          </div>\n        </div>\n\n        {cancelled ? (\n          <div style={{ marginBottom: 14 }}>\n            <Note kind=\"bad\">{BILLS.detail.cancelled}</Note>\n          </div>\n        ) : null}\n\n        <div className=\"ap-panel\" style={{ marginBottom: 16 }}>\n          <div className=\"ap-panel-head\">\n            <h2>{BILLS.detail.lines}</h2>\n            <span className=\"ap-sub ap-spacer\">\n              {interState ? BILLING.igstNote : BILLING.gstNote}\n            </span>\n          </div>\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <thead>\n                <tr>\n                  <th>Item</th>\n                  <th className=\"ap-right\">Qty</th>\n                  <th className=\"ap-right\">Rate</th>\n                  <th className=\"ap-right\">Taxable</th>\n                  <th className=\"ap-right\">GST</th>\n                  <th className=\"ap-right\">Amount</th>\n                </tr>\n              </thead>\n              <tbody>\n                {invoice.lines.map((l, i) => (\n                  <tr key={l.id || i}>\n                    <td>\n                      <span className=\"ap-strong\">{l.name}</span>\n                      {l.hsn ? <div className=\"ap-sub\">HSN {l.hsn}</div> : null}\n                    </td>\n                    <td className=\"ap-right ap-num\">\n                      {formatQty(l.quantity)} {unitShort(l.unit)}\n                    </td>\n                    <td className=\"ap-right ap-num\">{rupees(l.ratePaise)}</td>\n                    <td className=\"ap-right ap-num\">{rupees(l.taxablePaise)}</td>\n                    <td className=\"ap-right ap-num\">\n                      {rupees(l.cgstPaise + l.sgstPaise + l.igstPaise)}\n                      <span className=\"ap-sub\"> ({l.taxRate}%)</span>\n                    </td>\n                    <td className=\"ap-right ap-num ap-strong\">{rupees(l.totalPaise)}</td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <div className=\"ap-grid2\" style={{ gap: 16, alignItems: \"start\" }}>\n          <div className=\"ap-panel\">\n            <div className=\"ap-panel-head\">\n              <h2>{BILLS.detail.paymentsOn}</h2>\n            </div>\n            {invoice.payments && invoice.payments.length ? (\n              <div className=\"ap-tablewrap\">\n                <table className=\"ap-table\">\n                  <tbody>\n                    {invoice.payments.map((p) => (\n                      <tr key={p.id}>\n                        <td className=\"ap-sub\">{formatDateLong(p.date)}</td>\n                        <td>{modeLabel(p.mode)}</td>\n                        <td className=\"ap-right ap-num ap-strong\">{rupees(p.amountPaise)}</td>\n                      </tr>\n                    ))}\n                  </tbody>\n                </table>\n              </div>\n            ) : (\n              <div className=\"ap-panel-body ap-sub\">\n                {a.paid > 0\n                  ? `${rupees(a.paid)} received. The individual payments are on the customer's page.`\n                  : BILLS.detail.noPayments}\n              </div>\n            )}\n\n            {party ? (\n              <div className=\"ap-panel-foot ap-sub\">\n                <Link href={`/app/parties/${party.id}`}>{party.name}</Link>\n                {party.gstin ? ` · ${party.gstin}` : \"\"}\n                {party.stateCode ? ` · ${stateName(party.stateCode)}` : \"\"}\n              </div>\n            ) : null}\n          </div>\n\n          <div className=\"ap-panel\">\n            <div className=\"ap-panel-head\">\n              <h2>{BILLS.detail.totalsTitle}</h2>\n            </div>\n            <div className=\"ap-panel-body ap-tot\">\n              <div className=\"ap-tot-row\">\n                <span>Taxable value</span>\n                <span>{rupees(a.taxable)}</span>\n              </div>\n              {a.discount ? (\n                <div className=\"ap-tot-row\">\n                  <span>Discount</span>\n                  <span>- {rupees(a.discount)}</span>\n                </div>\n              ) : null}\n              {interState ? (\n                <div className=\"ap-tot-row\">\n                  <span>IGST</span>\n                  <span>{rupees(a.igst)}</span>\n                </div>\n              ) : (\n                <>\n                  <div className=\"ap-tot-row\">\n                    <span>CGST</span>\n                    <span>{rupees(a.cgst)}</span>\n                  </div>\n                  <div className=\"ap-tot-row\">\n                    <span>SGST</span>\n                    <span>{rupees(a.sgst)}</span>\n                  </div>\n                </>\n              )}\n              {a.roundOff ? (\n                <div className=\"ap-tot-row\">\n                  <span>Round off</span>\n                  <span>{rupees(a.roundOff)}</span>\n                </div>\n              ) : null}\n              <div className=\"ap-tot-grand\">\n                <span>Total</span>\n                <span className=\"ap-tot-amt\">{rupees(a.total)}</span>\n              </div>\n              <div className=\"ap-tot-words\">{paiseToWords(a.total)}</div>\n\n              {a.paid ? (\n                <div className=\"ap-tot-row\" style={{ marginTop: 8 }}>\n                  <span>Paid</span>\n                  <span>{rupees(a.paid)}</span>\n                </div>\n              ) : null}\n              {a.balance > 0 && !cancelled ? (\n                <div className=\"ap-tot-row\" style={{ fontWeight: 650, color: \"var(--ap-danger)\" }}>\n                  <span>Pending</span>\n                  <span>{rupees(a.balance)}</span>\n                </div>\n              ) : null}\n            </div>\n          </div>\n        </div>\n\n        {invoice.notes ? (\n          <p className=\"ap-hint\" style={{ marginTop: 12 }}>\n            Note on the bill: {invoice.notes}\n          </p>\n        ) : null}\n      </div>\n\n      <InvoicePrint\n        invoice={invoice}\n        shop={biz || shop.shop}\n        party={party}\n        size={printSize}\n        copyLabel={printSize === \"a4\" ? \"Customer copy\" : undefined}\n      />\n\n      {paying ? (\n        <PaymentForm\n          party={party}\n          invoice={invoice}\n          direction={invoice.docType === \"purchase\" ? \"out\" : \"in\"}\n          onClose={() => setPaying(false)}\n          onSaved={() => {\n            setPaying(false);\n            load();\n          }}\n        />\n      ) : null}\n\n      {cancelling ? (\n        <CancelBill\n          invoice={invoice}\n          onClose={() => setCancelling(false)}\n          onDone={() => {\n            setCancelling(false);\n            toast(BILLS.detail.cancelDone);\n            load();\n          }}\n        />\n      ) : null}\n    </>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// cancelling\n// ---------------------------------------------------------------------------\nfunction CancelBill({ invoice, onClose, onDone }) {\n  const [reason, setReason] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState(null);\n\n  const hasMoney = invoice.amounts.paid > 0;\n\n  async function go() {\n    setBusy(true);\n    setErr(null);\n    try {\n      await cancelInvoice(invoice.id, reason.trim() || undefined);\n      onDone();\n    } catch (e) {\n      setErr(\n        e.code === \"unsupported\"\n          ? \"This server does not have a cancel route yet.\"\n          : e.isOffline\n          ? COMMON.offlineBody\n          : e.message || COMMON.genericError\n      );\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <Modal\n      title={BILLS.detail.cancelTitle}\n      onClose={onClose}\n      footer={\n        <>\n          <button type=\"button\" className=\"ap-btn\" onClick={onClose} disabled={busy}>\n            Keep it\n          </button>\n          <button\n            type=\"button\"\n            className=\"ap-btn ap-btn-danger\"\n            onClick={go}\n            disabled={busy || hasMoney}\n          >\n            {busy ? COMMON.saving : BILLS.detail.cancelConfirm}\n          </button>\n        </>\n      }\n    >\n      <div className=\"ap-stack\">\n        {err ? <Note kind=\"bad\">{err}</Note> : null}\n        {hasMoney ? <Note kind=\"warn\">{BILLS.detail.cancelPaid}</Note> : null}\n        <p style={{ margin: 0 }}>{BILLS.detail.cancelBody}</p>\n        <TextArea\n          label={BILLS.detail.cancelReason}\n          value={reason}\n          onChange={(e) => setReason(e.target.value)}\n          rows={2}\n          placeholder=\"Wrong customer, wrong item, entered twice\"\n          disabled={hasMoney}\n        />\n      </div>\n    </Modal>\n  );\n}\n","components/app/bills/BillsPage.js":"\"use client\";\n\n// ===========================================================================\n// ALL THE BILLS\n// ---------------------------------------------------------------------------\n// Filters that match the questions actually asked: what went out today, what\n// is still unpaid, how the month is going. The totals line at the top is of\n// the filtered set, not of everything, because otherwise it answers a\n// question nobody asked.\n// ===========================================================================\n\nimport { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { BILLS, BILLING } from \"../content\";\nimport { Empty, ErrorState, PageHead, StatusPill, TableSkeleton } from \"../ui/Bits\";\nimport { IconPlus, IconSearch, IconBill } from \"../Icons\";\nimport { rupees, rupeesShort, formatDate, today, daysAgo, relativeDay } from \"../../../lib/money\";\nimport { listInvoices } from \"../data\";\n\nconst DOC_LABEL = {};\nfor (const d of BILLING.docTypes) DOC_LABEL[d.value] = d.label;\n\nexport default function BillsPage() {\n  const [q, setQ] = useState(\"\");\n  const [filter, setFilter] = useState(\"all\");\n  const [docType, setDocType] = useState(\"sale\");\n  const [rows, setRows] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const seq = useRef(0);\n\n  const load = useCallback(\n    async (term, type) => {\n      const mine = ++seq.current;\n      setLoading(true);\n      setError(null);\n      try {\n        const { rows: found } = await listInvoices({\n          docType: type || undefined,\n          search: term || undefined,\n          limit: 200,\n        });\n        if (seq.current !== mine) return;\n        setRows(found);\n      } catch (e) {\n        if (seq.current === mine) setError(e);\n      } finally {\n        if (seq.current === mine) setLoading(false);\n      }\n    },\n    []\n  );\n\n  useEffect(() => {\n    const timer = setTimeout(() => load(q.trim(), docType), q ? 220 : 0);\n    return () => clearTimeout(timer);\n  }, [q, docType, load]);\n\n  const shown = useMemo(() => {\n    const t = today();\n    const week = daysAgo(6);\n    const month = `${t.slice(0, 7)}-01`;\n    let out = rows;\n    if (filter === \"unpaid\") out = out.filter((r) => r.status !== \"cancelled\" && r.amounts.balance > 0);\n    if (filter === \"today\") out = out.filter((r) => r.date === t);\n    if (filter === \"week\") out = out.filter((r) => r.date >= week);\n    if (filter === \"month\") out = out.filter((r) => r.date >= month);\n    return out;\n  }, [rows, filter]);\n\n  const totals = useMemo(() => {\n    const live = shown.filter((r) => r.status !== \"cancelled\");\n    return {\n      count: live.length,\n      total: live.reduce((a, r) => a + r.amounts.total, 0),\n      due: live.reduce((a, r) => a + r.amounts.balance, 0),\n    };\n  }, [shown]);\n\n  return (\n    <>\n      <PageHead title={BILLS.title}>\n        <Link href=\"/app/billing\" className=\"ap-btn ap-btn-primary\">\n          <IconPlus size={17} /> {BILLS.add}\n        </Link>\n      </PageHead>\n\n      {!loading && shown.length ? (\n        <div className=\"ap-tiles\" style={{ marginBottom: 14, gridTemplateColumns: \"repeat(3, minmax(0,1fr))\" }}>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">Bills shown</div>\n            <div className=\"ap-tile-value\">{totals.count}</div>\n          </div>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">Their value</div>\n            <div className=\"ap-tile-value\">{rupeesShort(totals.total)}</div>\n          </div>\n          <div className=\"ap-tile ap-tile-bad\">\n            <div className=\"ap-tile-label\">Still due</div>\n            <div className=\"ap-tile-value\">{rupeesShort(totals.due)}</div>\n          </div>\n        </div>\n      ) : null}\n\n      <div className=\"ap-panel\">\n        <div className=\"ap-panel-head\" style={{ flexWrap: \"wrap\" }}>\n          <div className=\"ap-search\">\n            <span className=\"ap-search-ico\">\n              <IconSearch size={17} />\n            </span>\n            <input\n              className=\"ap-input\"\n              placeholder={BILLS.searchPlaceholder}\n              value={q}\n              onChange={(e) => setQ(e.target.value)}\n              aria-label={BILLS.searchPlaceholder}\n            />\n          </div>\n\n          <select\n            className=\"ap-select\"\n            style={{ width: \"auto\", minWidth: 140 }}\n            value={docType}\n            onChange={(e) => setDocType(e.target.value)}\n            aria-label=\"Bill type\"\n          >\n            {BILLING.docTypes.map((d) => (\n              <option key={d.value} value={d.value}>\n                {d.label}\n              </option>\n            ))}\n          </select>\n\n          <div className=\"ap-seg ap-spacer\">\n            {[\n              [\"all\", BILLS.filterAll],\n              [\"unpaid\", BILLS.filterUnpaid],\n              [\"today\", BILLS.filterToday],\n              [\"week\", BILLS.filterWeek],\n              [\"month\", BILLS.filterMonth],\n            ].map(([value, label]) => (\n              <button key={value} type=\"button\" aria-pressed={filter === value} onClick={() => setFilter(value)}>\n                {label}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        {error ? (\n          <div className=\"ap-panel-body\">\n            <ErrorState error={error} onRetry={() => load(q.trim(), docType)} />\n          </div>\n        ) : loading ? (\n          <TableSkeleton rows={7} cols={5} />\n        ) : shown.length ? (\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <thead>\n                <tr>\n                  <th>{BILLS.colNumber}</th>\n                  <th>{BILLS.colDate}</th>\n                  <th>{BILLS.colParty}</th>\n                  <th className=\"ap-right\">{BILLS.colTotal}</th>\n                  <th className=\"ap-right\">{BILLS.colBalance}</th>\n                  <th className=\"ap-right\">{BILLS.colStatus}</th>\n                </tr>\n              </thead>\n              <tbody>\n                {shown.map((b) => (\n                  <tr key={b.id}>\n                    <td>\n                      <Link href={`/app/bills/${b.id}`}>{b.number}</Link>\n                      {b.docType !== docType ? <div className=\"ap-sub\">{DOC_LABEL[b.docType]}</div> : null}\n                    </td>\n                    <td className=\"ap-sub\">{relativeDay(b.date)}</td>\n                    <td>{b.partyName || <span className=\"ap-sub\">Walk-in</span>}</td>\n                    <td className=\"ap-right ap-num ap-strong\">{rupees(b.amounts.total)}</td>\n                    <td className=\"ap-right ap-num\">\n                      {b.status !== \"cancelled\" && b.amounts.balance > 0 ? (\n                        <span style={{ color: \"var(--ap-danger)\" }}>{rupees(b.amounts.balance)}</span>\n                      ) : (\n                        <span className=\"ap-sub\">{\"–\"}</span>\n                      )}\n                    </td>\n                    <td className=\"ap-right\">\n                      <StatusPill invoice={b} />\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <Empty\n            icon={<IconBill size={34} />}\n            title={q || filter !== \"all\" ? BILLS.emptyFilterTitle : BILLS.emptyTitle}\n            body={q || filter !== \"all\" ? BILLS.emptyFilterBody : BILLS.emptyBody}\n            action={\n              <Link href=\"/app/billing\" className=\"ap-btn ap-btn-primary\">\n                <IconPlus size={17} /> {BILLS.add}\n              </Link>\n            }\n          />\n        )}\n      </div>\n\n      <p className=\"ap-hint\" style={{ marginTop: 10 }}>\n        Dates shown as {formatDate(today())} format. Cancelled bills stay in the list on purpose: GST needs\n        the numbering unbroken, so nothing is ever deleted.\n      </p>\n    </>\n  );\n}\n","components/app/content.js":"// ===========================================================================\n// EVERY WORD IN THE APP\n// ---------------------------------------------------------------------------\n// Kept in one file so the wording can be fixed without going hunting through\n// components, and so it can be handed to a translator later in one piece.\n//\n// The tone to keep: short, plain, and about the shop rather than about the\n// software. \"No bills yet\" not \"No records found\". \"Ramesh owes you 1,512\"\n// not \"Outstanding receivable balance\".\n// ===========================================================================\n\nexport const NAV = [\n  { href: \"/app\", label: \"Home\", icon: \"home\", hotkey: \"g h\" },\n  { href: \"/app/billing\", label: \"New bill\", icon: \"plus\", hotkey: \"g b\", accent: true },\n  { href: \"/app/bills\", label: \"Bills\", icon: \"bill\", hotkey: \"g l\" },\n  { href: \"/app/items\", label: \"Items\", icon: \"box\", hotkey: \"g i\" },\n  { href: \"/app/parties\", label: \"Customers\", icon: \"users\", hotkey: \"g p\" },\n];\n\nexport const COMMON = {\n  save: \"Save\",\n  saving: \"Saving…\",\n  cancel: \"Cancel\",\n  close: \"Close\",\n  delete: \"Delete\",\n  edit: \"Edit\",\n  search: \"Search\",\n  loading: \"Loading…\",\n  retry: \"Try again\",\n  back: \"Back\",\n  required: \"This is needed\",\n  offlineTitle: \"Cannot reach the server\",\n  offlineBody:\n    \"The app is running but the server is not answering. Nothing has been lost — check that the backend is running, then try again.\",\n  authTitle: \"Please sign in again\",\n  authBody: \"Your session has ended. Sign in and you will come straight back here.\",\n  noShopTitle: \"Set up your shop first\",\n  noShopBody: \"A bill needs a shop name and a state before it can be made. It takes a minute.\",\n  noShopCta: \"Set up my shop\",\n  genericError: \"Something went wrong. Please try again.\",\n};\n\nexport const HOME = {\n  title: \"Home\",\n  greetMorning: \"Good morning\",\n  greetAfternoon: \"Good afternoon\",\n  greetEvening: \"Good evening\",\n  tiles: {\n    sales: \"Sales today\",\n    salesNote: \"bills today\",\n    received: \"Money received today\",\n    receivedNote: \"cash, UPI and the rest\",\n    toCollect: \"To collect\",\n    toCollectNote: \"customers who still owe you\",\n    toPay: \"To pay\",\n    toPayNote: \"what you owe suppliers\",\n  },\n  quick: \"Quick actions\",\n  newBill: \"New bill\",\n  addItem: \"Add an item\",\n  addParty: \"Add a customer\",\n  collect: \"Take a payment\",\n  recent: \"Recent bills\",\n  recentEmpty: \"No bills yet. The first one takes about thirty seconds.\",\n  seeAll: \"See all\",\n  lowStock: \"Running low\",\n  lowStockEmpty: \"Nothing is running low.\",\n  lowStockNote: \"Items at or below the alert level you set.\",\n  owes: \"Who owes you\",\n  owesEmpty: \"Nobody owes you anything. Nice.\",\n  owesNote: \"Oldest first — chase these.\",\n  weekTitle: \"Last 7 days\",\n  weekNote: \"Sales, by day.\",\n  setupTitle: \"Finish setting up\",\n  setupNote: \"A few minutes now and every bill after this is faster.\",\n  stepItems: \"Add the things you sell\",\n  stepItemsNote: \"Even five items makes billing quick.\",\n  stepGst: \"Add your GSTIN\",\n  stepGstNote: \"Needed before you can give a customer a tax invoice.\",\n  stepBill: \"Make your first bill\",\n  stepBillNote: \"Try it with a walk-in customer.\",\n};\n\nexport const BILLING = {\n  title: \"New bill\",\n  docTypes: [\n    { value: \"sale\", label: \"Sale\" },\n    { value: \"purchase\", label: \"Purchase\" },\n    { value: \"estimate\", label: \"Estimate\" },\n    { value: \"credit_note\", label: \"Sales return\" },\n    { value: \"debit_note\", label: \"Purchase return\" },\n  ],\n  docHelp: {\n    sale: \"A normal sale. Stock goes down, the customer owes you.\",\n    purchase: \"Goods bought in. Stock goes up, you owe the supplier.\",\n    estimate: \"A quote. Nothing moves until you turn it into a bill.\",\n    credit_note: \"A customer returned something. Stock comes back, you owe them.\",\n    debit_note: \"You returned something to a supplier. Stock goes out.\",\n  },\n  partyLabel: \"Customer\",\n  partyLabelSupplier: \"Supplier\",\n  partyPlaceholder: \"Name or phone number — leave blank for a walk-in\",\n  walkIn: \"Walk-in customer\",\n  walkInNote: \"No name kept. Cash sale.\",\n  newParty: \"Add\",\n  dateLabel: \"Date\",\n  addItemPlaceholder: \"Type an item name or code, then press Enter\",\n  addItemHint: \"Nothing yet? Type the name and add it as you go.\",\n  createItem: \"Add\",\n  asNewItem: \"as a new item\",\n  noItems: \"No item matches that.\",\n  colItem: \"Item\",\n  colQty: \"Qty\",\n  colRate: \"Rate\",\n  colDisc: \"Disc %\",\n  colTax: \"GST\",\n  colAmount: \"Amount\",\n  emptyLines: \"No items on this bill yet.\",\n  emptyLinesHint: \"Use the box above. The total works itself out.\",\n  inclusive: \"Rates include GST\",\n  inclusiveHint: \"Tick this if your prices are MRP — the tax is taken out of the price rather than added on.\",\n  subtotal: \"Subtotal\",\n  discount: \"Discount\",\n  extraDiscount: \"Bill discount\",\n  taxable: \"Taxable value\",\n  roundOff: \"Round off\",\n  total: \"Total\",\n  gstNote: \"Same state, so the GST is split into CGST and SGST.\",\n  igstNote: \"Different state, so the whole GST is IGST.\",\n  stockWarn: \"Only {qty} {unit} of {name} in stock.\",\n  payTitle: \"Payment\",\n  payFull: \"Full\",\n  payNone: \"Credit\",\n  payAmount: \"Received\",\n  payMode: \"Paid by\",\n  payBalance: \"Still to collect\",\n  payNote: \"Note\",\n  payNotePlaceholder: \"Cheque number, reference, anything useful\",\n  saveAndPrint: \"Save and print\",\n  saveOnly: \"Save\",\n  savingBill: \"Saving…\",\n  savedTitle: \"Bill saved\",\n  savedNext: \"New bill\",\n  savedPrint: \"Print\",\n  savedShare: \"Send on WhatsApp\",\n  savedOpen: \"Open the bill\",\n  shortcuts: \"Shortcuts\",\n  keys: [\n    { keys: \"F2\", what: \"Jump to the item box\" },\n    { keys: \"F4\", what: \"Jump to the customer box\" },\n    { keys: \"Enter\", what: \"Add the item you have highlighted\" },\n    { keys: \"↑ ↓\", what: \"Move through the suggestions\" },\n    { keys: \"Alt + S\", what: \"Save the bill\" },\n    { keys: \"Alt + P\", what: \"Save and print\" },\n    { keys: \"Esc\", what: \"Close whatever is open\" },\n  ],\n  needLines: \"Add at least one item first.\",\n  needPartyCredit: \"A credit sale needs a customer, so you know who owes you.\",\n  overpaid: \"That is more than the bill. Reduce the amount received.\",\n};\n\nexport const ITEMS = {\n  title: \"Items\",\n  add: \"Add an item\",\n  searchPlaceholder: \"Search by name, code or HSN\",\n  filterAll: \"All\",\n  filterLow: \"Running low\",\n  filterServices: \"Services\",\n  colName: \"Item\",\n  colStock: \"In stock\",\n  colSale: \"Sale price\",\n  colPurchase: \"Cost\",\n  colTax: \"GST\",\n  colValue: \"Stock value\",\n  emptyTitle: \"No items yet\",\n  emptyBody: \"Add the things you sell. You can also add them while making a bill.\",\n  emptySearchTitle: \"Nothing matches\",\n  emptySearchBody: \"Try a shorter search, or add it as a new item.\",\n  lowTag: \"Low\",\n  outTag: \"Out of stock\",\n  service: \"Service\",\n  form: {\n    addTitle: \"Add an item\",\n    editTitle: \"Edit item\",\n    name: \"Item name\",\n    namePlaceholder: \"Basmati rice 5 kg\",\n    type: \"Type\",\n    typeGoods: \"Goods\",\n    typeService: \"Service\",\n    typeHint: \"A service has no stock to keep track of.\",\n    code: \"Item code\",\n    codePlaceholder: \"Barcode or your own code\",\n    codeHint: \"Scanning a barcode into the billing box finds the item instantly.\",\n    hsn: \"HSN / SAC\",\n    hsnHint: \"Needed on a tax invoice. Four digits is enough for most shops.\",\n    unit: \"Unit\",\n    salePrice: \"Sale price\",\n    salePriceHint: \"What the customer pays.\",\n    taxIncluded: \"This price includes GST\",\n    purchasePrice: \"Cost price\",\n    purchasePriceHint: \"What you paid. Used to work out profit.\",\n    taxRate: \"GST rate\",\n    openingStock: \"Stock in hand\",\n    openingStockHint: \"How many you have right now.\",\n    lowStockAlert: \"Tell me when stock falls to\",\n    lowStockHint: \"Leave blank for no alert.\",\n    description: \"Note\",\n    saved: \"Item saved\",\n    savedNew: \"{name} added\",\n  },\n  stock: {\n    title: \"Correct the stock\",\n    note: \"Use this when the count on the shelf does not match the app — breakage, a free sample, an old mistake. It is written down so the reason is on the record.\",\n    current: \"App says\",\n    actual: \"Actually in stock\",\n    change: \"Change\",\n    reason: \"Reason\",\n    reasons: [\n      { value: \"correction\", label: \"Count correction\" },\n      { value: \"damage\", label: \"Damaged or broken\" },\n      { value: \"expired\", label: \"Expired\" },\n      { value: \"lost\", label: \"Lost or stolen\" },\n      { value: \"sample\", label: \"Given free\" },\n      { value: \"other\", label: \"Other\" },\n    ],\n    notes: \"Note\",\n    done: \"Stock corrected\",\n  },\n  history: \"Stock movements\",\n  historyEmpty: \"No movements yet.\",\n};\n\nexport const PARTIES = {\n  title: \"Customers\",\n  add: \"Add a customer\",\n  searchPlaceholder: \"Search by name or phone\",\n  filterAll: \"All\",\n  filterCustomers: \"Customers\",\n  filterSuppliers: \"Suppliers\",\n  filterOwing: \"Owe you money\",\n  colName: \"Name\",\n  colPhone: \"Phone\",\n  colBalance: \"Balance\",\n  owesYou: \"owes you\",\n  youOwe: \"you owe\",\n  settled: \"Settled\",\n  emptyTitle: \"No customers yet\",\n  emptyBody: \"Add a customer when you want to keep track of what they owe. Walk-in cash sales do not need one.\",\n  emptySearchTitle: \"Nothing matches\",\n  emptySearchBody: \"Try a shorter search, or add them as a new customer.\",\n  form: {\n    addTitle: \"Add a customer\",\n    editTitle: \"Edit customer\",\n    name: \"Name\",\n    namePlaceholder: \"Ramesh Traders\",\n    type: \"They are a\",\n    typeCustomer: \"Customer\",\n    typeSupplier: \"Supplier\",\n    typeBoth: \"Both\",\n    phone: \"Phone\",\n    phoneHint: \"Used to send the bill on WhatsApp.\",\n    email: \"Email\",\n    gstin: \"GSTIN\",\n    gstinHint: \"15 characters. Needed if they want to claim the tax back.\",\n    gstinBad: \"That does not look like a valid GSTIN.\",\n    stateCode: \"State\",\n    stateHint: \"This decides whether the bill carries CGST + SGST or IGST, so it matters.\",\n    address: \"Address\",\n    city: \"City\",\n    pincode: \"PIN code\",\n    openingBalance: \"Opening balance\",\n    openingBalanceHint: \"What they already owed you before you started using this. Leave at zero if nothing.\",\n    openingOwesYou: \"They owe me\",\n    openingIOwe: \"I owe them\",\n    saved: \"Customer saved\",\n    savedNew: \"{name} added\",\n  },\n  detail: {\n    bills: \"Their bills\",\n    billsEmpty: \"No bills yet.\",\n    payments: \"Payments\",\n    collect: \"Take a payment\",\n    pay: \"Make a payment\",\n    ledger: \"Account\",\n    ledgerEmpty: \"Nothing on the account yet.\",\n    call: \"Call\",\n    whatsapp: \"WhatsApp\",\n    remind: \"Send a reminder\",\n    reminderText:\n      \"Hello {name}, this is a reminder from {shop}. {amount} is pending on your account. Thank you.\",\n  },\n};\n\nexport const BILLS = {\n  title: \"Bills\",\n  add: \"New bill\",\n  searchPlaceholder: \"Search by bill number or customer\",\n  filterAll: \"All\",\n  filterUnpaid: \"Unpaid\",\n  filterToday: \"Today\",\n  filterWeek: \"This week\",\n  filterMonth: \"This month\",\n  colNumber: \"Bill no.\",\n  colDate: \"Date\",\n  colParty: \"Customer\",\n  colTotal: \"Total\",\n  colBalance: \"Due\",\n  colStatus: \"Status\",\n  emptyTitle: \"No bills yet\",\n  emptyBody: \"Your first bill takes about thirty seconds.\",\n  emptyFilterTitle: \"Nothing here\",\n  emptyFilterBody: \"No bill matches that. Try a wider filter.\",\n  statuses: {\n    paid: \"Paid\",\n    partial: \"Part paid\",\n    unpaid: \"Unpaid\",\n    cancelled: \"Cancelled\",\n    draft: \"Draft\",\n  },\n  detail: {\n    print: \"Print\",\n    thermal: \"Receipt\",\n    share: \"WhatsApp\",\n    collect: \"Take payment\",\n    cancelBill: \"Cancel this bill\",\n    cancelled: \"This bill was cancelled.\",\n    cancelTitle: \"Cancel this bill?\",\n    cancelBody:\n      \"The bill stays on the record with a cancelled mark — GST needs the numbering to stay unbroken, so nothing is ever deleted. Stock and the customer's balance go back to what they were.\",\n    cancelReason: \"Why?\",\n    cancelConfirm: \"Yes, cancel it\",\n    cancelDone: \"Bill cancelled\",\n    cancelPaid: \"This bill has money against it. Refund the payment first, then cancel.\",\n    lines: \"Items\",\n    paymentsOn: \"Payments against this bill\",\n    noPayments: \"Nothing received yet.\",\n    totalsTitle: \"Totals\",\n  },\n};\n\nexport const PAYMENT = {\n  title: \"Take a payment\",\n  titleOut: \"Make a payment\",\n  party: \"From\",\n  partyOut: \"To\",\n  amount: \"Amount\",\n  mode: \"Paid by\",\n  date: \"Date\",\n  note: \"Note\",\n  notePlaceholder: \"Cheque number, reference, anything useful\",\n  against: \"Put it against\",\n  oldestFirst: \"Oldest bills first\",\n  oldestFirstHint: \"The usual way — the oldest unpaid bill is cleared first.\",\n  pickBills: \"Choose the bills myself\",\n  outstanding: \"Pending\",\n  willClear: \"Clears\",\n  unallocated: \"On account\",\n  unallocatedHint: \"Not against any one bill. It reduces what they owe overall.\",\n  save: \"Save the payment\",\n  done: \"Payment saved\",\n  nothingDue: \"Nothing is pending for them.\",\n  tooMuch: \"That is more than they owe. It will be kept on account.\",\n};\n\nexport const SHOP = {\n  switch: \"Switch shop\",\n  add: \"Add another shop\",\n  settings: \"Shop settings\",\n  signOut: \"Sign out\",\n  myAccount: \"My account\",\n  website: \"Website\",\n  help: \"Help\",\n};\n","components/app/data.js":"\"use client\";\n\n// ===========================================================================\n// TALKING TO THE BACKEND, IN THE APP'S OWN WORDS\n// ---------------------------------------------------------------------------\n// Two jobs.\n//\n// 1. Normalising. The server answers in camelCase, but a list endpoint may\n//    hand back a bare array or an object with a count for paging, and a\n//    field may arrive as salePrice or salePricePaise depending on which\n//    endpoint built it. Every screen reading those variations itself would\n//    be a slow leak of bugs. They are flattened here, once.\n//\n// 2. Keeping money in paise. Whatever the server sends - rupees as a\n//    number, or paise as a string - comes out of here as integer paise, and\n//    goes back as whatever that endpoint expects.\n//\n// If a shape below turns out not to match the backend, this is the only file\n// that has to change.\n// ===========================================================================\n\n// Through app-client, never straight at lib/api.js. That module belongs to\n// the login and account screens and is left exactly as they expect it.\nimport { api, qs, rowsOf, totalOf, ApiError } from \"../../lib/app-client\";\nimport { toPaise } from \"../../lib/money\";\n\n// ---------------------------------------------------------------------------\n// reading a money field\n// ---------------------------------------------------------------------------\n// A field named *Paise is already paise. Anything else is rupees and has to\n// be multiplied. Getting this backwards would be a hundredfold error on\n// every screen, so it is one function and nothing else does it.\nfunction paiseFrom(row, base) {\n  const paiseKey = `${base}Paise`;\n  if (row[paiseKey] !== undefined && row[paiseKey] !== null) return Math.round(Number(row[paiseKey])) || 0;\n  const snake = `${base.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`)}_paise`;\n  if (row[snake] !== undefined && row[snake] !== null) return Math.round(Number(row[snake])) || 0;\n  if (row[base] !== undefined && row[base] !== null) return toPaise(row[base]);\n  return 0;\n}\n\nfunction num(value, fallback = 0) {\n  const n = Number(value);\n  return Number.isFinite(n) ? n : fallback;\n}\n\n// ---------------------------------------------------------------------------\n// items\n// ---------------------------------------------------------------------------\nexport function normItem(row) {\n  if (!row) return null;\n  const salePaise = paiseFrom(row, \"salePrice\");\n  const costPaise = paiseFrom(row, \"purchasePrice\");\n  const stock = num(row.currentStock ?? row.current_stock, 0);\n  const low = row.lowStockAlert ?? row.low_stock_alert ?? null;\n\n  return {\n    id: row.id,\n    name: row.name || \"\",\n    type: row.type || \"goods\",\n    code: row.code || row.itemCode || \"\",\n    hsn: row.hsn || row.hsnCode || \"\",\n    unit: row.unit || \"PCS\",\n    taxRate: num(row.taxRate ?? row.tax_rate, 0),\n    taxIncluded: Boolean(row.taxIncluded ?? row.tax_included),\n    salePaise,\n    costPaise,\n    stock,\n    lowStockAlert: low === null || low === \"\" ? null : num(low, 0),\n    description: row.description || \"\",\n    isLow:\n      row.type !== \"service\" && low !== null && low !== \"\" && stock <= num(low, 0),\n    isOut: row.type !== \"service\" && stock <= 0,\n    stockValuePaise: row.type === \"service\" ? 0 : Math.round(stock * (costPaise || salePaise)),\n    raw: row,\n  };\n}\n\nexport async function listItems(params = {}) {\n  const res = await api.get(`/api/items${qs(params)}`);\n  return { rows: rowsOf(res).map(normItem), total: totalOf(res) };\n}\n\nexport async function getItem(id) {\n  return normItem(await api.get(`/api/items/${id}`));\n}\n\n// The server expects rupees on the way in - that is what its validator\n// accepts - so this is the one place that converts back.\nexport async function createItem(form) {\n  const body = {\n    name: form.name.trim(),\n    type: form.type || \"goods\",\n    unit: form.unit || \"PCS\",\n    salePrice: Number(form.salePrice) || 0,\n    taxRate: Number(form.taxRate) || 0,\n  };\n  if (form.code) body.code = form.code.trim();\n  if (form.hsn) body.hsn = String(form.hsn).trim();\n  if (form.purchasePrice !== \"\" && form.purchasePrice != null) body.purchasePrice = Number(form.purchasePrice) || 0;\n  if (form.taxIncluded) body.taxIncluded = true;\n  if (form.type !== \"service\" && form.openingStock !== \"\" && form.openingStock != null) {\n    body.openingStock = Number(form.openingStock) || 0;\n  }\n  if (form.lowStockAlert !== \"\" && form.lowStockAlert != null) {\n    body.lowStockAlert = Number(form.lowStockAlert) || 0;\n  }\n  if (form.description) body.description = form.description.trim();\n  return normItem(await api.post(\"/api/items\", body));\n}\n\nexport async function updateItem(id, form) {\n  const body = {\n    name: form.name.trim(),\n    type: form.type || \"goods\",\n    unit: form.unit || \"PCS\",\n    salePrice: Number(form.salePrice) || 0,\n    taxRate: Number(form.taxRate) || 0,\n    code: form.code ? form.code.trim() : null,\n    hsn: form.hsn ? String(form.hsn).trim() : null,\n    taxIncluded: Boolean(form.taxIncluded),\n    description: form.description || null,\n  };\n  if (form.purchasePrice !== \"\" && form.purchasePrice != null) body.purchasePrice = Number(form.purchasePrice) || 0;\n  body.lowStockAlert =\n    form.lowStockAlert === \"\" || form.lowStockAlert == null ? null : Number(form.lowStockAlert) || 0;\n  return normItem(await api.patch(`/api/items/${id}`, body));\n}\n\n// ---------------------------------------------------------------------------\n// parties\n// ---------------------------------------------------------------------------\n// A positive balance means they owe the shop. Negative means the shop owes\n// them. Every screen must agree on that sign or the dashboard will be\n// nonsense, so it is settled here.\nexport function normParty(row) {\n  if (!row) return null;\n  const balancePaise = paiseFrom(row, \"balance\");\n  return {\n    id: row.id,\n    name: row.name || \"\",\n    type: row.type || \"customer\",\n    phone: row.phone || \"\",\n    dialCode: row.dialCode || \"+91\",\n    email: row.email || \"\",\n    gstin: row.gstin || \"\",\n    stateCode: row.stateCode || row.state_code || \"\",\n    stateName: row.stateName || row.state_name || \"\",\n    address: row.address || \"\",\n    city: row.city || \"\",\n    pincode: row.pincode || \"\",\n    balancePaise,\n    owesUs: balancePaise > 0 ? balancePaise : 0,\n    weOwe: balancePaise < 0 ? -balancePaise : 0,\n    lastBillDate: row.lastInvoiceDate || row.last_invoice_date || null,\n    raw: row,\n  };\n}\n\nexport async function listParties(params = {}) {\n  const res = await api.get(`/api/parties${qs(params)}`);\n  return { rows: rowsOf(res).map(normParty), total: totalOf(res) };\n}\n\nexport async function getParty(id) {\n  return normParty(await api.get(`/api/parties/${id}`));\n}\n\nfunction partyBody(form) {\n  const body = { name: form.name.trim(), type: form.type || \"customer\" };\n  if (form.phone) body.phone = String(form.phone).replace(/\\D+/g, \"\");\n  if (form.email) body.email = form.email.trim();\n  if (form.gstin) body.gstin = form.gstin.trim().toUpperCase();\n  if (form.stateCode) body.stateCode = form.stateCode;\n  if (form.address) body.address = form.address.trim();\n  if (form.city) body.city = form.city.trim();\n  if (form.pincode) body.pincode = String(form.pincode).replace(/\\D+/g, \"\");\n  return body;\n}\n\nexport async function createParty(form) {\n  const body = partyBody(form);\n  const opening = Number(form.openingBalance) || 0;\n  if (opening) body.openingBalance = form.openingDirection === \"owe\" ? -opening : opening;\n  return normParty(await api.post(\"/api/parties\", body));\n}\n\nexport async function updateParty(id, form) {\n  return normParty(await api.patch(`/api/parties/${id}`, partyBody(form)));\n}\n\n// ---------------------------------------------------------------------------\n// invoices\n// ---------------------------------------------------------------------------\nexport function normInvoice(row) {\n  if (!row) return null;\n  const a = row.amounts || {};\n\n  // The amounts block comes back in rupees - 1512 means one thousand five\n  // hundred and twelve rupees, not fifteen rupees twelve paise. Anything\n  // named *Paise is already paise and is taken as it is.\n  const money = (key) => {\n    if (a[`${key}Paise`] !== undefined && a[`${key}Paise`] !== null) {\n      return Math.round(Number(a[`${key}Paise`])) || 0;\n    }\n    if (a[key] !== undefined && a[key] !== null) return toPaise(a[key]);\n    return paiseFrom(row, key);\n  };\n\n  const total = money(\"total\");\n  const balance = a.balance !== undefined || a.balancePaise !== undefined\n    ? money(\"balance\")\n    : total - money(\"paid\");\n\n  return {\n    id: row.id,\n    number: row.number || row.invoiceNumber || \"\",\n    docType: row.docType || row.doc_type || \"sale\",\n    date: String(row.date || row.invoiceDate || row.createdAt || \"\").slice(0, 10),\n    dueDate: row.dueDate ? String(row.dueDate).slice(0, 10) : null,\n    partyId: row.partyId ?? row.party_id ?? row.party?.id ?? null,\n    partyName: row.partyName || row.party?.name || \"\",\n    partyPhone: row.partyPhone || row.party?.phone || \"\",\n    partyGstin: row.partyGstin || row.party?.gstin || \"\",\n    partyStateCode: row.placeOfSupply || row.party?.stateCode || \"\",\n    status: row.status || \"\",\n    cancelledAt: row.cancelledAt || row.cancelled_at || null,\n    notes: row.notes || \"\",\n    interState: Boolean(row.interState ?? row.isInterState ?? (a.igst && toPaise(a.igst) > 0)),\n    amounts: {\n      taxable: money(\"taxable\"),\n      discount: money(\"discount\"),\n      cgst: money(\"cgst\"),\n      sgst: money(\"sgst\"),\n      igst: money(\"igst\"),\n      roundOff: money(\"roundOff\"),\n      total,\n      paid: money(\"paid\"),\n      balance,\n    },\n    lines: (row.lines || row.items || []).map(normInvoiceLine),\n    payments: (row.payments || []).map(normPayment),\n    raw: row,\n  };\n}\n\nexport function normInvoiceLine(row) {\n  if (!row) return null;\n  return {\n    id: row.id,\n    itemId: row.itemId ?? row.item_id ?? null,\n    name: row.name || row.itemName || row.description || \"\",\n    hsn: row.hsn || \"\",\n    unit: row.unit || \"PCS\",\n    quantity: num(row.quantity ?? row.qty, 0),\n    ratePaise: paiseFrom(row, \"rate\"),\n    discountPaise: paiseFrom(row, \"discount\"),\n    taxRate: num(row.taxRate ?? row.tax_rate, 0),\n    taxablePaise: paiseFrom(row, \"taxable\"),\n    cgstPaise: paiseFrom(row, \"cgst\"),\n    sgstPaise: paiseFrom(row, \"sgst\"),\n    igstPaise: paiseFrom(row, \"igst\"),\n    totalPaise: paiseFrom(row, \"total\"),\n    raw: row,\n  };\n}\n\nexport async function listInvoices(params = {}) {\n  const res = await api.get(`/api/invoices${qs(params)}`);\n  return { rows: rowsOf(res).map(normInvoice), total: totalOf(res) };\n}\n\nexport async function getInvoice(id) {\n  return normInvoice(await api.get(`/api/invoices/${id}`));\n}\n\nexport async function createInvoice(payload) {\n  return normInvoice(await api.post(\"/api/invoices\", payload));\n}\n\n// ---------------------------------------------------------------------------\n// endpoints whose exact path may differ\n// ---------------------------------------------------------------------------\n// Cancelling, correcting stock and reading the stock history are each\n// reasonable as more than one route. Rather than guess once and fail, try\n// the likely ones in turn and remember which answered, so the next call goes\n// straight there. A 404 or 405 means \"not this one\"; any other error is a\n// real failure and is thrown as it is.\nconst resolved = new Map();\n\nasync function tryRoutes(key, attempts) {\n  const known = resolved.get(key);\n  if (known !== undefined) {\n    if (known === null) throw new ApiError(\"Not supported by this server yet.\", { status: 404, code: \"unsupported\" });\n    return attempts[known]();\n  }\n  let last = null;\n  for (let i = 0; i < attempts.length; i++) {\n    try {\n      const out = await attempts[i]();\n      resolved.set(key, i);\n      return out;\n    } catch (e) {\n      if (e instanceof ApiError && (e.status === 404 || e.status === 405)) {\n        last = e;\n        continue;\n      }\n      throw e;\n    }\n  }\n  resolved.set(key, null);\n  throw last || new ApiError(\"Not supported by this server yet.\", { status: 404, code: \"unsupported\" });\n}\n\nexport async function cancelInvoice(id, reason) {\n  const out = await tryRoutes(`cancel`, [\n    () => api.post(`/api/invoices/${id}/cancel`, { reason }),\n    () => api.patch(`/api/invoices/${id}`, { status: \"cancelled\", cancelReason: reason }),\n    () => api.del(`/api/invoices/${id}${qs({ reason })}`),\n  ]);\n  return normInvoice(out) || { id };\n}\n\nexport async function adjustStock(itemId, { quantity, reason, notes }) {\n  const body = { change: quantity, quantity, reason, notes };\n  const out = await tryRoutes(`stockAdjust`, [\n    () => api.post(`/api/items/${itemId}/stock`, body),\n    () => api.post(`/api/items/${itemId}/stock-adjust`, body),\n    () => api.post(`/api/stock-moves`, { ...body, itemId }),\n  ]);\n  return normItem(out?.item || out) || null;\n}\n\nexport async function listStockMoves(itemId, params = {}) {\n  const out = await tryRoutes(`stockMoves`, [\n    () => api.get(`/api/items/${itemId}/stock-moves${qs(params)}`),\n    () => api.get(`/api/stock-moves${qs({ ...params, itemId })}`),\n  ]);\n  return rowsOf(out).map((row) => ({\n    id: row.id,\n    change: num(row.quantityChange ?? row.quantity_change ?? row.change, 0),\n    balanceAfter: num(row.balanceAfter ?? row.balance_after, 0),\n    reason: row.reason || \"\",\n    refType: row.refType || row.ref_type || \"\",\n    refId: row.refId ?? row.ref_id ?? null,\n    notes: row.notes || \"\",\n    createdAt: row.createdAt || row.created_at || null,\n  }));\n}\n\n// ---------------------------------------------------------------------------\n// payments\n// ---------------------------------------------------------------------------\nexport function normPayment(row) {\n  if (!row) return null;\n  return {\n    id: row.id,\n    direction: row.direction || \"in\",\n    partyId: row.partyId ?? row.party_id ?? null,\n    partyName: row.partyName || row.party?.name || \"\",\n    amountPaise: paiseFrom(row, \"amount\"),\n    mode: row.mode || \"cash\",\n    date: String(row.date || row.createdAt || \"\").slice(0, 10),\n    notes: row.notes || row.reference || \"\",\n    allocations: row.allocations || [],\n    raw: row,\n  };\n}\n\nexport async function listPayments(params = {}) {\n  const res = await api.get(`/api/payments${qs(params)}`);\n  return { rows: rowsOf(res).map(normPayment), total: totalOf(res) };\n}\n\nexport async function createPayment({ direction, partyId, amountRupees, mode, date, notes, allocations }) {\n  const body = { direction, partyId, amount: amountRupees, mode };\n  if (date) body.date = date;\n  if (notes) body.notes = notes;\n  if (allocations && allocations.length) body.allocations = allocations;\n  return normPayment(await api.post(\"/api/payments\", body));\n}\n\n// ---------------------------------------------------------------------------\n// the shop itself\n// ---------------------------------------------------------------------------\nexport function normBusiness(row) {\n  if (!row) return null;\n  return {\n    id: row.id,\n    name: row.name || \"\",\n    stateCode: row.stateCode || row.state_code || \"\",\n    stateName: row.stateName || row.state_name || \"\",\n    gstin: row.gstin || \"\",\n    phone: row.phone || \"\",\n    email: row.email || \"\",\n    address: row.address || \"\",\n    city: row.city || \"\",\n    pincode: row.pincode || \"\",\n    industry: row.industry || \"\",\n    plan: row.plan || row.subscription?.plan || null,\n    raw: row,\n  };\n}\n\nexport async function getBusiness(id) {\n  return normBusiness(await api.get(`/api/businesses/${id}`));\n}\n\nexport { ApiError };\n","components/app/items/ItemForm.js":"\"use client\";\n\n// ===========================================================================\n// ADD OR EDIT AN ITEM\n// ---------------------------------------------------------------------------\n// Used both from the Items page and straight out of the billing screen,\n// where a shopkeeper is halfway through a bill and realises the thing in\n// their hand was never entered. In that case the name is already typed, so\n// it arrives as `initialName` and the cursor lands on the price instead.\n// ===========================================================================\n\nimport { useState } from \"react\";\nimport Modal from \"../ui/Modal\";\nimport { Text, Select, Money, Check, numericOnly } from \"../ui/Field\";\nimport { Note } from \"../ui/Bits\";\nimport { ITEMS, COMMON } from \"../content\";\nimport { UNITS } from \"../../../lib/units\";\nimport { TAX_RATES } from \"../../../lib/gst-calc\";\nimport { createItem, updateItem } from \"../data\";\nimport { useToast } from \"../ui/Toast\";\n\nfunction blank(initialName = \"\") {\n  return {\n    name: initialName,\n    type: \"goods\",\n    code: \"\",\n    hsn: \"\",\n    unit: \"PCS\",\n    salePrice: \"\",\n    taxIncluded: false,\n    purchasePrice: \"\",\n    taxRate: \"5\",\n    openingStock: \"\",\n    lowStockAlert: \"\",\n    description: \"\",\n  };\n}\n\nfunction fromItem(item) {\n  return {\n    name: item.name,\n    type: item.type,\n    code: item.code,\n    hsn: item.hsn,\n    unit: item.unit,\n    salePrice: item.salePaise ? String(item.salePaise / 100) : \"\",\n    taxIncluded: item.taxIncluded,\n    purchasePrice: item.costPaise ? String(item.costPaise / 100) : \"\",\n    taxRate: String(item.taxRate ?? 0),\n    openingStock: String(item.stock ?? \"\"),\n    lowStockAlert: item.lowStockAlert == null ? \"\" : String(item.lowStockAlert),\n    description: item.description || \"\",\n  };\n}\n\nexport default function ItemForm({ item, initialName = \"\", onClose, onSaved }) {\n  const editing = Boolean(item);\n  const [form, setForm] = useState(() => (editing ? fromItem(item) : blank(initialName)));\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState(null);\n  const [fieldErrs, setFieldErrs] = useState({});\n  const { toast } = useToast();\n\n  const set = (key) => (e) => {\n    const value = e?.target?.type === \"checkbox\" ? e.target.checked : e?.target?.value ?? e;\n    setForm((f) => ({ ...f, [key]: value }));\n  };\n\n  const setNum = (key, opts) => (e) =>\n    setForm((f) => ({ ...f, [key]: numericOnly(e.target.value, opts) }));\n\n  async function submit(e) {\n    e.preventDefault();\n    setErr(null);\n    setFieldErrs({});\n\n    if (!form.name.trim()) {\n      setFieldErrs({ name: COMMON.required });\n      return;\n    }\n\n    setBusy(true);\n    try {\n      const saved = editing ? await updateItem(item.id, form) : await createItem(form);\n      toast(\n        editing\n          ? ITEMS.form.saved\n          : ITEMS.form.savedNew.replace(\"{name}\", saved?.name || form.name.trim())\n      );\n      onSaved?.(saved);\n    } catch (e2) {\n      // The server's validator names the fields it did not like; show them\n      // against the inputs rather than as one lump at the top.\n      if (e2.fields && typeof e2.fields === \"object\") {\n        const map = {};\n        for (const [k, v] of Object.entries(e2.fields)) map[k] = Array.isArray(v) ? v[0] : String(v);\n        setFieldErrs(map);\n      }\n      setErr(e2.isOffline ? COMMON.offlineBody : e2.message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const isService = form.type === \"service\";\n\n  return (\n    <Modal\n      title={editing ? ITEMS.form.editTitle : ITEMS.form.addTitle}\n      onClose={onClose}\n      wide\n      footer={\n        <>\n          <button type=\"button\" className=\"ap-btn\" onClick={onClose} disabled={busy}>\n            {COMMON.cancel}\n          </button>\n          <button type=\"submit\" form=\"ap-itemform\" className=\"ap-btn ap-btn-primary\" disabled={busy}>\n            {busy ? COMMON.saving : COMMON.save}\n          </button>\n        </>\n      }\n    >\n      <form id=\"ap-itemform\" onSubmit={submit} className=\"ap-stack\">\n        {err ? <Note kind=\"bad\">{err}</Note> : null}\n\n        <Text\n          label={ITEMS.form.name}\n          placeholder={ITEMS.form.namePlaceholder}\n          value={form.name}\n          onChange={set(\"name\")}\n          error={fieldErrs.name}\n          required\n          autoFocus={!initialName}\n          autoComplete=\"off\"\n          maxLength={160}\n        />\n\n        <div className=\"ap-grid3\">\n          <Select label={ITEMS.form.type} value={form.type} onChange={set(\"type\")} hint={ITEMS.form.typeHint}>\n            <option value=\"goods\">{ITEMS.form.typeGoods}</option>\n            <option value=\"service\">{ITEMS.form.typeService}</option>\n          </Select>\n\n          <Select label={ITEMS.form.unit} value={form.unit} onChange={set(\"unit\")} disabled={isService}>\n            {UNITS.map((u) => (\n              <option key={u.code} value={u.code}>\n                {u.label} ({u.short})\n              </option>\n            ))}\n          </Select>\n\n          <Select\n            label={ITEMS.form.taxRate}\n            value={form.taxRate}\n            onChange={set(\"taxRate\")}\n            error={fieldErrs.taxRate}\n          >\n            {TAX_RATES.map((t) => (\n              <option key={t.value} value={String(t.value)}>\n                {t.label}\n              </option>\n            ))}\n          </Select>\n        </div>\n\n        <div className=\"ap-grid2\">\n          <Money\n            label={ITEMS.form.salePrice}\n            hint={ITEMS.form.salePriceHint}\n            value={form.salePrice}\n            onChange={setNum(\"salePrice\")}\n            error={fieldErrs.salePrice}\n            autoFocus={Boolean(initialName)}\n            placeholder=\"0.00\"\n          />\n          <Money\n            label={ITEMS.form.purchasePrice}\n            hint={ITEMS.form.purchasePriceHint}\n            value={form.purchasePrice}\n            onChange={setNum(\"purchasePrice\")}\n            error={fieldErrs.purchasePrice}\n            placeholder=\"0.00\"\n          />\n        </div>\n\n        <Check\n          label={ITEMS.form.taxIncluded}\n          hint=\"Tick this if the price above is the MRP. The GST is then taken out of it rather than added on top.\"\n          checked={form.taxIncluded}\n          onChange={set(\"taxIncluded\")}\n        />\n\n        {!isService ? (\n          <div className=\"ap-grid2\">\n            <Text\n              label={ITEMS.form.openingStock}\n              hint={ITEMS.form.openingStockHint}\n              value={form.openingStock}\n              onChange={setNum(\"openingStock\")}\n              inputMode=\"decimal\"\n              placeholder=\"0\"\n              disabled={editing}\n            />\n            <Text\n              label={ITEMS.form.lowStockAlert}\n              hint={ITEMS.form.lowStockHint}\n              value={form.lowStockAlert}\n              onChange={setNum(\"lowStockAlert\")}\n              inputMode=\"decimal\"\n              placeholder=\"e.g. 5\"\n            />\n          </div>\n        ) : null}\n\n        {editing && !isService ? (\n          <Note kind=\"info\" icon={false}>\n            Stock cannot be edited here on purpose. Use <strong>Correct the stock</strong> on the item so\n            the change is written down with a reason. That record is what makes the numbers trustworthy\n            later.\n          </Note>\n        ) : null}\n\n        <div className=\"ap-grid2\">\n          <Text\n            label={ITEMS.form.code}\n            placeholder={ITEMS.form.codePlaceholder}\n            hint={ITEMS.form.codeHint}\n            value={form.code}\n            onChange={set(\"code\")}\n            autoComplete=\"off\"\n            maxLength={60}\n          />\n          <Text\n            label={ITEMS.form.hsn}\n            hint={ITEMS.form.hsnHint}\n            value={form.hsn}\n            onChange={(e) => setForm((f) => ({ ...f, hsn: numericOnly(e.target.value, { decimals: false }) }))}\n            inputMode=\"numeric\"\n            maxLength={8}\n            error={fieldErrs.hsn}\n          />\n        </div>\n      </form>\n    </Modal>\n  );\n}\n","components/app/items/ItemsPage.js":"\"use client\";\n\n// ===========================================================================\n// ITEMS\n// ---------------------------------------------------------------------------\n// The shop's list of what it sells, with the stock against each. The search\n// goes to the server rather than filtering what is already loaded, because a\n// kirana shop with two thousand items would otherwise be downloading all of\n// them to find one.\n//\n// The totals strip along the top is the thing a shopkeeper actually looks at\n// here: how much stock is sitting on the shelves, and how much of it has run\n// out without anybody noticing.\n// ===========================================================================\n\nimport { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport { ITEMS, COMMON } from \"../content\";\nimport { Empty, ErrorState, PageHead, TableSkeleton } from \"../ui/Bits\";\nimport { IconPlus, IconSearch, IconBox, IconEdit, IconHistory } from \"../Icons\";\nimport { rupees, rupeesShort, formatQty } from \"../../../lib/money\";\nimport { unitShort } from \"../../../lib/units\";\nimport { listItems } from \"../data\";\nimport ItemForm from \"./ItemForm\";\nimport StockAdjust from \"./StockAdjust\";\nimport StockHistory from \"./StockHistory\";\n\nexport default function ItemsPage() {\n  const [q, setQ] = useState(\"\");\n  const [filter, setFilter] = useState(\"all\");\n  const [rows, setRows] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  const [editing, setEditing] = useState(null);\n  const [adding, setAdding] = useState(false);\n  const [adjusting, setAdjusting] = useState(null);\n  const [history, setHistory] = useState(null);\n\n  const seq = useRef(0);\n\n  const load = useCallback(async (term) => {\n    const mine = ++seq.current;\n    setLoading(true);\n    setError(null);\n    try {\n      const { rows: found } = await listItems({ search: term || undefined, limit: 200 });\n      if (seq.current !== mine) return;\n      setRows(found);\n    } catch (e) {\n      if (seq.current === mine) setError(e);\n    } finally {\n      if (seq.current === mine) setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    const timer = setTimeout(() => load(q.trim()), q ? 220 : 0);\n    return () => clearTimeout(timer);\n  }, [q, load]);\n\n  const shown = useMemo(() => {\n    if (filter === \"low\") return rows.filter((r) => r.type !== \"service\" && (r.isLow || r.isOut));\n    if (filter === \"services\") return rows.filter((r) => r.type === \"service\");\n    return rows;\n  }, [rows, filter]);\n\n  const totals = useMemo(() => {\n    const goods = rows.filter((r) => r.type !== \"service\");\n    return {\n      count: rows.length,\n      stockValue: goods.reduce((a, r) => a + r.stockValuePaise, 0),\n      low: goods.filter((r) => r.isLow && !r.isOut).length,\n      out: goods.filter((r) => r.isOut).length,\n    };\n  }, [rows]);\n\n  function replaceRow(saved) {\n    if (!saved) return;\n    setRows((prev) => {\n      const at = prev.findIndex((r) => r.id === saved.id);\n      if (at < 0) return [saved, ...prev];\n      const next = [...prev];\n      next[at] = saved;\n      return next;\n    });\n  }\n\n  return (\n    <>\n      <PageHead title={ITEMS.title}>\n        <button type=\"button\" className=\"ap-btn ap-btn-primary\" onClick={() => setAdding(true)}>\n          <IconPlus size={17} /> {ITEMS.add}\n        </button>\n      </PageHead>\n\n      {!loading && rows.length ? (\n        <div className=\"ap-tiles\" style={{ marginBottom: 14 }}>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">Items</div>\n            <div className=\"ap-tile-value\">{totals.count}</div>\n          </div>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">Stock value</div>\n            <div className=\"ap-tile-value\">{rupeesShort(totals.stockValue)}</div>\n            <div className=\"ap-tile-note\">at cost where known</div>\n          </div>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">Running low</div>\n            <div className=\"ap-tile-value\">{totals.low}</div>\n          </div>\n          {/* Red only when there is something to be red about. A zero in red\n              reads as a problem when it is the opposite. */}\n          <div className={totals.out ? \"ap-tile ap-tile-bad\" : \"ap-tile\"}>\n            <div className=\"ap-tile-label\">Out of stock</div>\n            <div className=\"ap-tile-value\">{totals.out}</div>\n          </div>\n        </div>\n      ) : null}\n\n      <div className=\"ap-panel\">\n        <div className=\"ap-panel-head\">\n          <div className=\"ap-search\">\n            <span className=\"ap-search-ico\">\n              <IconSearch size={17} />\n            </span>\n            <input\n              className=\"ap-input\"\n              placeholder={ITEMS.searchPlaceholder}\n              value={q}\n              onChange={(e) => setQ(e.target.value)}\n              aria-label={ITEMS.searchPlaceholder}\n            />\n          </div>\n          <div className=\"ap-seg ap-spacer\">\n            <button type=\"button\" aria-pressed={filter === \"all\"} onClick={() => setFilter(\"all\")}>\n              {ITEMS.filterAll}\n            </button>\n            <button type=\"button\" aria-pressed={filter === \"low\"} onClick={() => setFilter(\"low\")}>\n              {ITEMS.filterLow}\n            </button>\n            <button\n              type=\"button\"\n              aria-pressed={filter === \"services\"}\n              onClick={() => setFilter(\"services\")}\n            >\n              {ITEMS.filterServices}\n            </button>\n          </div>\n        </div>\n\n        {error ? (\n          <div className=\"ap-panel-body\">\n            <ErrorState error={error} onRetry={() => load(q.trim())} />\n          </div>\n        ) : loading ? (\n          <TableSkeleton rows={6} cols={5} />\n        ) : shown.length ? (\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <thead>\n                <tr>\n                  <th>{ITEMS.colName}</th>\n                  <th className=\"ap-right\">{ITEMS.colStock}</th>\n                  <th className=\"ap-right\">{ITEMS.colSale}</th>\n                  <th className=\"ap-right\">{ITEMS.colPurchase}</th>\n                  <th className=\"ap-right\">{ITEMS.colTax}</th>\n                  <th className=\"ap-right\">{ITEMS.colValue}</th>\n                  <th />\n                </tr>\n              </thead>\n              <tbody>\n                {shown.map((r) => (\n                  <tr key={r.id}>\n                    <td>\n                      <span className=\"ap-strong\">{r.name}</span>\n                      <div className=\"ap-sub\">\n                        {[r.code || null, r.hsn ? `HSN ${r.hsn}` : null, r.type === \"service\" ? ITEMS.service : null]\n                          .filter(Boolean)\n                          .join(\" · \") || unitShort(r.unit)}\n                      </div>\n                    </td>\n\n                    <td className=\"ap-right\">\n                      {r.type === \"service\" ? (\n                        <span className=\"ap-sub\">{\"–\"}</span>\n                      ) : (\n                        <>\n                          <span className=\"ap-num ap-strong\">\n                            {formatQty(r.stock)} {unitShort(r.unit)}\n                          </span>\n                          {r.isOut ? (\n                            <div>\n                              <span className=\"ap-pill ap-pill-unpaid\">{ITEMS.outTag}</span>\n                            </div>\n                          ) : r.isLow ? (\n                            <div>\n                              <span className=\"ap-pill ap-pill-part\">{ITEMS.lowTag}</span>\n                            </div>\n                          ) : null}\n                        </>\n                      )}\n                    </td>\n\n                    <td className=\"ap-right ap-num\">{rupees(r.salePaise)}</td>\n                    <td className=\"ap-right ap-num\">\n                      {r.costPaise ? rupees(r.costPaise) : <span className=\"ap-sub\">{\"–\"}</span>}\n                    </td>\n                    <td className=\"ap-right ap-num\">{r.taxRate}%</td>\n                    <td className=\"ap-right ap-num\">\n                      {r.type === \"service\" ? (\n                        <span className=\"ap-sub\">{\"–\"}</span>\n                      ) : (\n                        rupees(r.stockValuePaise)\n                      )}\n                    </td>\n\n                    <td className=\"ap-right\">\n                      <div className=\"ap-row\" style={{ justifyContent: \"flex-end\", gap: 4 }}>\n                        <button\n                          type=\"button\"\n                          className=\"ap-btn ap-btn-ghost ap-btn-icon\"\n                          title={COMMON.edit}\n                          aria-label={`${COMMON.edit} ${r.name}`}\n                          onClick={() => setEditing(r)}\n                        >\n                          <IconEdit size={16} />\n                        </button>\n                        {r.type !== \"service\" ? (\n                          <>\n                            <button\n                              type=\"button\"\n                              className=\"ap-btn ap-btn-sm\"\n                              onClick={() => setAdjusting(r)}\n                            >\n                              Stock\n                            </button>\n                            <button\n                              type=\"button\"\n                              className=\"ap-btn ap-btn-ghost ap-btn-icon\"\n                              title={ITEMS.history}\n                              aria-label={`${ITEMS.history} for ${r.name}`}\n                              onClick={() => setHistory(r)}\n                            >\n                              <IconHistory size={16} />\n                            </button>\n                          </>\n                        ) : null}\n                      </div>\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <Empty\n            icon={<IconBox size={34} />}\n            title={q ? ITEMS.emptySearchTitle : ITEMS.emptyTitle}\n            body={q ? ITEMS.emptySearchBody : ITEMS.emptyBody}\n            action={\n              <button\n                type=\"button\"\n                className=\"ap-btn ap-btn-primary\"\n                onClick={() => (q ? setAdding(true) : setAdding(true))}\n              >\n                <IconPlus size={17} /> {ITEMS.add}\n              </button>\n            }\n          />\n        )}\n      </div>\n\n      {adding ? (\n        <ItemForm\n          initialName={q.trim()}\n          onClose={() => setAdding(false)}\n          onSaved={(saved) => {\n            setAdding(false);\n            replaceRow(saved);\n          }}\n        />\n      ) : null}\n\n      {editing ? (\n        <ItemForm\n          item={editing}\n          onClose={() => setEditing(null)}\n          onSaved={(saved) => {\n            setEditing(null);\n            replaceRow(saved);\n          }}\n        />\n      ) : null}\n\n      {adjusting ? (\n        <StockAdjust\n          item={adjusting}\n          onClose={() => setAdjusting(null)}\n          onSaved={(saved) => {\n            setAdjusting(null);\n            // The server may answer with the item, or with nothing useful.\n            // Reloading is cheap and is certain to be right.\n            if (saved && saved.id) replaceRow(saved);\n            else load(q.trim());\n          }}\n        />\n      ) : null}\n\n      {history ? <StockHistory item={history} onClose={() => setHistory(null)} /> : null}\n    </>\n  );\n}\n","components/app/items/StockAdjust.js":"\"use client\";\n\n// ===========================================================================\n// CORRECTING THE STOCK\n// ---------------------------------------------------------------------------\n// The shelf says eight, the app says ten. Something broke, or was given\n// away, or was never entered properly. This is where that gets straightened\n// out - and it asks for a reason, because a stock number nobody can explain\n// is a stock number nobody trusts.\n//\n// The shopkeeper types what is actually there, not the difference. Working\n// out \"minus two\" in their head is a step that can go wrong, and the whole\n// point of the screen is that the two numbers end up matching.\n// ===========================================================================\n\nimport { useMemo, useState } from \"react\";\nimport Modal from \"../ui/Modal\";\nimport { Text, Select, TextArea, numericOnly } from \"../ui/Field\";\nimport { Note } from \"../ui/Bits\";\nimport { ITEMS, COMMON } from \"../content\";\nimport { formatQty } from \"../../../lib/money\";\nimport { unitShort } from \"../../../lib/units\";\nimport { adjustStock } from \"../data\";\nimport { useToast } from \"../ui/Toast\";\n\nexport default function StockAdjust({ item, onClose, onSaved }) {\n  const [actual, setActual] = useState(() => formatQty(item.stock));\n  const [reason, setReason] = useState(\"correction\");\n  const [notes, setNotes] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState(null);\n  const { toast } = useToast();\n\n  const change = useMemo(() => {\n    const target = Number(actual);\n    if (!Number.isFinite(target)) return 0;\n    return Number((target - Number(item.stock)).toFixed(3));\n  }, [actual, item.stock]);\n\n  async function submit(e) {\n    e.preventDefault();\n    setErr(null);\n    if (!change) {\n      setErr(\"The count already matches. Nothing to change.\");\n      return;\n    }\n    setBusy(true);\n    try {\n      const saved = await adjustStock(item.id, { quantity: change, reason, notes: notes.trim() || undefined });\n      toast(ITEMS.stock.done);\n      onSaved?.(saved);\n    } catch (e2) {\n      if (e2.code === \"unsupported\") {\n        setErr(\n          \"This server does not have a stock correction route yet. Everything else works; tell the developer which path it should be and it will be pointed at it.\"\n        );\n      } else {\n        setErr(e2.isOffline ? COMMON.offlineBody : e2.message || COMMON.genericError);\n      }\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const unit = unitShort(item.unit);\n\n  return (\n    <Modal\n      title={ITEMS.stock.title}\n      onClose={onClose}\n      footer={\n        <>\n          <button type=\"button\" className=\"ap-btn\" onClick={onClose} disabled={busy}>\n            {COMMON.cancel}\n          </button>\n          <button type=\"submit\" form=\"ap-stockform\" className=\"ap-btn ap-btn-primary\" disabled={busy}>\n            {busy ? COMMON.saving : COMMON.save}\n          </button>\n        </>\n      }\n    >\n      <form id=\"ap-stockform\" onSubmit={submit} className=\"ap-stack\">\n        {err ? <Note kind=\"bad\">{err}</Note> : null}\n\n        <div>\n          <span className=\"ap-sub\">Item</span>\n          <div className=\"ap-strong\">{item.name}</div>\n        </div>\n\n        <p className=\"ap-hint\" style={{ margin: 0 }}>\n          {ITEMS.stock.note}\n        </p>\n\n        <div className=\"ap-grid3\">\n          <div>\n            <span className=\"ap-label\">{ITEMS.stock.current}</span>\n            <div className=\"ap-strong ap-num\" style={{ fontSize: 18, paddingTop: 6 }}>\n              {formatQty(item.stock)} {unit}\n            </div>\n          </div>\n\n          <Text\n            label={ITEMS.stock.actual}\n            value={actual}\n            onChange={(e) => setActual(numericOnly(e.target.value))}\n            inputMode=\"decimal\"\n            autoFocus\n            required\n          />\n\n          <div>\n            <span className=\"ap-label\">{ITEMS.stock.change}</span>\n            <div\n              className=\"ap-strong ap-num\"\n              style={{\n                fontSize: 18,\n                paddingTop: 6,\n                color: change < 0 ? \"var(--ap-danger)\" : change > 0 ? \"var(--ap-brand-ink)\" : \"var(--ap-ink-3)\",\n              }}\n            >\n              {change > 0 ? \"+\" : \"\"}\n              {formatQty(change)} {unit}\n            </div>\n          </div>\n        </div>\n\n        <Select label={ITEMS.stock.reason} value={reason} onChange={(e) => setReason(e.target.value)}>\n          {ITEMS.stock.reasons.map((r) => (\n            <option key={r.value} value={r.value}>\n              {r.label}\n            </option>\n          ))}\n        </Select>\n\n        <TextArea\n          label={ITEMS.stock.notes}\n          value={notes}\n          onChange={(e) => setNotes(e.target.value)}\n          rows={2}\n          placeholder=\"Anything that would help explain this in six months\"\n        />\n      </form>\n    </Modal>\n  );\n}\n","components/app/items/StockHistory.js":"\"use client\";\n\n// ===========================================================================\n// WHERE THE STOCK WENT\n// ---------------------------------------------------------------------------\n// Every change to an item's stock is written down as it happens, with the\n// running balance after it and what caused it. So when the shelf and the app\n// disagree, there is a trail to walk back through rather than an argument.\n//\n// Nothing in here can be edited. That is the point of it.\n// ===========================================================================\n\nimport { useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport Modal from \"../ui/Modal\";\nimport { Empty, Note, Spinner } from \"../ui/Bits\";\nimport { ITEMS, COMMON } from \"../content\";\nimport { formatQty, formatDate } from \"../../../lib/money\";\nimport { unitShort } from \"../../../lib/units\";\nimport { listStockMoves } from \"../data\";\nimport { IconHistory } from \"../Icons\";\n\nconst REASON_LABEL = {\n  sale: \"Sold\",\n  purchase: \"Bought in\",\n  credit_note: \"Returned by customer\",\n  debit_note: \"Returned to supplier\",\n  opening: \"Opening stock\",\n  correction: \"Count correction\",\n  damage: \"Damaged\",\n  expired: \"Expired\",\n  lost: \"Lost or stolen\",\n  sample: \"Given free\",\n  other: \"Other\",\n  cancel: \"Bill cancelled\",\n};\n\nexport default function StockHistory({ item, onClose }) {\n  const [rows, setRows] = useState(null);\n  const [err, setErr] = useState(null);\n\n  useEffect(() => {\n    let alive = true;\n    listStockMoves(item.id, { limit: 60 })\n      .then((r) => alive && setRows(r))\n      .catch((e) => alive && setErr(e));\n    return () => {\n      alive = false;\n    };\n  }, [item.id]);\n\n  const unit = unitShort(item.unit);\n\n  return (\n    <Modal\n      title={`${ITEMS.history} · ${item.name}`}\n      onClose={onClose}\n      wide\n      footer={\n        <button type=\"button\" className=\"ap-btn\" onClick={onClose}>\n          {COMMON.close}\n        </button>\n      }\n    >\n      {err ? (\n        <Note kind={err.code === \"unsupported\" ? \"info\" : \"bad\"} icon={false}>\n          {err.code === \"unsupported\"\n            ? \"This server does not expose the stock history yet. The movements are being recorded — they just are not readable from here until that route exists.\"\n            : err.isOffline\n            ? COMMON.offlineBody\n            : err.message}\n        </Note>\n      ) : rows === null ? (\n        <Spinner />\n      ) : rows.length ? (\n        <div className=\"ap-tablewrap\" style={{ maxHeight: 420, overflowY: \"auto\" }}>\n          <table className=\"ap-table\">\n            <thead>\n              <tr>\n                <th>When</th>\n                <th>What happened</th>\n                <th className=\"ap-right\">Change</th>\n                <th className=\"ap-right\">Left</th>\n              </tr>\n            </thead>\n            <tbody>\n              {rows.map((m) => (\n                <tr key={m.id}>\n                  <td className=\"ap-sub\">{formatDate(m.createdAt)}</td>\n                  <td>\n                    <span>{REASON_LABEL[m.reason] || m.reason || \"Change\"}</span>\n                    {m.refType === \"invoice\" && m.refId ? (\n                      <div className=\"ap-sub\">\n                        <Link href={`/app/bills/${m.refId}`}>Open the bill</Link>\n                      </div>\n                    ) : null}\n                    {m.notes ? <div className=\"ap-sub\">{m.notes}</div> : null}\n                  </td>\n                  <td\n                    className=\"ap-right ap-num ap-strong\"\n                    style={{ color: m.change < 0 ? \"var(--ap-danger)\" : \"var(--ap-brand-ink)\" }}\n                  >\n                    {m.change > 0 ? \"+\" : \"\"}\n                    {formatQty(m.change)}\n                  </td>\n                  <td className=\"ap-right ap-num\">\n                    {formatQty(m.balanceAfter)} {unit}\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      ) : (\n        <Empty icon={<IconHistory size={32} />} title={ITEMS.historyEmpty} />\n      )}\n    </Modal>\n  );\n}\n","components/app/parties/PartiesPage.js":"\"use client\";\n\n// ===========================================================================\n// CUSTOMERS AND SUPPLIERS\n// ---------------------------------------------------------------------------\n// The list is sorted by who owes the most, not alphabetically. A shopkeeper\n// opening this screen is almost always here to find out who to chase, and\n// an A-to-Z list buries that.\n// ===========================================================================\n\nimport { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useSearchParams } from \"next/navigation\";\nimport { PARTIES } from \"../content\";\nimport { Empty, ErrorState, PageHead, TableSkeleton } from \"../ui/Bits\";\nimport { IconPlus, IconSearch, IconUsers, IconPhone } from \"../Icons\";\nimport { rupees, rupeesShort, formatDate } from \"../../../lib/money\";\nimport { listParties } from \"../data\";\nimport PartyForm from \"./PartyForm\";\n\nexport default function PartiesPage() {\n  const params = useSearchParams();\n  const [q, setQ] = useState(\"\");\n  const [filter, setFilter] = useState(() => (params?.get(\"filter\") === \"owing\" ? \"owing\" : \"all\"));\n  const [rows, setRows] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const [adding, setAdding] = useState(false);\n  const seq = useRef(0);\n\n  const load = useCallback(async (term) => {\n    const mine = ++seq.current;\n    setLoading(true);\n    setError(null);\n    try {\n      const { rows: found } = await listParties({ search: term || undefined, limit: 200 });\n      if (seq.current !== mine) return;\n      setRows(found);\n    } catch (e) {\n      if (seq.current === mine) setError(e);\n    } finally {\n      if (seq.current === mine) setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    const timer = setTimeout(() => load(q.trim()), q ? 220 : 0);\n    return () => clearTimeout(timer);\n  }, [q, load]);\n\n  const shown = useMemo(() => {\n    let out = rows;\n    if (filter === \"customers\") out = out.filter((r) => r.type === \"customer\" || r.type === \"both\");\n    if (filter === \"suppliers\") out = out.filter((r) => r.type === \"supplier\" || r.type === \"both\");\n    if (filter === \"owing\") out = out.filter((r) => r.owesUs > 0);\n    return [...out].sort((a, b) => b.owesUs - a.owesUs || a.name.localeCompare(b.name));\n  }, [rows, filter]);\n\n  const totals = useMemo(\n    () => ({\n      toCollect: rows.reduce((a, r) => a + r.owesUs, 0),\n      toPay: rows.reduce((a, r) => a + r.weOwe, 0),\n      owing: rows.filter((r) => r.owesUs > 0).length,\n    }),\n    [rows]\n  );\n\n  return (\n    <>\n      <PageHead title={PARTIES.title}>\n        <button type=\"button\" className=\"ap-btn ap-btn-primary\" onClick={() => setAdding(true)}>\n          <IconPlus size={17} /> {PARTIES.add}\n        </button>\n      </PageHead>\n\n      {!loading && rows.length ? (\n        <div className=\"ap-tiles\" style={{ marginBottom: 14, gridTemplateColumns: \"repeat(3, minmax(0,1fr))\" }}>\n          <div className=\"ap-tile ap-tile-bad\">\n            <div className=\"ap-tile-label\">{PARTIES.filterOwing}</div>\n            <div className=\"ap-tile-value\">{rupeesShort(totals.toCollect)}</div>\n            <div className=\"ap-tile-note\">across {totals.owing} customers</div>\n          </div>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">You owe</div>\n            <div className=\"ap-tile-value\">{rupeesShort(totals.toPay)}</div>\n          </div>\n          <div className=\"ap-tile\">\n            <div className=\"ap-tile-label\">On the books</div>\n            <div className=\"ap-tile-value\">{rows.length}</div>\n          </div>\n        </div>\n      ) : null}\n\n      <div className=\"ap-panel\">\n        <div className=\"ap-panel-head\">\n          <div className=\"ap-search\">\n            <span className=\"ap-search-ico\">\n              <IconSearch size={17} />\n            </span>\n            <input\n              className=\"ap-input\"\n              placeholder={PARTIES.searchPlaceholder}\n              value={q}\n              onChange={(e) => setQ(e.target.value)}\n              aria-label={PARTIES.searchPlaceholder}\n            />\n          </div>\n          <div className=\"ap-seg ap-spacer\">\n            {[\n              [\"all\", PARTIES.filterAll],\n              [\"customers\", PARTIES.filterCustomers],\n              [\"suppliers\", PARTIES.filterSuppliers],\n              [\"owing\", PARTIES.filterOwing],\n            ].map(([value, label]) => (\n              <button key={value} type=\"button\" aria-pressed={filter === value} onClick={() => setFilter(value)}>\n                {label}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        {error ? (\n          <div className=\"ap-panel-body\">\n            <ErrorState error={error} onRetry={() => load(q.trim())} />\n          </div>\n        ) : loading ? (\n          <TableSkeleton rows={6} cols={4} />\n        ) : shown.length ? (\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <thead>\n                <tr>\n                  <th>{PARTIES.colName}</th>\n                  <th>{PARTIES.colPhone}</th>\n                  <th>Last bill</th>\n                  <th className=\"ap-right\">{PARTIES.colBalance}</th>\n                </tr>\n              </thead>\n              <tbody>\n                {shown.map((p) => (\n                  <tr key={p.id}>\n                    <td>\n                      <Link href={`/app/parties/${p.id}`}>{p.name}</Link>\n                      <div className=\"ap-sub\">\n                        {[\n                          p.type === \"supplier\" ? \"Supplier\" : p.type === \"both\" ? \"Customer and supplier\" : null,\n                          p.city || null,\n                          p.gstin || null,\n                        ]\n                          .filter(Boolean)\n                          .join(\" · \")}\n                      </div>\n                    </td>\n                    <td>\n                      {p.phone ? (\n                        <a href={`tel:+91${p.phone}`} className=\"ap-row\" style={{ gap: 6 }}>\n                          <IconPhone size={14} /> {p.phone}\n                        </a>\n                      ) : (\n                        <span className=\"ap-sub\">{\"–\"}</span>\n                      )}\n                    </td>\n                    <td className=\"ap-sub\">{p.lastBillDate ? formatDate(p.lastBillDate) : \"–\"}</td>\n                    <td className=\"ap-right\">\n                      {p.balancePaise === 0 ? (\n                        <span className=\"ap-sub\">{PARTIES.settled}</span>\n                      ) : (\n                        <>\n                          <span\n                            className=\"ap-strong ap-num\"\n                            style={{ color: p.owesUs ? \"var(--ap-danger)\" : \"var(--ap-brand-ink)\" }}\n                          >\n                            {rupees(Math.abs(p.balancePaise))}\n                          </span>\n                          <div className=\"ap-sub\">{p.owesUs ? PARTIES.owesYou : PARTIES.youOwe}</div>\n                        </>\n                      )}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <Empty\n            icon={<IconUsers size={34} />}\n            title={q ? PARTIES.emptySearchTitle : PARTIES.emptyTitle}\n            body={q ? PARTIES.emptySearchBody : PARTIES.emptyBody}\n            action={\n              <button type=\"button\" className=\"ap-btn ap-btn-primary\" onClick={() => setAdding(true)}>\n                <IconPlus size={17} /> {PARTIES.add}\n              </button>\n            }\n          />\n        )}\n      </div>\n\n      {adding ? (\n        <PartyForm\n          initial={{ name: q.trim() }}\n          onClose={() => setAdding(false)}\n          onSaved={(saved) => {\n            setAdding(false);\n            if (saved) setRows((prev) => [saved, ...prev.filter((r) => r.id !== saved.id)]);\n          }}\n        />\n      ) : null}\n    </>\n  );\n}\n","components/app/parties/PartyDetail.js":"\"use client\";\n\n// ===========================================================================\n// ONE CUSTOMER\n// ---------------------------------------------------------------------------\n// What they owe, every bill, every payment, and a WhatsApp reminder that is\n// written for them rather than a template with a blank in it.\n//\n// The reminder is a link, not a messaging integration. It opens WhatsApp\n// with the words ready and the shopkeeper presses send. No API, no fee, no\n// approval process, and it works the same from a phone and a desktop.\n// ===========================================================================\n\nimport { useCallback, useEffect, useState } from \"react\";\nimport Link from \"next/link\";\nimport { PARTIES, BILLS, COMMON } from \"../content\";\nimport { Empty, ErrorState, PageHead, StatusPill, TableSkeleton, Note } from \"../ui/Bits\";\nimport { IconPhone, IconWhatsApp, IconEdit, IconPlus, IconBill, IconRupee } from \"../Icons\";\nimport { rupees, formatDate, relativeDay, ageInDays } from \"../../../lib/money\";\nimport { modeLabel } from \"../../../lib/units\";\nimport { stateName } from \"../../../lib/gst-states\";\nimport { getParty, listInvoices, listPayments } from \"../data\";\nimport { useShop } from \"../useShop\";\nimport PartyForm from \"./PartyForm\";\nimport PaymentForm from \"../payments/PaymentForm\";\n\nexport default function PartyDetail({ id }) {\n  const shop = useShop();\n  const [party, setParty] = useState(null);\n  const [bills, setBills] = useState([]);\n  const [payments, setPayments] = useState([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  const [editing, setEditing] = useState(false);\n  const [collecting, setCollecting] = useState(false);\n\n  const load = useCallback(async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const [p, inv, pay] = await Promise.all([\n        getParty(id),\n        listInvoices({ partyId: id, limit: 60 }).catch(() => ({ rows: [] })),\n        listPayments({ partyId: id, limit: 40 }).catch(() => ({ rows: [] })),\n      ]);\n      setParty(p);\n      setBills(inv.rows);\n      setPayments(pay.rows);\n    } catch (e) {\n      setError(e);\n    } finally {\n      setLoading(false);\n    }\n  }, [id]);\n\n  useEffect(() => {\n    load();\n  }, [load]);\n\n  if (error) return <ErrorState error={error} onRetry={load} />;\n\n  if (loading || !party) {\n    return (\n      <div className=\"ap-panel\">\n        <TableSkeleton rows={5} cols={3} />\n      </div>\n    );\n  }\n\n  const owes = party.owesUs > 0;\n  const oldestOpen = bills\n    .filter((b) => b.status !== \"cancelled\" && b.amounts.balance > 0)\n    .sort((a, b) => String(a.date).localeCompare(String(b.date)))[0];\n\n  const reminder = PARTIES.detail.reminderText\n    .replace(\"{name}\", party.name)\n    .replace(\"{shop}\", shop.shop?.name || \"our shop\")\n    .replace(\"{amount}\", rupees(party.owesUs));\n\n  const waHref = party.phone\n    ? `https://wa.me/91${String(party.phone).slice(-10)}?text=${encodeURIComponent(reminder)}`\n    : null;\n\n  return (\n    <>\n      <PageHead title={party.name}>\n        {party.phone ? (\n          <a className=\"ap-btn\" href={`tel:+91${party.phone}`}>\n            <IconPhone size={16} /> {PARTIES.detail.call}\n          </a>\n        ) : null}\n        {waHref && owes ? (\n          <a className=\"ap-btn\" href={waHref} target=\"_blank\" rel=\"noopener noreferrer\">\n            <IconWhatsApp size={16} /> {PARTIES.detail.remind}\n          </a>\n        ) : null}\n        <button type=\"button\" className=\"ap-btn\" onClick={() => setEditing(true)}>\n          <IconEdit size={16} /> {COMMON.edit}\n        </button>\n        <button type=\"button\" className=\"ap-btn ap-btn-primary\" onClick={() => setCollecting(true)}>\n          <IconRupee size={16} /> {owes ? PARTIES.detail.collect : PARTIES.detail.pay}\n        </button>\n      </PageHead>\n\n      <div className=\"ap-grid2\" style={{ gap: 16, alignItems: \"start\", marginBottom: 16 }}>\n        <div className=\"ap-panel\">\n          <div className=\"ap-panel-body\">\n            <div className=\"ap-tile-label\">{PARTIES.colBalance}</div>\n            <div\n              className=\"ap-tile-value\"\n              style={{ color: owes ? \"var(--ap-danger)\" : party.weOwe ? \"var(--ap-brand-ink)\" : undefined }}\n            >\n              {party.balancePaise === 0 ? PARTIES.settled : rupees(Math.abs(party.balancePaise))}\n            </div>\n            {party.balancePaise !== 0 ? (\n              <div className=\"ap-tile-note\">{owes ? PARTIES.owesYou : PARTIES.youOwe}</div>\n            ) : null}\n\n            {oldestOpen ? (\n              <div style={{ marginTop: 12 }}>\n                <Note kind={ageInDays(oldestOpen.date) > 30 ? \"warn\" : \"info\"} icon={false}>\n                  Oldest unpaid bill is <strong>{oldestOpen.number}</strong> from{\" \"}\n                  {formatDate(oldestOpen.date)}\n                  {ageInDays(oldestOpen.date) > 0 ? ` — ${ageInDays(oldestOpen.date)} days ago` : \"\"}.\n                </Note>\n              </div>\n            ) : null}\n          </div>\n        </div>\n\n        <div className=\"ap-panel\">\n          <div className=\"ap-panel-body\" style={{ display: \"grid\", gap: 8, fontSize: 13.5 }}>\n            <Row label=\"Phone\" value={party.phone ? `+91 ${party.phone}` : null} />\n            <Row label=\"Email\" value={party.email} />\n            <Row label=\"GSTIN\" value={party.gstin} mono />\n            <Row label=\"State\" value={party.stateCode ? stateName(party.stateCode) : null} />\n            <Row label=\"Address\" value={[party.address, party.city, party.pincode].filter(Boolean).join(\", \")} />\n          </div>\n        </div>\n      </div>\n\n      <section className=\"ap-panel\" style={{ marginBottom: 16 }}>\n        <div className=\"ap-panel-head\">\n          <h2>{PARTIES.detail.bills}</h2>\n          <Link href=\"/app/billing\" className=\"ap-btn ap-btn-sm ap-spacer\">\n            <IconPlus size={15} /> {BILLS.add}\n          </Link>\n        </div>\n        {bills.length ? (\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <thead>\n                <tr>\n                  <th>{BILLS.colNumber}</th>\n                  <th>{BILLS.colDate}</th>\n                  <th className=\"ap-right\">{BILLS.colTotal}</th>\n                  <th className=\"ap-right\">{BILLS.colBalance}</th>\n                  <th className=\"ap-right\">{BILLS.colStatus}</th>\n                </tr>\n              </thead>\n              <tbody>\n                {bills.map((b) => (\n                  <tr key={b.id}>\n                    <td>\n                      <Link href={`/app/bills/${b.id}`}>{b.number}</Link>\n                    </td>\n                    <td className=\"ap-sub\">{relativeDay(b.date)}</td>\n                    <td className=\"ap-right ap-num\">{rupees(b.amounts.total)}</td>\n                    <td className=\"ap-right ap-num\">\n                      {b.amounts.balance > 0 ? (\n                        <span style={{ color: \"var(--ap-danger)\" }}>{rupees(b.amounts.balance)}</span>\n                      ) : (\n                        <span className=\"ap-sub\">{\"–\"}</span>\n                      )}\n                    </td>\n                    <td className=\"ap-right\">\n                      <StatusPill invoice={b} />\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <Empty icon={<IconBill size={30} />} title={PARTIES.detail.billsEmpty} />\n        )}\n      </section>\n\n      <section className=\"ap-panel\">\n        <div className=\"ap-panel-head\">\n          <h2>{PARTIES.detail.payments}</h2>\n        </div>\n        {payments.length ? (\n          <div className=\"ap-tablewrap\">\n            <table className=\"ap-table\">\n              <tbody>\n                {payments.map((p) => (\n                  <tr key={p.id}>\n                    <td className=\"ap-sub\">{formatDate(p.date)}</td>\n                    <td>\n                      {p.direction === \"in\" ? \"Received\" : \"Paid\"} by {modeLabel(p.mode)}\n                      {p.notes ? <div className=\"ap-sub\">{p.notes}</div> : null}\n                    </td>\n                    <td\n                      className=\"ap-right ap-num ap-strong\"\n                      style={{ color: p.direction === \"in\" ? \"var(--ap-brand-ink)\" : \"var(--ap-ink)\" }}\n                    >\n                      {rupees(p.amountPaise)}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ) : (\n          <Empty icon={<IconRupee size={30} />} title={PARTIES.detail.ledgerEmpty} />\n        )}\n      </section>\n\n      {editing ? (\n        <PartyForm\n          party={party}\n          onClose={() => setEditing(false)}\n          onSaved={() => {\n            setEditing(false);\n            load();\n          }}\n        />\n      ) : null}\n\n      {collecting ? (\n        <PaymentForm\n          party={party}\n          direction={owes || party.balancePaise === 0 ? \"in\" : \"out\"}\n          onClose={() => setCollecting(false)}\n          onSaved={() => {\n            setCollecting(false);\n            load();\n          }}\n        />\n      ) : null}\n    </>\n  );\n}\n\nfunction Row({ label, value, mono }) {\n  if (!value) return null;\n  return (\n    <div style={{ display: \"flex\", gap: 12 }}>\n      <span className=\"ap-sub\" style={{ width: 78, flex: \"0 0 auto\" }}>\n        {label}\n      </span>\n      <span style={mono ? { fontFamily: \"var(--ap-mono)\" } : undefined}>{value}</span>\n    </div>\n  );\n}\n","components/app/parties/PartyForm.js":"\"use client\";\n\n// ===========================================================================\n// ADD OR EDIT A CUSTOMER OR SUPPLIER\n// ---------------------------------------------------------------------------\n// Opened from the Customers page and from the billing screen mid-bill. Only\n// the name is compulsory: a shopkeeper adding a customer at the counter with\n// a queue behind them should be able to type a name and get on with it.\n//\n// Two bits of quiet help worth keeping:\n//   - typing a GSTIN fills in the state from its first two digits, because\n//     that is exactly what those digits mean\n//   - the state is what decides CGST+SGST versus IGST, so when it is missing\n//     the form says so rather than leaving it looking optional\n// ===========================================================================\n\nimport { useState } from \"react\";\nimport Modal from \"../ui/Modal\";\nimport { Text, Select, Money, TextArea, digitsOnly, numericOnly } from \"../ui/Field\";\nimport { Note } from \"../ui/Bits\";\nimport { PARTIES, COMMON } from \"../content\";\nimport { GST_STATES, isValidGstin, stateCodeFromGstin } from \"../../../lib/gst-states\";\nimport { createParty, updateParty } from \"../data\";\nimport { useToast } from \"../ui/Toast\";\n\nfunction blank(initial = {}) {\n  return {\n    name: initial.name || \"\",\n    type: initial.type || \"customer\",\n    phone: initial.phone || \"\",\n    email: \"\",\n    gstin: \"\",\n    stateCode: initial.stateCode || \"\",\n    address: \"\",\n    city: \"\",\n    pincode: \"\",\n    openingBalance: \"\",\n    openingDirection: \"owes\",\n  };\n}\n\nfunction fromParty(p) {\n  return {\n    name: p.name,\n    type: p.type,\n    phone: p.phone,\n    email: p.email,\n    gstin: p.gstin,\n    stateCode: p.stateCode,\n    address: p.address,\n    city: p.city,\n    pincode: p.pincode,\n    openingBalance: \"\",\n    openingDirection: \"owes\",\n  };\n}\n\nexport default function PartyForm({ party, initial, onClose, onSaved }) {\n  const editing = Boolean(party);\n  const [form, setForm] = useState(() => (editing ? fromParty(party) : blank(initial)));\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState(null);\n  const [fieldErrs, setFieldErrs] = useState({});\n  const { toast } = useToast();\n\n  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));\n\n  function onGstin(e) {\n    const value = e.target.value.toUpperCase().replace(/[^0-9A-Z]/g, \"\").slice(0, 15);\n    setForm((f) => {\n      // The first two digits of a GSTIN are the state code. Filling it in\n      // saves a step and removes a way to get the tax wrong.\n      const fromGstin = stateCodeFromGstin(value);\n      return { ...f, gstin: value, stateCode: fromGstin && !f.stateCode ? fromGstin : f.stateCode };\n    });\n  }\n\n  async function submit(e) {\n    e.preventDefault();\n    setErr(null);\n    const errs = {};\n    if (!form.name.trim()) errs.name = COMMON.required;\n    if (form.gstin && !isValidGstin(form.gstin)) errs.gstin = PARTIES.form.gstinBad;\n    if (form.phone && form.phone.length !== 10) errs.phone = \"A mobile number is 10 digits.\";\n    setFieldErrs(errs);\n    if (Object.keys(errs).length) return;\n\n    setBusy(true);\n    try {\n      const saved = editing ? await updateParty(party.id, form) : await createParty(form);\n      toast(\n        editing\n          ? PARTIES.form.saved\n          : PARTIES.form.savedNew.replace(\"{name}\", saved?.name || form.name.trim())\n      );\n      onSaved?.(saved);\n    } catch (e2) {\n      if (e2.fields && typeof e2.fields === \"object\") {\n        const map = {};\n        for (const [k, v] of Object.entries(e2.fields)) map[k] = Array.isArray(v) ? v[0] : String(v);\n        setFieldErrs(map);\n      }\n      setErr(e2.isOffline ? COMMON.offlineBody : e2.message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <Modal\n      title={editing ? PARTIES.form.editTitle : PARTIES.form.addTitle}\n      onClose={onClose}\n      wide\n      footer={\n        <>\n          <button type=\"button\" className=\"ap-btn\" onClick={onClose} disabled={busy}>\n            {COMMON.cancel}\n          </button>\n          <button type=\"submit\" form=\"ap-partyform\" className=\"ap-btn ap-btn-primary\" disabled={busy}>\n            {busy ? COMMON.saving : COMMON.save}\n          </button>\n        </>\n      }\n    >\n      <form id=\"ap-partyform\" onSubmit={submit} className=\"ap-stack\">\n        {err ? <Note kind=\"bad\">{err}</Note> : null}\n\n        <div className=\"ap-grid2\">\n          <Text\n            label={PARTIES.form.name}\n            placeholder={PARTIES.form.namePlaceholder}\n            value={form.name}\n            onChange={set(\"name\")}\n            error={fieldErrs.name}\n            required\n            autoFocus\n            autoComplete=\"off\"\n            maxLength={160}\n          />\n          <Select label={PARTIES.form.type} value={form.type} onChange={set(\"type\")}>\n            <option value=\"customer\">{PARTIES.form.typeCustomer}</option>\n            <option value=\"supplier\">{PARTIES.form.typeSupplier}</option>\n            <option value=\"both\">{PARTIES.form.typeBoth}</option>\n          </Select>\n        </div>\n\n        <div className=\"ap-grid2\">\n          <Text\n            label={PARTIES.form.phone}\n            hint={PARTIES.form.phoneHint}\n            value={form.phone}\n            onChange={(e) => setForm((f) => ({ ...f, phone: digitsOnly(e.target.value, 10) }))}\n            inputMode=\"numeric\"\n            error={fieldErrs.phone}\n            placeholder=\"98765 43210\"\n          />\n          <Text\n            label={PARTIES.form.email}\n            type=\"email\"\n            value={form.email}\n            onChange={set(\"email\")}\n            error={fieldErrs.email}\n            autoComplete=\"off\"\n          />\n        </div>\n\n        <div className=\"ap-grid2\">\n          <Text\n            label={PARTIES.form.gstin}\n            hint={PARTIES.form.gstinHint}\n            value={form.gstin}\n            onChange={onGstin}\n            error={fieldErrs.gstin}\n            autoComplete=\"off\"\n            style={{ textTransform: \"uppercase\", fontFamily: \"var(--ap-mono)\" }}\n            placeholder=\"09ABCDE1234F1Z5\"\n          />\n          <Select\n            label={PARTIES.form.stateCode}\n            hint={PARTIES.form.stateHint}\n            value={form.stateCode}\n            onChange={set(\"stateCode\")}\n            error={fieldErrs.stateCode}\n          >\n            <option value=\"\">Not set</option>\n            {GST_STATES.map((s) => (\n              <option key={s.code} value={s.code}>\n                {s.name}\n              </option>\n            ))}\n          </Select>\n        </div>\n\n        <TextArea label={PARTIES.form.address} value={form.address} onChange={set(\"address\")} rows={2} />\n\n        <div className=\"ap-grid2\">\n          <Text label={PARTIES.form.city} value={form.city} onChange={set(\"city\")} autoComplete=\"off\" />\n          <Text\n            label={PARTIES.form.pincode}\n            value={form.pincode}\n            onChange={(e) => setForm((f) => ({ ...f, pincode: digitsOnly(e.target.value, 6) }))}\n            inputMode=\"numeric\"\n          />\n        </div>\n\n        {!editing ? (\n          <div className=\"ap-grid2\">\n            <Money\n              label={PARTIES.form.openingBalance}\n              hint={PARTIES.form.openingBalanceHint}\n              value={form.openingBalance}\n              onChange={(e) => setForm((f) => ({ ...f, openingBalance: numericOnly(e.target.value) }))}\n              placeholder=\"0.00\"\n            />\n            <Select\n              label=\"Which way round\"\n              value={form.openingDirection}\n              onChange={set(\"openingDirection\")}\n              disabled={!Number(form.openingBalance)}\n            >\n              <option value=\"owes\">{PARTIES.form.openingOwesYou}</option>\n              <option value=\"owe\">{PARTIES.form.openingIOwe}</option>\n            </Select>\n          </div>\n        ) : null}\n      </form>\n    </Modal>\n  );\n}\n","components/app/payments/PaymentForm.js":"\"use client\";\n\n// ===========================================================================\n// TAKING A PAYMENT\n// ---------------------------------------------------------------------------\n// Opened from a customer, or from one particular bill.\n//\n// The part worth getting right is what the money is put against. A customer\n// handing over two thousand rupees against four old bills does not say which\n// ones - and if the app guesses wrongly, the ageing is wrong and the shop\n// chases the wrong bill. So:\n//\n//   - by default it clears the oldest bills first, which is what almost\n//     every shop does and what an accountant expects\n//   - the shopkeeper can override it and tick the bills themselves\n//   - anything left over sits on the account rather than being forced onto\n//     a bill it does not belong to\n//\n// Opened from a single bill, that bill is pre-ticked and the rest is hidden.\n// ===========================================================================\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport Modal from \"../ui/Modal\";\nimport { Money, Select, Text, TextArea, numericOnly } from \"../ui/Field\";\nimport { Note, Spinner } from \"../ui/Bits\";\nimport { PAYMENT, COMMON } from \"../content\";\nimport { PAYMENT_MODES } from \"../../../lib/units\";\nimport { rupees, today, toPaise, formatDate, ageInDays } from \"../../../lib/money\";\nimport { listInvoices, createPayment } from \"../data\";\nimport { useToast } from \"../ui/Toast\";\n\nexport default function PaymentForm({ party, invoice, direction = \"in\", onClose, onSaved }) {\n  const { toast } = useToast();\n  const singleBill = Boolean(invoice);\n\n  const [amount, setAmount] = useState(() =>\n    invoice ? String(Math.max(0, invoice.amounts.balance) / 100) : \"\"\n  );\n  const [mode, setMode] = useState(\"cash\");\n  const [date, setDate] = useState(() => today());\n  const [notes, setNotes] = useState(\"\");\n  const [manual, setManual] = useState(false);\n  const [ticked, setTicked] = useState(() => (invoice ? { [invoice.id]: true } : {}));\n\n  const [pending, setPending] = useState(singleBill ? [invoice] : null);\n  const [loading, setLoading] = useState(!singleBill);\n  const [busy, setBusy] = useState(false);\n  const [err, setErr] = useState(null);\n\n  // Which bills are still open for this customer, oldest first - that is the\n  // order the money is applied in.\n  useEffect(() => {\n    if (singleBill || !party?.id) return;\n    let alive = true;\n    (async () => {\n      try {\n        const { rows } = await listInvoices({\n          partyId: party.id,\n          docType: direction === \"in\" ? \"sale\" : \"purchase\",\n          limit: 100,\n        });\n        if (!alive) return;\n        setPending(\n          rows\n            .filter((r) => r.status !== \"cancelled\" && r.amounts.balance > 0)\n            .sort((a, b) => String(a.date).localeCompare(String(b.date)))\n        );\n      } catch (e) {\n        if (alive) setErr(e.isOffline ? COMMON.offlineBody : e.message);\n      } finally {\n        if (alive) setLoading(false);\n      }\n    })();\n    return () => {\n      alive = false;\n    };\n  }, [party, direction, singleBill]);\n\n  const amountPaise = Math.max(0, toPaise(amount));\n\n  // Work out the split. Either the ticked bills, or oldest first until the\n  // money runs out.\n  const split = useMemo(() => {\n    const rows = pending || [];\n    const chosen = manual ? rows.filter((r) => ticked[r.id]) : rows;\n    let left = amountPaise;\n    const out = [];\n    for (const r of chosen) {\n      if (left <= 0) break;\n      const take = Math.min(left, r.amounts.balance);\n      if (take <= 0) continue;\n      out.push({ invoice: r, paise: take });\n      left -= take;\n    }\n    return { allocations: out, leftover: left };\n  }, [pending, manual, ticked, amountPaise]);\n\n  const totalPending = (pending || []).reduce((a, r) => a + r.amounts.balance, 0);\n\n  async function submit(e) {\n    e.preventDefault();\n    setErr(null);\n    if (amountPaise <= 0) {\n      setErr(\"Enter how much was received.\");\n      return;\n    }\n    setBusy(true);\n    try {\n      const saved = await createPayment({\n        direction,\n        partyId: party?.id,\n        amountRupees: amountPaise / 100,\n        mode,\n        date,\n        notes: notes.trim() || undefined,\n        allocations: split.allocations.map((a) => ({\n          invoiceId: a.invoice.id,\n          amount: a.paise / 100,\n        })),\n      });\n      toast(PAYMENT.done);\n      onSaved?.(saved);\n    } catch (e2) {\n      setErr(e2.isOffline ? COMMON.offlineBody : e2.message || COMMON.genericError);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  const title = direction === \"in\" ? PAYMENT.title : PAYMENT.titleOut;\n\n  return (\n    <Modal\n      title={title}\n      onClose={onClose}\n      footer={\n        <>\n          <button type=\"button\" className=\"ap-btn\" onClick={onClose} disabled={busy}>\n            {COMMON.cancel}\n          </button>\n          <button type=\"submit\" form=\"ap-payform\" className=\"ap-btn ap-btn-primary\" disabled={busy}>\n            {busy ? COMMON.saving : PAYMENT.save}\n          </button>\n        </>\n      }\n    >\n      <form id=\"ap-payform\" onSubmit={submit} className=\"ap-stack\">\n        {err ? <Note kind=\"bad\">{err}</Note> : null}\n\n        <div className=\"ap-row\" style={{ justifyContent: \"space-between\" }}>\n          <div>\n            <span className=\"ap-sub\">{direction === \"in\" ? PAYMENT.party : PAYMENT.partyOut}</span>\n            <div className=\"ap-strong\">{party?.name || \"Walk-in\"}</div>\n          </div>\n          {!singleBill && pending ? (\n            <div style={{ textAlign: \"right\" }}>\n              <span className=\"ap-sub\">{PAYMENT.outstanding}</span>\n              <div className=\"ap-strong ap-num\">{rupees(totalPending)}</div>\n            </div>\n          ) : null}\n        </div>\n\n        <div className=\"ap-grid2\">\n          <Money\n            label={PAYMENT.amount}\n            value={amount}\n            onChange={(e) => setAmount(numericOnly(e.target.value))}\n            placeholder=\"0.00\"\n            autoFocus\n            required\n          />\n          <Select label={PAYMENT.mode} value={mode} onChange={(e) => setMode(e.target.value)}>\n            {PAYMENT_MODES.map((m) => (\n              <option key={m.value} value={m.value}>\n                {m.label}\n              </option>\n            ))}\n          </Select>\n        </div>\n\n        <div className=\"ap-grid2\">\n          <Text label={PAYMENT.date} type=\"date\" value={date} onChange={(e) => setDate(e.target.value)} />\n        </div>\n\n        {singleBill ? (\n          <Note kind=\"info\" icon={false}>\n            Going against bill <strong>{invoice.number}</strong>, which has{\" \"}\n            <strong>{rupees(invoice.amounts.balance)}</strong> pending.\n          </Note>\n        ) : loading ? (\n          <Spinner />\n        ) : pending && pending.length ? (\n          <div>\n            <div className=\"ap-label\">{PAYMENT.against}</div>\n            <div className=\"ap-seg\" style={{ marginBottom: 9 }}>\n              <button type=\"button\" aria-pressed={!manual} onClick={() => setManual(false)}>\n                {PAYMENT.oldestFirst}\n              </button>\n              <button type=\"button\" aria-pressed={manual} onClick={() => setManual(true)}>\n                {PAYMENT.pickBills}\n              </button>\n            </div>\n\n            <div className=\"ap-tablewrap\" style={{ maxHeight: 210, overflowY: \"auto\" }}>\n              <table className=\"ap-table\">\n                <tbody>\n                  {pending.map((r) => {\n                    const alloc = split.allocations.find((a) => a.invoice.id === r.id);\n                    const age = ageInDays(r.date);\n                    return (\n                      <tr key={r.id}>\n                        {manual ? (\n                          <td style={{ width: 34 }}>\n                            <input\n                              type=\"checkbox\"\n                              checked={Boolean(ticked[r.id])}\n                              onChange={(e) =>\n                                setTicked((t) => ({ ...t, [r.id]: e.target.checked }))\n                              }\n                              aria-label={`Put this payment against ${r.number}`}\n                            />\n                          </td>\n                        ) : null}\n                        <td>\n                          <span className=\"ap-strong\">{r.number}</span>\n                          <div className=\"ap-sub\">\n                            {formatDate(r.date)}\n                            {age > 30 ? ` · ${age} days old` : \"\"}\n                          </div>\n                        </td>\n                        <td className=\"ap-right ap-num\">{rupees(r.amounts.balance)}</td>\n                        <td className=\"ap-right ap-num\" style={{ color: \"var(--ap-brand-ink)\" }}>\n                          {alloc ? rupees(alloc.paise) : \"\"}\n                        </td>\n                      </tr>\n                    );\n                  })}\n                </tbody>\n              </table>\n            </div>\n\n            {!manual ? <p className=\"ap-hint\">{PAYMENT.oldestFirstHint}</p> : null}\n\n            {split.leftover > 0 ? (\n              <div style={{ marginTop: 9 }}>\n                <Note kind=\"info\" icon={false}>\n                  <strong>{rupees(split.leftover)}</strong> {PAYMENT.unallocated.toLowerCase()} &mdash;{\" \"}\n                  {PAYMENT.unallocatedHint}\n                </Note>\n              </div>\n            ) : null}\n          </div>\n        ) : (\n          <Note kind=\"info\" icon={false}>\n            {PAYMENT.nothingDue} It will be kept on their account.\n          </Note>\n        )}\n\n        <TextArea\n          label={PAYMENT.note}\n          placeholder={PAYMENT.notePlaceholder}\n          value={notes}\n          onChange={(e) => setNotes(e.target.value)}\n          rows={2}\n        />\n      </form>\n    </Modal>\n  );\n}\n","components/app/print/InvoicePrint.js":"\"use client\";\n\n// ===========================================================================\n// THE BILL ON PAPER\n// ---------------------------------------------------------------------------\n// This is hidden on screen and only exists when something is printed. It is\n// a tax invoice, so it carries what the law expects a tax invoice to carry:\n// both parties' names, addresses and GSTINs, the place of supply, HSN\n// against each line, the tax split out by rate, the total in words, and the\n// word \"Tax Invoice\" at the top when the shop is registered.\n//\n// A shop that has not got a GSTIN yet cannot issue a tax invoice, so for\n// them the heading says \"Invoice\" and the tax columns are left out instead\n// of printing zeroes. Printing a tax invoice without a GSTIN would be worse\n// than printing nothing.\n//\n// Two sizes, chosen by the `size` prop:\n//   a4      - a proper invoice for a customer who files it\n//   thermal - 80mm roll, for a counter printer\n// ===========================================================================\n\nimport { rupees, formatQty, formatDateLong, paiseToWords } from \"../../../lib/money\";\nimport { unitShort } from \"../../../lib/units\";\nimport { stateName } from \"../../../lib/gst-states\";\n\nexport default function InvoicePrint({ invoice, shop, party, lines, size = \"a4\", copyLabel }) {\n  if (!invoice) return null;\n\n  const rows = (invoice.lines && invoice.lines.length ? invoice.lines : lines) || [];\n  const a = invoice.amounts || {};\n  const registered = Boolean(shop?.gstin);\n  const interState = Boolean(invoice.interState) || Number(a.igst) > 0;\n\n  const heading =\n    invoice.docType === \"estimate\"\n      ? \"Estimate\"\n      : invoice.docType === \"credit_note\"\n      ? \"Credit Note\"\n      : invoice.docType === \"debit_note\"\n      ? \"Debit Note\"\n      : invoice.docType === \"purchase\"\n      ? \"Purchase Bill\"\n      : registered\n      ? \"Tax Invoice\"\n      : \"Invoice\";\n\n  // One row per tax rate. Built from the lines rather than taken from the\n  // totals, because the printed breakup has to add up to the printed lines.\n  const breakup = [];\n  for (const l of rows) {\n    const rate = Number(l.taxRate) || 0;\n    if (!rate) continue;\n    let b = breakup.find((x) => x.rate === rate);\n    if (!b) {\n      b = { rate, taxable: 0, cgst: 0, sgst: 0, igst: 0 };\n      breakup.push(b);\n    }\n    b.taxable += Number(l.taxablePaise || 0);\n    b.cgst += Number(l.cgstPaise || 0);\n    b.sgst += Number(l.sgstPaise || 0);\n    b.igst += Number(l.igstPaise || 0);\n  }\n  breakup.sort((x, y) => x.rate - y.rate);\n\n  if (size === \"thermal\") {\n    return (\n      <div className=\"pr-sheet pr-thermal\">\n        <div className=\"pr-t-head\">\n          <strong>{shop?.name || \"Shop\"}</strong>\n          {shop?.address ? <div>{shop.address}</div> : null}\n          {shop?.city ? <div>{shop.city}</div> : null}\n          {shop?.phone ? <div>Ph {shop.phone}</div> : null}\n          {shop?.gstin ? <div>GSTIN {shop.gstin}</div> : null}\n        </div>\n\n        <div className=\"pr-t-rule\" />\n        <div className=\"pr-t-meta\">\n          <span>{invoice.number}</span>\n          <span>{formatDateLong(invoice.date)}</span>\n        </div>\n        {party?.name ? <div className=\"pr-t-meta-1\">{party.name}</div> : null}\n        <div className=\"pr-t-rule\" />\n\n        <table className=\"pr-t-table\">\n          <tbody>\n            {rows.map((l, i) => (\n              <tr key={l.id || i}>\n                <td colSpan={2}>\n                  {l.name}\n                  <div className=\"pr-t-sub\">\n                    {formatQty(l.quantity)} {unitShort(l.unit)} x {rupees(l.ratePaise)}\n                  </div>\n                </td>\n                <td className=\"pr-right\">{rupees(l.totalPaise)}</td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n\n        <div className=\"pr-t-rule\" />\n        <div className=\"pr-t-meta\">\n          <span>Taxable</span>\n          <span>{rupees(a.taxable)}</span>\n        </div>\n        {interState ? (\n          <div className=\"pr-t-meta\">\n            <span>IGST</span>\n            <span>{rupees(a.igst)}</span>\n          </div>\n        ) : (\n          <>\n            <div className=\"pr-t-meta\">\n              <span>CGST</span>\n              <span>{rupees(a.cgst)}</span>\n            </div>\n            <div className=\"pr-t-meta\">\n              <span>SGST</span>\n              <span>{rupees(a.sgst)}</span>\n            </div>\n          </>\n        )}\n        {a.roundOff ? (\n          <div className=\"pr-t-meta\">\n            <span>Round off</span>\n            <span>{rupees(a.roundOff)}</span>\n          </div>\n        ) : null}\n        <div className=\"pr-t-rule\" />\n        <div className=\"pr-t-total\">\n          <span>TOTAL</span>\n          <span>{rupees(a.total)}</span>\n        </div>\n        {a.balance > 0 ? (\n          <div className=\"pr-t-meta\">\n            <span>Pending</span>\n            <span>{rupees(a.balance)}</span>\n          </div>\n        ) : null}\n        <div className=\"pr-t-rule\" />\n        <div className=\"pr-t-foot\">Thank you. Please come again.</div>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"pr-sheet pr-a4\">\n      <div className=\"pr-head\">\n        <div className=\"pr-shop\">\n          <div className=\"pr-shop-name\">{shop?.name || \"Shop\"}</div>\n          {shop?.address ? <div>{shop.address}</div> : null}\n          <div>{[shop?.city, shop?.pincode].filter(Boolean).join(\" - \")}</div>\n          {shop?.stateCode ? (\n            <div>\n              {stateName(shop.stateCode)} ({shop.stateCode})\n            </div>\n          ) : null}\n          {shop?.phone ? <div>Phone {shop.phone}</div> : null}\n          {shop?.gstin ? (\n            <div>\n              <strong>GSTIN {shop.gstin}</strong>\n            </div>\n          ) : null}\n        </div>\n        <div className=\"pr-title\">\n          <div className=\"pr-title-main\">{heading}</div>\n          {copyLabel ? <div className=\"pr-copy\">{copyLabel}</div> : null}\n        </div>\n      </div>\n\n      <div className=\"pr-bar\">\n        <div>\n          <span className=\"pr-k\">Bill no.</span>\n          <span className=\"pr-v\">{invoice.number}</span>\n        </div>\n        <div>\n          <span className=\"pr-k\">Date</span>\n          <span className=\"pr-v\">{formatDateLong(invoice.date)}</span>\n        </div>\n        {invoice.dueDate ? (\n          <div>\n            <span className=\"pr-k\">Due</span>\n            <span className=\"pr-v\">{formatDateLong(invoice.dueDate)}</span>\n          </div>\n        ) : null}\n        <div>\n          <span className=\"pr-k\">Place of supply</span>\n          <span className=\"pr-v\">\n            {party?.stateCode ? `${stateName(party.stateCode)} (${party.stateCode})` : stateName(shop?.stateCode) || \"-\"}\n          </span>\n        </div>\n      </div>\n\n      <div className=\"pr-parties\">\n        <div className=\"pr-party\">\n          <div className=\"pr-party-h\">Billed to</div>\n          <div className=\"pr-party-name\">{party?.name || \"Walk-in customer\"}</div>\n          {party?.address ? <div>{party.address}</div> : null}\n          {party?.city || party?.pincode ? (\n            <div>{[party?.city, party?.pincode].filter(Boolean).join(\" - \")}</div>\n          ) : null}\n          {party?.stateCode ? <div>{stateName(party.stateCode)}</div> : null}\n          {party?.phone ? <div>Phone {party.phone}</div> : null}\n          {party?.gstin ? <div>GSTIN {party.gstin}</div> : null}\n        </div>\n      </div>\n\n      <table className=\"pr-table\">\n        <thead>\n          <tr>\n            <th className=\"pr-n\">#</th>\n            <th>Item</th>\n            <th className=\"pr-hsn\">HSN</th>\n            <th className=\"pr-right\">Qty</th>\n            <th className=\"pr-right\">Rate</th>\n            {registered ? <th className=\"pr-right\">Taxable</th> : null}\n            {registered ? <th className=\"pr-right\">GST</th> : null}\n            <th className=\"pr-right\">Amount</th>\n          </tr>\n        </thead>\n        <tbody>\n          {rows.map((l, i) => (\n            <tr key={l.id || i}>\n              <td className=\"pr-n\">{i + 1}</td>\n              <td>{l.name}</td>\n              <td className=\"pr-hsn\">{l.hsn || \"\"}</td>\n              <td className=\"pr-right\">\n                {formatQty(l.quantity)} {unitShort(l.unit)}\n              </td>\n              <td className=\"pr-right\">{rupees(l.ratePaise)}</td>\n              {registered ? <td className=\"pr-right\">{rupees(l.taxablePaise)}</td> : null}\n              {registered ? (\n                <td className=\"pr-right\">\n                  {rupees(Number(l.cgstPaise || 0) + Number(l.sgstPaise || 0) + Number(l.igstPaise || 0))}\n                  <span className=\"pr-rate\"> ({l.taxRate}%)</span>\n                </td>\n              ) : null}\n              <td className=\"pr-right\">{rupees(l.totalPaise)}</td>\n            </tr>\n          ))}\n        </tbody>\n      </table>\n\n      <div className=\"pr-bottom\">\n        <div className=\"pr-left\">\n          {registered && breakup.length ? (\n            <table className=\"pr-tax\">\n              <thead>\n                <tr>\n                  <th>GST %</th>\n                  <th className=\"pr-right\">Taxable</th>\n                  {interState ? (\n                    <th className=\"pr-right\">IGST</th>\n                  ) : (\n                    <>\n                      <th className=\"pr-right\">CGST</th>\n                      <th className=\"pr-right\">SGST</th>\n                    </>\n                  )}\n                </tr>\n              </thead>\n              <tbody>\n                {breakup.map((b) => (\n                  <tr key={b.rate}>\n                    <td>{b.rate}%</td>\n                    <td className=\"pr-right\">{rupees(b.taxable)}</td>\n                    {interState ? (\n                      <td className=\"pr-right\">{rupees(b.igst)}</td>\n                    ) : (\n                      <>\n                        <td className=\"pr-right\">{rupees(b.cgst)}</td>\n                        <td className=\"pr-right\">{rupees(b.sgst)}</td>\n                      </>\n                    )}\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          ) : null}\n\n          <div className=\"pr-words\">\n            <span className=\"pr-k\">Amount in words</span>\n            <div>{paiseToWords(a.total)}</div>\n          </div>\n\n          {invoice.notes ? (\n            <div className=\"pr-words\">\n              <span className=\"pr-k\">Note</span>\n              <div>{invoice.notes}</div>\n            </div>\n          ) : null}\n        </div>\n\n        <div className=\"pr-totals\">\n          <div className=\"pr-trow\">\n            <span>Taxable value</span>\n            <span>{rupees(a.taxable)}</span>\n          </div>\n          {a.discount ? (\n            <div className=\"pr-trow\">\n              <span>Discount</span>\n              <span>- {rupees(a.discount)}</span>\n            </div>\n          ) : null}\n          {registered && interState ? (\n            <div className=\"pr-trow\">\n              <span>IGST</span>\n              <span>{rupees(a.igst)}</span>\n            </div>\n          ) : null}\n          {registered && !interState ? (\n            <>\n              <div className=\"pr-trow\">\n                <span>CGST</span>\n                <span>{rupees(a.cgst)}</span>\n              </div>\n              <div className=\"pr-trow\">\n                <span>SGST</span>\n                <span>{rupees(a.sgst)}</span>\n              </div>\n            </>\n          ) : null}\n          {a.roundOff ? (\n            <div className=\"pr-trow\">\n              <span>Round off</span>\n              <span>{rupees(a.roundOff)}</span>\n            </div>\n          ) : null}\n          <div className=\"pr-trow pr-grand\">\n            <span>Total</span>\n            <span>{rupees(a.total)}</span>\n          </div>\n          {a.paid ? (\n            <div className=\"pr-trow\">\n              <span>Paid</span>\n              <span>{rupees(a.paid)}</span>\n            </div>\n          ) : null}\n          {a.balance > 0 ? (\n            <div className=\"pr-trow pr-due\">\n              <span>Pending</span>\n              <span>{rupees(a.balance)}</span>\n            </div>\n          ) : null}\n        </div>\n      </div>\n\n      <div className=\"pr-foot\">\n        <div className=\"pr-terms\">\n          <div className=\"pr-k\">Terms</div>\n          <div>Goods once sold will only be taken back as per the shop&rsquo;s policy.</div>\n        </div>\n        <div className=\"pr-sign\">\n          <div className=\"pr-sign-line\" />\n          <div>For {shop?.name || \"the shop\"}</div>\n          <div className=\"pr-k\">Authorised signatory</div>\n        </div>\n      </div>\n    </div>\n  );\n}\n","components/app/print.css":"/* ==========================================================================\n   THE PRINTED BILL\n   --------------------------------------------------------------------------\n   Prefixed pr-. Hidden on screen; only the printer ever sees it.\n\n   Two deliberate decisions:\n\n   1. Everything is in points and millimetres, not pixels. A bill has to come\n      out the same size whatever the browser's zoom was set to.\n   2. No colour that depends on being printed in colour. Most shops have a\n      black and white laser or a thermal roll, so the layout is carried by\n      rules and weight, and anything that only reads as a colour would read\n      as nothing at all.\n   ========================================================================== */\n\n.pr-sheet {\n  display: none;\n}\n\n@media print {\n  /* --------------------------------------------------------------------\n     A4\n     -------------------------------------------------------------------- */\n  @page {\n    size: A4;\n    margin: 12mm 12mm 14mm;\n  }\n\n  .pr-sheet {\n    display: block;\n    color: #000;\n    background: #fff;\n    font-family: \"Helvetica Neue\", Arial, sans-serif;\n    font-size: 9.5pt;\n    line-height: 1.35;\n  }\n\n  .pr-a4 {\n    width: 100%;\n  }\n\n  .pr-head {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 10mm;\n    border-bottom: 1.2pt solid #000;\n    padding-bottom: 3mm;\n  }\n\n  .pr-shop {\n    font-size: 9pt;\n    line-height: 1.4;\n  }\n\n  .pr-shop-name {\n    font-size: 15pt;\n    font-weight: 700;\n    letter-spacing: -0.2pt;\n    margin-bottom: 1mm;\n  }\n\n  .pr-title {\n    text-align: right;\n    flex: 0 0 auto;\n  }\n\n  .pr-title-main {\n    font-size: 13pt;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: 0.6pt;\n  }\n\n  .pr-copy {\n    font-size: 8pt;\n    text-transform: uppercase;\n    letter-spacing: 0.4pt;\n  }\n\n  .pr-bar {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 3mm 8mm;\n    padding: 2.5mm 0;\n    border-bottom: 0.4pt solid #000;\n  }\n\n  .pr-k {\n    display: block;\n    font-size: 7.5pt;\n    text-transform: uppercase;\n    letter-spacing: 0.4pt;\n    color: #444;\n  }\n\n  .pr-v {\n    font-weight: 600;\n    font-size: 10pt;\n  }\n\n  .pr-parties {\n    display: flex;\n    gap: 8mm;\n    padding: 3mm 0;\n    border-bottom: 0.4pt solid #000;\n  }\n\n  .pr-party {\n    font-size: 9pt;\n    line-height: 1.4;\n  }\n\n  .pr-party-h {\n    font-size: 7.5pt;\n    text-transform: uppercase;\n    letter-spacing: 0.4pt;\n    color: #444;\n    margin-bottom: 0.8mm;\n  }\n\n  .pr-party-name {\n    font-weight: 700;\n    font-size: 10.5pt;\n  }\n\n  /* the lines */\n  .pr-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin-top: 3mm;\n    font-size: 9pt;\n  }\n\n  .pr-table th {\n    text-align: left;\n    font-size: 7.5pt;\n    text-transform: uppercase;\n    letter-spacing: 0.3pt;\n    border-bottom: 0.8pt solid #000;\n    padding: 1.6mm 1.5mm;\n    white-space: nowrap;\n  }\n\n  .pr-table td {\n    padding: 1.6mm 1.5mm;\n    border-bottom: 0.3pt solid #999;\n    vertical-align: top;\n  }\n\n  /* Repeat the header if the bill runs onto a second page, and never split a\n     line across the break. */\n  .pr-table thead {\n    display: table-header-group;\n  }\n\n  .pr-table tr {\n    break-inside: avoid;\n    page-break-inside: avoid;\n  }\n\n  .pr-right {\n    text-align: right;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .pr-n {\n    width: 7mm;\n  }\n\n  .pr-hsn {\n    width: 16mm;\n    font-size: 8pt;\n  }\n\n  .pr-rate {\n    font-size: 7.5pt;\n    color: #444;\n  }\n\n  /* the bottom half */\n  .pr-bottom {\n    display: flex;\n    gap: 8mm;\n    margin-top: 4mm;\n    break-inside: avoid;\n  }\n\n  .pr-left {\n    flex: 1;\n    min-width: 0;\n  }\n\n  .pr-tax {\n    border-collapse: collapse;\n    font-size: 8.5pt;\n    margin-bottom: 3mm;\n  }\n\n  .pr-tax th,\n  .pr-tax td {\n    border: 0.3pt solid #666;\n    padding: 1.2mm 2.5mm;\n    white-space: nowrap;\n  }\n\n  .pr-tax th {\n    font-size: 7.5pt;\n    text-transform: uppercase;\n    letter-spacing: 0.3pt;\n  }\n\n  .pr-words {\n    margin-bottom: 2.5mm;\n    font-size: 9pt;\n    max-width: 95mm;\n  }\n\n  .pr-totals {\n    width: 62mm;\n    flex: 0 0 auto;\n    font-size: 9.5pt;\n  }\n\n  .pr-trow {\n    display: flex;\n    justify-content: space-between;\n    gap: 4mm;\n    padding: 1mm 0;\n    font-variant-numeric: tabular-nums;\n  }\n\n  .pr-grand {\n    border-top: 0.8pt solid #000;\n    border-bottom: 1.6pt double #000;\n    margin-top: 1mm;\n    padding: 1.6mm 0;\n    font-size: 12pt;\n    font-weight: 700;\n  }\n\n  .pr-due {\n    font-weight: 700;\n  }\n\n  .pr-foot {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-end;\n    gap: 10mm;\n    margin-top: 8mm;\n    break-inside: avoid;\n  }\n\n  .pr-terms {\n    font-size: 8pt;\n    max-width: 100mm;\n  }\n\n  .pr-sign {\n    text-align: center;\n    font-size: 8.5pt;\n    flex: 0 0 auto;\n  }\n\n  .pr-sign-line {\n    width: 45mm;\n    border-bottom: 0.5pt solid #000;\n    height: 14mm;\n    margin-bottom: 1mm;\n  }\n\n  /* --------------------------------------------------------------------\n     80mm thermal roll\n     --------------------------------------------------------------------\n     Printed through the same browser dialog - the shopkeeper picks the\n     roll printer and the paper size. 72mm of printable width inside an\n     80mm roll is the usual figure.\n     -------------------------------------------------------------------- */\n  .pr-thermal {\n    width: 72mm;\n    font-family: \"Courier New\", Courier, monospace;\n    font-size: 8.5pt;\n    line-height: 1.3;\n  }\n\n  .pr-t-head {\n    text-align: center;\n    font-size: 8pt;\n  }\n\n  .pr-t-head strong {\n    display: block;\n    font-size: 11pt;\n    margin-bottom: 0.6mm;\n  }\n\n  .pr-t-rule {\n    border-top: 0.4pt dashed #000;\n    margin: 1.6mm 0;\n  }\n\n  .pr-t-meta,\n  .pr-t-total {\n    display: flex;\n    justify-content: space-between;\n    gap: 3mm;\n  }\n\n  .pr-t-meta-1 {\n    margin-top: 0.8mm;\n  }\n\n  .pr-t-total {\n    font-size: 11pt;\n    font-weight: 700;\n  }\n\n  .pr-t-table {\n    width: 100%;\n    border-collapse: collapse;\n  }\n\n  .pr-t-table td {\n    padding: 0.8mm 0;\n    vertical-align: top;\n  }\n\n  .pr-t-sub {\n    font-size: 7.5pt;\n  }\n\n  .pr-t-foot {\n    text-align: center;\n    font-size: 8pt;\n    margin-top: 1.6mm;\n  }\n}\n","components/app/ui/Bits.js":"\"use client\";\n\n// ===========================================================================\n// THE SMALL SHARED PIECES\n// ---------------------------------------------------------------------------\n// Empty states, loading states, status pills, notices. Small enough that a\n// file each would be more trouble than it saves.\n// ===========================================================================\n\nimport Link from \"next/link\";\nimport { BILLS, COMMON } from \"../content\";\nimport { IconWarn } from \"../Icons\";\n\nexport function Spinner({ label }) {\n  return (\n    <span className=\"ap-row\" style={{ gap: 9, color: \"var(--ap-ink-3)\" }}>\n      <span className=\"ap-spin\" />\n      <span>{label || COMMON.loading}</span>\n    </span>\n  );\n}\n\n// A table-shaped placeholder rather than a spinner. The page does not jump\n// when the real rows arrive, which matters on a slow shop connection.\nexport function TableSkeleton({ rows = 5, cols = 4 }) {\n  return (\n    <table className=\"ap-table\" aria-hidden=\"true\">\n      <tbody>\n        {Array.from({ length: rows }).map((_, r) => (\n          <tr key={r}>\n            {Array.from({ length: cols }).map((__, c) => (\n              <td key={c}>\n                <div className=\"ap-skel\" style={{ width: c === 0 ? \"62%\" : \"40%\" }} />\n              </td>\n            ))}\n          </tr>\n        ))}\n      </tbody>\n    </table>\n  );\n}\n\nexport function Empty({ icon, title, body, action }) {\n  return (\n    <div className=\"ap-empty\">\n      {icon ? <div>{icon}</div> : null}\n      <h3>{title}</h3>\n      {body ? <p>{body}</p> : null}\n      {action}\n    </div>\n  );\n}\n\nexport function Note({ kind = \"info\", children, icon }) {\n  return (\n    <div className={`ap-note ap-note-${kind}`}>\n      {icon === false ? null : icon || <IconWarn size={17} />}\n      <div>{children}</div>\n    </div>\n  );\n}\n\n// The one place that decides what a bill's state is called and what colour\n// it gets. Left to each screen it would drift.\nexport function statusOf(invoice) {\n  if (!invoice) return \"unpaid\";\n  if (invoice.status === \"cancelled\" || invoice.cancelledAt) return \"cancelled\";\n  if (invoice.status === \"draft\") return \"draft\";\n  const total = Number(invoice.amounts?.total ?? invoice.totalPaise ?? 0);\n  const balance = Number(invoice.amounts?.balance ?? invoice.balancePaise ?? total);\n  if (balance <= 0) return \"paid\";\n  if (balance < total) return \"partial\";\n  return \"unpaid\";\n}\n\nexport function StatusPill({ invoice, status }) {\n  const s = status || statusOf(invoice);\n  return <span className={`ap-pill ap-pill-${s === \"draft\" ? \"info\" : s}`}>{BILLS.statuses[s] || s}</span>;\n}\n\n// A failure the user can do something about. Offline gets its own words\n// because \"try again\" is the right advice there and nowhere else.\nexport function ErrorState({ error, onRetry }) {\n  const offline = error?.isOffline;\n  return (\n    <div className=\"ap-panel\">\n      <div className=\"ap-panel-body\">\n        <Note kind={offline ? \"warn\" : \"bad\"}>\n          <strong style={{ display: \"block\", marginBottom: 3 }}>\n            {offline ? COMMON.offlineTitle : COMMON.genericError}\n          </strong>\n          {offline ? COMMON.offlineBody : error?.message || \"\"}\n        </Note>\n        {onRetry ? (\n          <div style={{ marginTop: 12 }}>\n            <button type=\"button\" className=\"ap-btn\" onClick={onRetry}>\n              {COMMON.retry}\n            </button>\n          </div>\n        ) : null}\n      </div>\n    </div>\n  );\n}\n\n// The top bar already shows the page's name, so printing it again here would\n// just be the same word twice. The heading stays in the markup for screen\n// readers and for anybody landing on the page with styles off.\nexport function PageHead({ title, children }) {\n  return (\n    <div className=\"ap-row\" style={{ marginBottom: 14, justifyContent: \"flex-end\" }}>\n      <h1 className=\"ap-sronly\">{title}</h1>\n      {children}\n    </div>\n  );\n}\n\nexport function LinkButton({ href, children, variant = \"\", ...rest }) {\n  return (\n    <Link href={href} className={`ap-btn ${variant}`} {...rest}>\n      {children}\n    </Link>\n  );\n}\n","components/app/ui/Field.js":"\"use client\";\n\n// ===========================================================================\n// FORM PIECES\n// ---------------------------------------------------------------------------\n// Label, input, hint and error in one component, because the three of them\n// getting out of step is the commonest form bug there is. The error is tied\n// to the input with aria-describedby so a screen reader reads it.\n// ===========================================================================\n\nimport { useId } from \"react\";\n\nexport function Field({ label, hint, error, required, children, id: given }) {\n  const auto = useId();\n  const id = given || auto;\n  const hintId = hint ? `${id}-hint` : undefined;\n  const errId = error ? `${id}-err` : undefined;\n\n  return (\n    <div className=\"ap-field\">\n      {label ? (\n        <label className=\"ap-label\" htmlFor={id}>\n          {label}\n          {required ? <span className=\"ap-req\"> *</span> : null}\n        </label>\n      ) : null}\n      {typeof children === \"function\"\n        ? children({\n            id,\n            \"aria-describedby\": [hintId, errId].filter(Boolean).join(\" \") || undefined,\n            \"aria-invalid\": error ? \"true\" : undefined,\n          })\n        : children}\n      {hint && !error ? (\n        <p className=\"ap-hint\" id={hintId}>\n          {hint}\n        </p>\n      ) : null}\n      {error ? (\n        <p className=\"ap-err\" id={errId}>\n          {error}\n        </p>\n      ) : null}\n    </div>\n  );\n}\n\nexport function Text({ label, hint, error, required, id, ...rest }) {\n  return (\n    <Field label={label} hint={hint} error={error} required={required} id={id}>\n      {(a) => <input className=\"ap-input\" {...a} {...rest} />}\n    </Field>\n  );\n}\n\nexport function Select({ label, hint, error, required, children, id, ...rest }) {\n  return (\n    <Field label={label} hint={hint} error={error} required={required} id={id}>\n      {(a) => (\n        <select className=\"ap-select\" {...a} {...rest}>\n          {children}\n        </select>\n      )}\n    </Field>\n  );\n}\n\nexport function TextArea({ label, hint, error, required, id, ...rest }) {\n  return (\n    <Field label={label} hint={hint} error={error} required={required} id={id}>\n      {(a) => <textarea className=\"ap-textarea\" {...a} {...rest} />}\n    </Field>\n  );\n}\n\n// ---------------------------------------------------------------------------\n// money input\n// ---------------------------------------------------------------------------\n// Held as the string the user is typing, not as a number, so a half-typed\n// \"12.\" does not get reformatted out from under them mid-keystroke.\n// inputMode=\"decimal\" gets the number pad on a phone without the spinner\n// arrows and scroll-wheel surprises of type=\"number\".\nexport function Money({ label, hint, error, required, id, ...rest }) {\n  return (\n    <Field label={label} hint={hint} error={error} required={required} id={id}>\n      {(a) => (\n        <div className=\"ap-money\">\n          <input\n            className=\"ap-input\"\n            type=\"text\"\n            inputMode=\"decimal\"\n            autoComplete=\"off\"\n            {...a}\n            {...rest}\n          />\n        </div>\n      )}\n    </Field>\n  );\n}\n\nexport function Check({ label, hint, ...rest }) {\n  return (\n    <div>\n      <label className=\"ap-check\">\n        <input type=\"checkbox\" {...rest} />\n        <span>{label}</span>\n      </label>\n      {hint ? <p className=\"ap-hint\">{hint}</p> : null}\n    </div>\n  );\n}\n\n// Only digits, and only as many as asked for. Used for phone and PIN code,\n// where a stray letter means a WhatsApp message that never arrives.\nexport function digitsOnly(value, max) {\n  const d = String(value || \"\").replace(/\\D+/g, \"\");\n  return max ? d.slice(0, max) : d;\n}\n\n// Accepts digits and one decimal point, nothing else. Lets the field hold\n// \"12.\" while it is being typed.\nexport function numericOnly(value, { decimals = true } = {}) {\n  let s = String(value ?? \"\").replace(decimals ? /[^0-9.]/g : /[^0-9]/g, \"\");\n  if (decimals) {\n    const first = s.indexOf(\".\");\n    if (first !== -1) s = s.slice(0, first + 1) + s.slice(first + 1).replace(/\\./g, \"\");\n  }\n  return s;\n}\n","components/app/ui/Modal.js":"\"use client\";\n\n// ===========================================================================\n// MODAL\n// ---------------------------------------------------------------------------\n// Escape closes it, the backdrop closes it, and focus is trapped inside\n// while it is open and handed back to whatever opened it on close. A till\n// operator working on the keyboard should never tab out of a dialog into the\n// page behind it.\n// ===========================================================================\n\nimport { useEffect, useRef } from \"react\";\nimport { IconClose } from \"../Icons\";\n\nexport default function Modal({ title, onClose, children, footer, wide = false, labelledBy }) {\n  const box = useRef(null);\n  const returnTo = useRef(null);\n\n  useEffect(() => {\n    returnTo.current = document.activeElement;\n\n    // The first real input, so typing can start straight away.\n    const first = box.current?.querySelector(\n      \"input:not([type=hidden]):not([disabled]), select, textarea, button\"\n    );\n    first?.focus();\n\n    const onKey = (e) => {\n      if (e.key === \"Escape\") {\n        e.stopPropagation();\n        onClose?.();\n        return;\n      }\n      if (e.key !== \"Tab\") return;\n\n      const focusable = [\n        ...(box.current?.querySelectorAll(\n          'a[href], button:not([disabled]), input:not([type=hidden]):not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex=\"-1\"])'\n        ) || []),\n      ].filter((el) => el.offsetParent !== null);\n      if (!focusable.length) return;\n\n      const first2 = focusable[0];\n      const last = focusable[focusable.length - 1];\n      if (e.shiftKey && document.activeElement === first2) {\n        e.preventDefault();\n        last.focus();\n      } else if (!e.shiftKey && document.activeElement === last) {\n        e.preventDefault();\n        first2.focus();\n      }\n    };\n\n    document.addEventListener(\"keydown\", onKey, true);\n    // Stop the page behind from scrolling under the dialog.\n    const prevOverflow = document.body.style.overflow;\n    document.body.style.overflow = \"hidden\";\n\n    return () => {\n      document.removeEventListener(\"keydown\", onKey, true);\n      document.body.style.overflow = prevOverflow;\n      if (returnTo.current && returnTo.current.focus) returnTo.current.focus();\n    };\n  }, [onClose]);\n\n  return (\n    <div\n      className=\"ap-backdrop\"\n      onMouseDown={(e) => {\n        if (e.target === e.currentTarget) onClose?.();\n      }}\n    >\n      <div\n        className={`ap-modal${wide ? \" ap-modal-wide\" : \"\"}`}\n        role=\"dialog\"\n        aria-modal=\"true\"\n        aria-label={labelledBy ? undefined : title}\n        aria-labelledby={labelledBy}\n        ref={box}\n      >\n        {title ? (\n          <div className=\"ap-modal-head\">\n            <h2>{title}</h2>\n            <button type=\"button\" className=\"ap-modal-x\" onClick={onClose} aria-label=\"Close\">\n              <IconClose size={18} />\n            </button>\n          </div>\n        ) : null}\n        <div className=\"ap-modal-body\">{children}</div>\n        {footer ? <div className=\"ap-modal-foot\">{footer}</div> : null}\n      </div>\n    </div>\n  );\n}\n","components/app/ui/Toast.js":"\"use client\";\n\n// ===========================================================================\n// TOASTS\n// ---------------------------------------------------------------------------\n// Confirmation that something happened, without stealing focus. A shopkeeper\n// mid-bill must never have the keyboard taken away from them by a dialog\n// saying \"Saved\".\n// ===========================================================================\n\nimport { createContext, useCallback, useContext, useMemo, useRef, useState } from \"react\";\nimport { IconCheck, IconWarn } from \"../Icons\";\n\nconst Ctx = createContext({ toast: () => {}, error: () => {} });\n\nexport function useToast() {\n  return useContext(Ctx);\n}\n\nexport function ToastProvider({ children }) {\n  const [list, setList] = useState([]);\n  const seq = useRef(0);\n\n  const push = useCallback((message, kind) => {\n    if (!message) return;\n    const id = ++seq.current;\n    setList((prev) => [...prev, { id, message, kind }]);\n    // An error stays up longer - it may need reading twice.\n    const ms = kind === \"bad\" ? 5200 : 2600;\n    setTimeout(() => setList((prev) => prev.filter((t) => t.id !== id)), ms);\n  }, []);\n\n  const value = useMemo(\n    () => ({\n      toast: (m) => push(m, \"good\"),\n      error: (m) => push(m, \"bad\"),\n    }),\n    [push]\n  );\n\n  return (\n    <Ctx.Provider value={value}>\n      {children}\n      {/* aria-live so a screen reader announces it without a focus jump */}\n      <div className=\"ap-toasts\" role=\"status\" aria-live=\"polite\">\n        {list.map((t) => (\n          <div key={t.id} className={`ap-toast ap-toast-${t.kind}`}>\n            {t.kind === \"bad\" ? <IconWarn size={16} /> : <IconCheck size={16} />}\n            <span>{t.message}</span>\n          </div>\n        ))}\n      </div>\n    </Ctx.Provider>\n  );\n}\n","components/app/useShop.js":"\"use client\";\n\n// ===========================================================================\n// WHO IS SIGNED IN, AND WHICH SHOP\n// ---------------------------------------------------------------------------\n// The login screens and the account page already have an auth provider. The\n// app area needs exactly the same facts, so it reads from that one rather\n// than keeping a second idea of who is signed in - two sources of truth\n// about a session is how you end up billing into the wrong shop.\n//\n// The import is deliberately forgiving about the hook's name. The provider\n// may export useAuth, useAccount or a default; this picks whichever is\n// there, so the app area does not break over a naming difference.\n// ===========================================================================\n\nimport * as Provider from \"../account/AuthProvider\";\n\nfunction pickHook() {\n  for (const name of [\"useAuth\", \"useAccount\", \"useSession\", \"useUser\"]) {\n    if (typeof Provider[name] === \"function\") return Provider[name];\n  }\n  if (typeof Provider.default === \"function\") return Provider.default;\n  return null;\n}\n\nconst hook = pickHook();\n\n// Normalised, so a screen never has to guess whether the field is called\n// businessId or activeBusinessId.\nexport function useShop() {\n  const raw = hook ? hook() : {};\n  const state = raw || {};\n\n  const businesses = state.businesses || state.shops || [];\n  const businessId =\n    state.businessId ?? state.activeBusinessId ?? state.currentBusinessId ?? null;\n\n  const shop =\n    state.business ||\n    state.activeBusiness ||\n    businesses.find((b) => String(b.id) === String(businessId)) ||\n    businesses[0] ||\n    null;\n\n  return {\n    ...state,\n    user: state.user || null,\n    businesses,\n    businessId: businessId ?? (shop ? shop.id : null),\n    shop,\n    ready: state.ready !== false,\n    offline: Boolean(state.offline),\n    signedIn: Boolean(state.user),\n    // The shop's own state code decides CGST+SGST versus IGST on every bill\n    // it issues, so it is lifted out here where billing can reach it.\n    stateCode: shop ? shop.stateCode || shop.state_code || null : null,\n  };\n}\n\nexport default useShop;\n","lib/app-client.js":"// ===========================================================================\n// THE APP AREA'S WAY IN TO lib/api.js\n// ---------------------------------------------------------------------------\n// The login and the account pages already had a working api module before\n// the app area existed. Replacing it was a mistake - it exports things those\n// screens import, and dropping any of them breaks the build.\n//\n// So this sits on top of the original instead and leaves it alone. It works\n// out what that module offers and calls it accordingly, which means a\n// difference in how it is shaped - api.get versus a bare request, data\n// wrapped in { ok, data } or not - costs nothing here.\n//\n// Everything the app area sends to the server goes through this file. If the\n// api module is ever renamed or reshaped, this is the only place that needs\n// to know.\n// ===========================================================================\n\nimport * as ApiModule from \"./api\";\n\n// Copied into a plain object on purpose. Reading Api.something straight off\n// an import * namespace is checked at build time, and asking for a name that\n// module happens not to export fails the build outright - which defeats the\n// whole point of looking to see what is there. Spreading it first turns\n// those into ordinary property reads.\nconst Api = { ...ApiModule };\n\n// ---------------------------------------------------------------------------\n// the error type\n// ---------------------------------------------------------------------------\n// Use the original's if it has one, so an error thrown by the login screen\n// and an error thrown here are the same kind of thing and `instanceof` holds.\nclass LocalApiError extends Error {\n  constructor(message, { status = 0, code = \"error\", fields = null, body = null } = {}) {\n    super(message || \"Something went wrong.\");\n    this.name = \"ApiError\";\n    this.status = status;\n    this.code = code;\n    this.fields = fields;\n    this.body = body;\n  }\n\n  get isOffline() {\n    return this.code === \"network\";\n  }\n\n  get isAuth() {\n    return this.status === 401;\n  }\n\n  get isMissing() {\n    return this.status === 404;\n  }\n}\n\nexport const ApiError = Api.ApiError || LocalApiError;\n\n// ---------------------------------------------------------------------------\n// which business is active\n// ---------------------------------------------------------------------------\n// The original module keeps this, under one of several plausible shapes. It\n// is read rather than stored again here: two places remembering which shop\n// is open is how you end up billing into the wrong one.\nfunction currentBusinessId() {\n  const ab = Api.activeBusiness;\n  try {\n    if (ab == null) {\n      if (typeof Api.getBusinessId === \"function\") return Api.getBusinessId();\n      return undefined;\n    }\n    if (typeof ab === \"function\") return ab();\n    if (typeof ab === \"object\") {\n      if (typeof ab.get === \"function\") return ab.get();\n      if (ab.id !== undefined) return ab.id;\n      if (ab.value !== undefined) return ab.value;\n      return undefined;\n    }\n    return ab;\n  } catch {\n    return undefined;\n  }\n}\n\n// ---------------------------------------------------------------------------\n// the call\n// ---------------------------------------------------------------------------\n// The api object's own methods come first, because that is the surface the\n// rest of the site already uses and so the one certain to behave. A bare\n// request() is the fallback.\nfunction buildRequest() {\n  const obj = Api.api || Api.default;\n\n  if (obj && typeof obj === \"object\") {\n    const byMethod = {\n      GET: obj.get,\n      POST: obj.post,\n      PATCH: obj.patch,\n      PUT: obj.put,\n      DELETE: obj.del || obj.delete || obj.remove,\n    };\n    if (typeof byMethod.GET === \"function\" && typeof byMethod.POST === \"function\") {\n      return (method, path, options = {}) => {\n        const fn = byMethod[method];\n        if (typeof fn !== \"function\") {\n          throw new ApiError(`lib/api.js has no ${method.toLowerCase()} method.`, {\n            status: 405,\n            code: \"unsupported\",\n          });\n        }\n        // Reads take (path, options). Writes take (path, body, options).\n        return method === \"GET\" || method === \"DELETE\"\n          ? fn.call(obj, path, options)\n          : fn.call(obj, path, options.body, options);\n      };\n    }\n  }\n\n  const bare =\n    typeof Api.request === \"function\"\n      ? Api.request\n      : obj && typeof obj.request === \"function\"\n      ? obj.request.bind(obj)\n      : null;\n\n  if (bare) return (method, path, options = {}) => bare(method, path, options);\n\n  throw new ApiError(\n    \"lib/api.js does not export an api object or a request function the app area can use.\",\n    { code: \"config\" }\n  );\n}\n\nlet call = null;\n\n// Some api modules hand back the whole { ok, data } envelope and some have\n// already unwrapped it. Either is fine; this settles it in one place.\nfunction unwrap(value) {\n  if (\n    value &&\n    typeof value === \"object\" &&\n    !Array.isArray(value) &&\n    \"data\" in value &&\n    (\"ok\" in value || \"success\" in value)\n  ) {\n    return value.data;\n  }\n  return value;\n}\n\nasync function request(method, path, options = {}) {\n  if (!call) call = buildRequest();\n  const businessId = options.businessId !== undefined ? options.businessId : currentBusinessId();\n  const out = await call(method, path, businessId ? { ...options, businessId } : options);\n  return unwrap(out);\n}\n\nexport const api = {\n  get: (path, options) => request(\"GET\", path, options),\n  post: (path, body, options) => request(\"POST\", path, { ...(options || {}), body }),\n  patch: (path, body, options) => request(\"PATCH\", path, { ...(options || {}), body }),\n  put: (path, body, options) => request(\"PUT\", path, { ...(options || {}), body }),\n  del: (path, options) => request(\"DELETE\", path, options),\n  request,\n};\n\n// ---------------------------------------------------------------------------\n// small helpers\n// ---------------------------------------------------------------------------\n// A list endpoint may answer with a bare array or with an object carrying a\n// count for paging. Flatten both so a screen can just map over the result.\nexport function rowsOf(result) {\n  if (!result) return [];\n  if (Array.isArray(result)) return result;\n  for (const key of [\"rows\", \"items\", \"data\", \"results\", \"list\"]) {\n    if (Array.isArray(result[key])) return result[key];\n  }\n  return [];\n}\n\nexport function totalOf(result, fallback) {\n  if (result && typeof result === \"object\" && !Array.isArray(result)) {\n    for (const key of [\"total\", \"count\", \"totalCount\"]) {\n      if (typeof result[key] === \"number\") return result[key];\n    }\n  }\n  return fallback == null ? rowsOf(result).length : fallback;\n}\n\n// A query string that leaves out anything empty, so we never send ?search=\nexport function qs(params) {\n  const sp = new URLSearchParams();\n  for (const [k, v] of Object.entries(params || {})) {\n    if (v === undefined || v === null || v === \"\") continue;\n    sp.set(k, String(v));\n  }\n  const s = sp.toString();\n  return s ? `?${s}` : \"\";\n}\n\nexport default api;\n","lib/gst-calc.js":"// ===========================================================================\n// GST, WORKED OUT IN THE BROWSER\n// ---------------------------------------------------------------------------\n// This mirrors the backend's computeLine/computeTotals so the total updates\n// as the shopkeeper types, without a round trip per keystroke.\n//\n// IMPORTANT: the backend is the authority. This is a preview. Once a bill is\n// saved, every screen shows the amounts the server sent back, never these.\n// If the two ever disagree, the server is right and this file has a bug.\n//\n// The rules, in plain terms:\n//   - supplier's state == place of supply  ->  CGST + SGST, half each\n//   - different states                     ->  IGST, the whole rate\n//   - a walk-in customer with no state     ->  treated as same-state\n//   - the grand total is rounded to the rupee, and the difference is shown\n//     as its own \"Round off\" line, because that is what the law expects\n// ===========================================================================\n\n// Half of an odd number of paise cannot be split evenly. The backend gives\n// the extra paisa to CGST and this does the same, so the two agree exactly.\nexport function halve(paise) {\n  const second = Math.floor(paise / 2);\n  return [paise - second, second];\n}\n\nexport function roundToRupee(paise) {\n  const rounded = Math.round(paise / 100) * 100;\n  return { rounded, roundOff: rounded - paise };\n}\n\nexport function isInterState(supplierStateCode, placeOfSupply) {\n  // No place of supply means a walk-in sale over the counter, which is\n  // always within the state the shop is in.\n  if (!placeOfSupply) return false;\n  if (!supplierStateCode) return false;\n  return String(supplierStateCode) !== String(placeOfSupply);\n}\n\n// ---------------------------------------------------------------------------\n// one line\n// ---------------------------------------------------------------------------\n// line: { quantity, ratePaise, taxRate, discountPercent, discountPaise,\n//         taxIncluded }\n//\n// taxIncluded matters more than it looks. A kirana shop's MRP already has\n// the tax in it: a 450 rupee bag of rice at 5% is 428.57 + 21.43, not\n// 450 + 22.50. Getting this wrong makes every bill in the shop wrong.\nexport function computeLine(line, { interState = false } = {}) {\n  const quantity = Number(line.quantity) || 0;\n  const ratePaise = Math.round(Number(line.ratePaise) || 0);\n  const taxRate = Number(line.taxRate) || 0;\n\n  const gross = Math.round(quantity * ratePaise);\n\n  let discount = 0;\n  if (line.discountPercent) {\n    discount = Math.round((gross * Number(line.discountPercent)) / 100);\n  } else if (line.discountPaise) {\n    discount = Math.round(Number(line.discountPaise));\n  }\n  if (discount > gross) discount = gross;\n\n  const afterDiscount = gross - discount;\n\n  let taxable;\n  let tax;\n  if (line.taxIncluded && taxRate > 0) {\n    // Work backwards out of the inclusive amount.\n    taxable = Math.round((afterDiscount * 100) / (100 + taxRate));\n    tax = afterDiscount - taxable;\n  } else {\n    taxable = afterDiscount;\n    tax = Math.round((taxable * taxRate) / 100);\n  }\n\n  let cgst = 0;\n  let sgst = 0;\n  let igst = 0;\n  if (interState) {\n    igst = tax;\n  } else {\n    [cgst, sgst] = halve(tax);\n  }\n\n  return {\n    quantity,\n    ratePaise,\n    taxRate,\n    gross,\n    discount,\n    taxable,\n    tax,\n    cgst,\n    sgst,\n    igst,\n    total: taxable + tax,\n  };\n}\n\n// ---------------------------------------------------------------------------\n// the whole bill\n// ---------------------------------------------------------------------------\n// extraDiscountPaise is the \"take fifty off the whole bill\" that happens at\n// the counter. It is applied to the taxable value of each line in\n// proportion, because a flat discount after tax would make the GST on the\n// bill wrong - and that is the number the department checks.\nexport function computeTotals(lines, options = {}) {\n  const { interState = false, extraDiscountPaise = 0, roundOffEnabled = true } = options;\n\n  const computed = lines.map((l) => computeLine(l, { interState }));\n\n  const grossSum = computed.reduce((a, l) => a + l.gross, 0);\n  const lineDiscountSum = computed.reduce((a, l) => a + l.discount, 0);\n  const taxableBeforeExtra = computed.reduce((a, l) => a + l.taxable, 0);\n\n  let rows = computed;\n  let extra = Math.round(Number(extraDiscountPaise) || 0);\n  if (extra > taxableBeforeExtra) extra = taxableBeforeExtra;\n\n  if (extra > 0 && taxableBeforeExtra > 0) {\n    // Hand out the discount line by line, keeping a running remainder so the\n    // paise lost to rounding land on the last line instead of vanishing.\n    let left = extra;\n    rows = computed.map((l, i) => {\n      const share = i === computed.length - 1 ? left : Math.round((extra * l.taxable) / taxableBeforeExtra);\n      const applied = Math.min(share, l.taxable, left);\n      left -= applied;\n      const taxable = l.taxable - applied;\n      const tax = Math.round((taxable * l.taxRate) / 100);\n      let cgst = 0;\n      let sgst = 0;\n      let igst = 0;\n      if (interState) igst = tax;\n      else [cgst, sgst] = halve(tax);\n      return { ...l, extraDiscount: applied, taxable, tax, cgst, sgst, igst, total: taxable + tax };\n    });\n  }\n\n  const taxable = rows.reduce((a, l) => a + l.taxable, 0);\n  const cgst = rows.reduce((a, l) => a + l.cgst, 0);\n  const sgst = rows.reduce((a, l) => a + l.sgst, 0);\n  const igst = rows.reduce((a, l) => a + l.igst, 0);\n  const tax = cgst + sgst + igst;\n  const beforeRound = taxable + tax;\n\n  const { rounded, roundOff } = roundOffEnabled\n    ? roundToRupee(beforeRound)\n    : { rounded: beforeRound, roundOff: 0 };\n\n  // One row per tax rate, which is how the printed bill has to show it.\n  const byRate = new Map();\n  for (const l of rows) {\n    if (!l.taxable && !l.tax) continue;\n    const key = l.taxRate;\n    const b = byRate.get(key) || { taxRate: key, taxable: 0, cgst: 0, sgst: 0, igst: 0, tax: 0 };\n    b.taxable += l.taxable;\n    b.cgst += l.cgst;\n    b.sgst += l.sgst;\n    b.igst += l.igst;\n    b.tax += l.tax;\n    byRate.set(key, b);\n  }\n\n  return {\n    lines: rows,\n    interState,\n    gross: grossSum,\n    lineDiscount: lineDiscountSum,\n    extraDiscount: extra,\n    discount: lineDiscountSum + extra,\n    taxable,\n    cgst,\n    sgst,\n    igst,\n    tax,\n    beforeRound,\n    roundOff,\n    total: rounded,\n    taxBreakup: [...byRate.values()].sort((a, b) => a.taxRate - b.taxRate),\n  };\n}\n\n// The rates a shop in India can actually pick. Anything else and the bill\n// will be questioned.\nexport const TAX_RATES = [\n  { value: 0, label: \"0% (exempt)\" },\n  { value: 0.25, label: \"0.25%\" },\n  { value: 3, label: \"3%\" },\n  { value: 5, label: \"5%\" },\n  { value: 12, label: \"12%\" },\n  { value: 18, label: \"18%\" },\n  { value: 28, label: \"28%\" },\n];\n","lib/gst-states.js":"// ===========================================================================\n// STATES AND UNION TERRITORIES, WITH THEIR GST CODES\n// ---------------------------------------------------------------------------\n// The two-digit code is the first two characters of every GSTIN, and it is\n// what decides whether a bill carries CGST + SGST or IGST. So this list is\n// not decoration - get a code wrong and every bill to that customer has the\n// wrong tax on it.\n//\n// Ordered alphabetically because that is how somebody looks for their state\n// in a dropdown, not by code.\n// ===========================================================================\n\nexport const GST_STATES = [\n  { code: \"35\", name: \"Andaman and Nicobar Islands\" },\n  { code: \"37\", name: \"Andhra Pradesh\" },\n  { code: \"12\", name: \"Arunachal Pradesh\" },\n  { code: \"18\", name: \"Assam\" },\n  { code: \"10\", name: \"Bihar\" },\n  { code: \"04\", name: \"Chandigarh\" },\n  { code: \"22\", name: \"Chhattisgarh\" },\n  { code: \"26\", name: \"Dadra and Nagar Haveli and Daman and Diu\" },\n  { code: \"07\", name: \"Delhi\" },\n  { code: \"30\", name: \"Goa\" },\n  { code: \"24\", name: \"Gujarat\" },\n  { code: \"06\", name: \"Haryana\" },\n  { code: \"02\", name: \"Himachal Pradesh\" },\n  { code: \"01\", name: \"Jammu and Kashmir\" },\n  { code: \"20\", name: \"Jharkhand\" },\n  { code: \"29\", name: \"Karnataka\" },\n  { code: \"32\", name: \"Kerala\" },\n  { code: \"38\", name: \"Ladakh\" },\n  { code: \"31\", name: \"Lakshadweep\" },\n  { code: \"23\", name: \"Madhya Pradesh\" },\n  { code: \"27\", name: \"Maharashtra\" },\n  { code: \"14\", name: \"Manipur\" },\n  { code: \"17\", name: \"Meghalaya\" },\n  { code: \"15\", name: \"Mizoram\" },\n  { code: \"13\", name: \"Nagaland\" },\n  { code: \"21\", name: \"Odisha\" },\n  { code: \"97\", name: \"Other Territory\" },\n  { code: \"34\", name: \"Puducherry\" },\n  { code: \"03\", name: \"Punjab\" },\n  { code: \"08\", name: \"Rajasthan\" },\n  { code: \"11\", name: \"Sikkim\" },\n  { code: \"33\", name: \"Tamil Nadu\" },\n  { code: \"36\", name: \"Telangana\" },\n  { code: \"16\", name: \"Tripura\" },\n  { code: \"09\", name: \"Uttar Pradesh\" },\n  { code: \"05\", name: \"Uttarakhand\" },\n  { code: \"19\", name: \"West Bengal\" },\n];\n\nconst BY_CODE = new Map(GST_STATES.map((s) => [s.code, s.name]));\n\nexport function stateName(code) {\n  if (!code) return \"\";\n  return BY_CODE.get(String(code).padStart(2, \"0\")) || \"\";\n}\n\n// ---------------------------------------------------------------------------\n// GSTIN\n// ---------------------------------------------------------------------------\n// Shape only. A GSTIN that passes this is still not proof the business\n// exists or is active - only the GST portal can say that. But catching a\n// typo here saves a rejected invoice later.\n//\n// 15 characters: 2 state code, 10 PAN, 1 entity number, 1 \"Z\", 1 check digit.\nconst GSTIN_RE = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;\nconst ALPHABET = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\nexport function gstinCheckDigit(first14) {\n  // The portal's own algorithm: each character's value, doubled on every\n  // second position from the left, folded back into base 36.\n  let sum = 0;\n  for (let i = 0; i < 14; i++) {\n    const value = ALPHABET.indexOf(first14[i]);\n    if (value < 0) return null;\n    const factor = i % 2 === 0 ? 1 : 2;\n    const product = value * factor;\n    sum += Math.floor(product / 36) + (product % 36);\n  }\n  const remainder = sum % 36;\n  return ALPHABET[(36 - remainder) % 36];\n}\n\nexport function isValidGstin(value) {\n  const s = String(value || \"\").trim().toUpperCase();\n  if (s.length !== 15) return false;\n  if (!GSTIN_RE.test(s)) return false;\n  if (!BY_CODE.has(s.slice(0, 2))) return false;\n  const expected = gstinCheckDigit(s.slice(0, 14));\n  return expected !== null && expected === s[14];\n}\n\nexport function stateCodeFromGstin(value) {\n  const s = String(value || \"\").trim();\n  if (s.length < 2) return \"\";\n  return BY_CODE.has(s.slice(0, 2)) ? s.slice(0, 2) : \"\";\n}\n","lib/money.js":"// ===========================================================================\n// MONEY\n// ---------------------------------------------------------------------------\n// The backend stores every amount as an integer number of paise in a BIGINT,\n// and so does this file. 0.1 + 0.2 is not 0.3 in a browser either, and a\n// shopkeeper checking a bill against the cash in the drawer will find the\n// missing paisa.\n//\n// Rule: paise inside, rupees only at the edges - what the user types in and\n// what gets printed out.\n// ===========================================================================\n\nexport function toPaise(rupees) {\n  const n = typeof rupees === \"string\" ? Number(rupees.replace(/,/g, \"\").trim()) : rupees;\n  if (typeof n !== \"number\" || !Number.isFinite(n)) return 0;\n  // Multiply first, then round. Rounding a float loses a paisa: 19.99 * 100\n  // comes out as 1998.9999999999998, which truncates to 1998.\n  return Math.round(n * 100);\n}\n\nexport function toRupees(paise) {\n  return (Number(paise) || 0) / 100;\n}\n\n// 152450 -> \"1,524.50\". Indian grouping: last three digits, then pairs.\nexport function formatPaise(paise, { decimals = true } = {}) {\n  const n = Number(paise) || 0;\n  const negative = n < 0;\n  const abs = Math.abs(n);\n  const whole = Math.floor(abs / 100);\n  const fraction = abs % 100;\n\n  let s = String(whole);\n  if (s.length > 3) {\n    const last3 = s.slice(-3);\n    let rest = s.slice(0, -3);\n    const pairs = [];\n    while (rest.length > 2) {\n      pairs.unshift(rest.slice(-2));\n      rest = rest.slice(0, -2);\n    }\n    if (rest) pairs.unshift(rest);\n    s = `${pairs.join(\",\")},${last3}`;\n  }\n\n  const out = decimals || fraction ? `${s}.${String(fraction).padStart(2, \"0\")}` : s;\n  return negative ? `-${out}` : out;\n}\n\n// With the rupee sign. Used everywhere on screen.\nexport function rupees(paise, options) {\n  return `₹${formatPaise(paise, options)}`;\n}\n\n// Short form for dashboard tiles, where the exact paisa is noise.\n// 4523400 -> \"45,234\" ; 125000000 -> \"1.25 L\" ; 45000000000 -> \"4.50 Cr\"\nexport function rupeesShort(paise) {\n  const n = Math.abs(Number(paise) || 0);\n  const sign = Number(paise) < 0 ? \"-\" : \"\";\n  if (n >= 10000000 * 100) return `${sign}₹${(n / (10000000 * 100)).toFixed(2)} Cr`;\n  if (n >= 100000 * 100) return `${sign}₹${(n / (100000 * 100)).toFixed(2)} L`;\n  return `${sign}₹${formatPaise(n, { decimals: false })}`;\n}\n\n// Quantities are DECIMAL(12,3) in the database - 1.5 kg is a real sale.\n// Trailing zeros are dropped so a count of pieces reads as \"4\", not \"4.000\".\nexport function formatQty(qty) {\n  const n = Number(qty) || 0;\n  const s = n.toFixed(3);\n  return s.replace(/\\.?0+$/, \"\");\n}\n\nexport function toQty(value) {\n  const n = typeof value === \"string\" ? Number(value.trim()) : value;\n  if (typeof n !== \"number\" || !Number.isFinite(n)) return 0;\n  return Number(n.toFixed(3));\n}\n\n// ---------------------------------------------------------------------------\n// amount in words\n// ---------------------------------------------------------------------------\n// A GST invoice is expected to carry the total in words, and in India that\n// means the lakh/crore system, not millions.\nconst ONES = [\n  \"\", \"One\", \"Two\", \"Three\", \"Four\", \"Five\", \"Six\", \"Seven\", \"Eight\", \"Nine\",\n  \"Ten\", \"Eleven\", \"Twelve\", \"Thirteen\", \"Fourteen\", \"Fifteen\", \"Sixteen\",\n  \"Seventeen\", \"Eighteen\", \"Nineteen\",\n];\nconst TENS = [\"\", \"\", \"Twenty\", \"Thirty\", \"Forty\", \"Fifty\", \"Sixty\", \"Seventy\", \"Eighty\", \"Ninety\"];\n\nfunction twoDigits(n) {\n  if (n < 20) return ONES[n];\n  const t = TENS[Math.floor(n / 10)];\n  const o = ONES[n % 10];\n  return o ? `${t} ${o}` : t;\n}\n\nfunction threeDigits(n) {\n  const h = Math.floor(n / 100);\n  const rest = n % 100;\n  const parts = [];\n  if (h) parts.push(`${ONES[h]} Hundred`);\n  if (rest) parts.push(twoDigits(rest));\n  return parts.join(\" \");\n}\n\nfunction wholeToWords(n) {\n  if (n === 0) return \"Zero\";\n  const crore = Math.floor(n / 10000000);\n  const lakh = Math.floor((n % 10000000) / 100000);\n  const thousand = Math.floor((n % 100000) / 1000);\n  const rest = n % 1000;\n\n  const parts = [];\n  if (crore) parts.push(`${wholeToWords(crore)} Crore`);\n  if (lakh) parts.push(`${twoDigits(lakh)} Lakh`);\n  if (thousand) parts.push(`${twoDigits(thousand)} Thousand`);\n  if (rest) parts.push(threeDigits(rest));\n  return parts.join(\" \");\n}\n\nexport function paiseToWords(paise) {\n  const n = Math.abs(Number(paise) || 0);\n  const whole = Math.floor(n / 100);\n  const fraction = n % 100;\n  let out = `${wholeToWords(whole)} Rupees`;\n  if (fraction) out += ` and ${twoDigits(fraction)} Paise`;\n  return `${out} Only`;\n}\n\n// ---------------------------------------------------------------------------\n// dates\n// ---------------------------------------------------------------------------\n// Indian shops read dates as DD-MM-YYYY. The server speaks YYYY-MM-DD.\nexport function today() {\n  const d = new Date();\n  const p = (x) => String(x).padStart(2, \"0\");\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;\n}\n\nexport function daysAgo(n) {\n  const d = new Date();\n  d.setDate(d.getDate() - n);\n  const p = (x) => String(x).padStart(2, \"0\");\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;\n}\n\nexport function formatDate(value) {\n  if (!value) return \"\";\n  const s = String(value).slice(0, 10);\n  const [y, m, d] = s.split(\"-\");\n  if (!y || !m || !d) return s;\n  return `${d}-${m}-${y}`;\n}\n\nconst MONTHS = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"];\n\nexport function formatDateLong(value) {\n  if (!value) return \"\";\n  const s = String(value).slice(0, 10);\n  const [y, m, d] = s.split(\"-\");\n  if (!y || !m || !d) return s;\n  return `${Number(d)} ${MONTHS[Number(m) - 1] || m} ${y}`;\n}\n\n// \"3 days ago\" reads faster than a date when scanning who owes money.\nexport function ageInDays(value) {\n  if (!value) return 0;\n  const then = new Date(`${String(value).slice(0, 10)}T00:00:00`);\n  const now = new Date();\n  now.setHours(0, 0, 0, 0);\n  return Math.max(0, Math.round((now - then) / 86400000));\n}\n\nexport function relativeDay(value) {\n  const days = ageInDays(value);\n  if (days === 0) return \"Today\";\n  if (days === 1) return \"Yesterday\";\n  if (days < 7) return `${days} days ago`;\n  return formatDate(value);\n}\n","lib/units.js":"// ===========================================================================\n// UNITS\n// ---------------------------------------------------------------------------\n// These are the UQC codes - the Unit Quantity Codes the GST portal accepts.\n// Using the real codes now means an e-invoice or a GSTR-1 export later does\n// not need every item in the shop re-tagged.\n// ===========================================================================\n\nexport const UNITS = [\n  { code: \"PCS\", label: \"Piece\", short: \"pcs\" },\n  { code: \"NOS\", label: \"Numbers\", short: \"nos\" },\n  { code: \"KGS\", label: \"Kilogram\", short: \"kg\" },\n  { code: \"GMS\", label: \"Gram\", short: \"g\" },\n  { code: \"LTR\", label: \"Litre\", short: \"ltr\" },\n  { code: \"MLT\", label: \"Millilitre\", short: \"ml\" },\n  { code: \"BAG\", label: \"Bag\", short: \"bag\" },\n  { code: \"BOX\", label: \"Box\", short: \"box\" },\n  { code: \"BTL\", label: \"Bottle\", short: \"btl\" },\n  { code: \"PAC\", label: \"Packet\", short: \"pkt\" },\n  { code: \"DOZ\", label: \"Dozen\", short: \"dz\" },\n  { code: \"MTR\", label: \"Metre\", short: \"mtr\" },\n  { code: \"CMS\", label: \"Centimetre\", short: \"cm\" },\n  { code: \"SQF\", label: \"Square feet\", short: \"sqft\" },\n  { code: \"SQM\", label: \"Square metre\", short: \"sqm\" },\n  { code: \"TON\", label: \"Tonne\", short: \"ton\" },\n  { code: \"QTL\", label: \"Quintal\", short: \"qtl\" },\n  { code: \"PAIR\", label: \"Pair\", short: \"pair\" },\n  { code: \"SET\", label: \"Set\", short: \"set\" },\n  { code: \"ROL\", label: \"Roll\", short: \"roll\" },\n  { code: \"TUB\", label: \"Tube\", short: \"tube\" },\n  { code: \"CAN\", label: \"Can\", short: \"can\" },\n  { code: \"OTH\", label: \"Other\", short: \"unit\" },\n];\n\nconst BY_CODE = new Map(UNITS.map((u) => [u.code, u]));\n\nexport function unitShort(code) {\n  const u = BY_CODE.get(String(code || \"\").toUpperCase());\n  return u ? u.short : String(code || \"\").toLowerCase() || \"unit\";\n}\n\nexport function unitLabel(code) {\n  const u = BY_CODE.get(String(code || \"\").toUpperCase());\n  return u ? u.label : code || \"Unit\";\n}\n\n// How a sale is settled. \"Credit\" is not a payment mode as such - it means\n// nothing was taken and the customer owes it - but it belongs in the same\n// list because that is how it is chosen at the counter.\nexport const PAYMENT_MODES = [\n  { value: \"cash\", label: \"Cash\" },\n  { value: \"upi\", label: \"UPI\" },\n  { value: \"card\", label: \"Card\" },\n  { value: \"bank\", label: \"Bank transfer\" },\n  { value: \"cheque\", label: \"Cheque\" },\n  { value: \"other\", label: \"Other\" },\n];\n\nexport function modeLabel(value) {\n  const m = PAYMENT_MODES.find((x) => x.value === value);\n  return m ? m.label : value || \"\";\n}\n"};

let written = 0;
let same = 0;
for (const [rel, body] of Object.entries(FILES)) {
  const abs = path.join(ROOT, rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  if (fs.existsSync(abs)) {
    if (fs.readFileSync(abs, "utf8") === body) { same++; continue; }
    fs.copyFileSync(abs, abs + ".bak");
  }
  fs.writeFileSync(abs, body);
  console.log("WRITE " + rel);
  written++;
}
if (same) console.log("OK    " + same + " files already current.");
console.log("");
console.log(written === 0 ? "Nothing to change." : "Done - " + written + " files written.");

// ---------------------------------------------------------------------------
// the two stylesheets
// ---------------------------------------------------------------------------
const cssPath = path.join(ROOT, "app/globals.css");
const imports = ['@import "../components/app/app.css";', '@import "../components/app/print.css";'];

if (!fs.existsSync(cssPath)) {
  console.log("");
  console.log("SKIP  app/globals.css - not found. Add these two lines by hand:");
  for (const line of imports) console.log("      " + line);
} else {
  let s = fs.readFileSync(cssPath, "utf8");
  const missing = imports.filter((line) => !s.includes(line.slice(9, -2)));
  if (!missing.length) {
    console.log("OK    app/globals.css - both imports already there.");
  } else {
    const found = [...s.matchAll(/^@import[^\n]*\n/gm)];
    const block = missing.join("\n") + "\n";
    if (found.length) {
      const last = found[found.length - 1];
      const at = last.index + last[0].length;
      s = s.slice(0, at) + block + s.slice(at);
    } else {
      s = block + s;
    }
    fs.copyFileSync(cssPath, cssPath + ".bak");
    fs.writeFileSync(cssPath, s);
    console.log("PATCH app/globals.css - added " + missing.length + " import(s)");
  }
}

